function getStoredRecentReactions(): string[] {
  try {
    const raw = typeof window !== "undefined" ? localStorage.getItem("agent360_recent_reactions") : null;
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        const merged = Array.from(new Set([...parsed, ...DEFAULT_REACTIONS]));
        return merged.slice(0, 8);
      }
    }
  } catch {}
  return DEFAULT_REACTIONS;
}

function saveStoredRecentReaction(emoji: string) {
  try {
    const current = getStoredRecentReactions();
    const updated = [emoji, ...current.filter((e) => e !== emoji)].slice(0, 8);
    localStorage.setItem("agent360_recent_reactions", JSON.stringify(updated));
  } catch {}
}

const QUICK_REACTIONS = ["👍", "❤️", "🔥", "🎉", "👀", "🚀"];

function stripSharedRoomContext(text: string): string {
  if (!text) return "";
  let cleaned = text.replace(/^\s*QUESTION_FOR_PARENT:\s*/i, "");
  cleaned = cleaned.replace(/\[IMPLICIT_REACTION_FEEDBACK[^\]]*\][\s\S]*?\[\/IMPLICIT_REACTION_FEEDBACK\]/gi, "").trim();
  if (/^BuildSpecialtySynthesisFallback\(collab,\s*objective\)$/i.test(cleaned)) {
    cleaned = "**[Đóng góp chuyên môn từ Room]**\n- Đã đồng bộ phân tích chuyên môn và chuyển về Chủ session tổng hợp kết quả cuối.";
  }
  let idx = cleaned.indexOf("[SHARED SESSION ROOM CONTEXT]");
  if (idx < 0) idx = cleaned.indexOf("[AGENTTEAMS COLLABORATION ROOM");
  const skyerAwareIdx = cleaned.indexOf("[SKYER PLATFORM CHANNEL & APP CONNECTION AWARENESS]");
  if (skyerAwareIdx >= 0 && (idx < 0 || skyerAwareIdx < idx)) idx = skyerAwareIdx;
  if (idx < 0) return cleaned;
  let head = cleaned.slice(0, idx).trimEnd();
  const tail = cleaned.slice(idx);
  const tailAttachments = tail.match(/\[Attached File:\s*[^\n\r]+?\s*\([^()\n\r]+\)\]/gi) || [];
  for (const att of tailAttachments) {
    if (!head.includes(att)) {
      head = head ? `${head}\n\n${att}` : att;
    }
  }
  return head;
}

function stabilizeStreamingMarkdown(text: string, isActivelyStreaming: boolean): string {
  if (!text || !isActivelyStreaming) return text;
  let out = text;
  const boldCount = (out.match(/\*\*/g) || []).length;
  if (boldCount % 2 === 1 && !out.endsWith("*")) {
    out += "**";
  }
  const lastLine = out.split("\n").pop() || "";
  const inlineTickCount = (lastLine.replace(/```/g, "").match(/`/g) || []).length;
  if (inlineTickCount % 2 === 1) {
    out += "`";
  }
  return out;
}

let _composerMeasureCtx: CanvasRenderingContext2D | null = null;
function measureComposerTextWidthPx(text: string): number {
  if (typeof document !== "undefined") {
    try {
      if (!_composerMeasureCtx) {
        const canvas = document.createElement("canvas");
        _composerMeasureCtx = canvas.getContext("2d");
      }
      if (_composerMeasureCtx) {
        const isSmall = typeof window !== "undefined" && window.innerWidth < 640;
        _composerMeasureCtx.font = `400 ${isSmall ? "16px" : "14.5px"} Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
        return _composerMeasureCtx.measureText(text).width;
      }
    } catch {}
  }
  let fallbackPx = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if ("ilI|!.,:;'\"`()[]{} ".includes(ch)) fallbackPx += 4.2;
    else if ("frt".includes(ch)) fallbackPx += 5.2;
    else if ("wmWM@#%&".includes(ch)) fallbackPx += 11.5;
    else fallbackPx += 7.5;
  }
  return fallbackPx;
}


function isColorBright(hexColor?: string): boolean {
  if (!hexColor || !hexColor.startsWith("#")) return false;
  const hex = hexColor.replace("#", "");
  const r = parseInt(hex.substring(0, 2), 16) || 0;
  const g = parseInt(hex.substring(2, 4), 16) || 0;
  const b = parseInt(hex.substring(4, 6), 16) || 0;
  // Perceived brightness formula (YIQ)
  const yiq = (r * 299 + g * 587 + b * 114) / 1000;
  return yiq >= 170;
}

function computeIsMultilineComposer(text: string, measuredWidth?: number): boolean {
  if (!text) return false;
  if (text.includes("\n")) return true;

  const isSmallScreen = typeof window !== "undefined" && window.innerWidth < 640;
  if (isSmallScreen && text.length > 26) return true;
  if (!isSmallScreen && text.length > 62) return true;

  const chromeDeductionPx = isSmallScreen ? 142 : 120;
  if (measuredWidth && measuredWidth > 120) {
    const availableTextPx = Math.max(40, measuredWidth - chromeDeductionPx);
    const totalTextPx = measureComposerTextWidthPx(text);
    if (totalTextPx >= availableTextPx) return true;

    if (text.includes(" ")) {
      const words = text.split(" ");
      let currentLinePx = 0;
      const spacePx = measureComposerTextWidthPx(" ");
      for (let i = 0; i < words.length; i++) {
        const word = words[i];
        if (!word) {
          currentLinePx += spacePx;
          continue;
        }
        const wordPx = measureComposerTextWidthPx(word);
        if (currentLinePx === 0) {
          if (wordPx > availableTextPx) return true;
          currentLinePx = wordPx;
        } else {
          if (currentLinePx + spacePx + wordPx > availableTextPx) return true;
          currentLinePx += spacePx + wordPx;
        }
      }
    }
    return false;
  }

  if (typeof window === "undefined") return text.length > 45;
  const w = window.innerWidth;
  const threshold = w < 480 ? 24 : w < 640 ? 30 : w < 1024 ? 44 : 60;
  return text.length > threshold;
}

function computeChatTitleMarqueeDuration(title: string): string {
  if (!title) return "4s";
  // Maintain a strictly constant, comfortable steady slide velocity (~24px/s) across all titles
  const approxWidth = title.length * 7.5;
  const overflowPx = Math.max(25, approxWidth - 110);
  const durSec = Math.max(2.8, overflowPx / 24);
  return durSec.toFixed(1) + "s";
}

function detectSessionPronouns(
  messages: ChatMessage[],
  currentMsg: ChatMessage
): { self: string; user: string; lang: "vi" | "en" | "other" } {
  const sampleTexts: string[] = [];
  for (let i = Math.max(0, messages.length - 8); i < messages.length; i++) {
    if (messages[i]?.content) sampleTexts.push(messages[i].content);
  }
  if (currentMsg?.content) sampleTexts.push(currentMsg.content);
  if (currentMsg?.reasoning) sampleTexts.push(currentMsg.reasoning);
  const combined = sampleTexts.join("\n");

  const hasViChars = /[àáảãạăắằẳẵặâấầẩẫậèéẻẽẹêếềểễệìíỉĩịòóỏõọôốồổỗộơớờởỡợùúủũụưứừửữựỳýỷỹỵđ]/i.test(combined);
  if (!hasViChars) {
    if (/\b(the|and|for|you|please|check|what|how|list|report|let)\b/i.test(combined)) {
      return { self: "I", user: "you", lang: "en" };
    }
    return { self: "", user: "", lang: "other" };
  }

  let user = "anh";
  if (/\bsếp\b/i.test(combined) && !/\b(anh|chị)\b/i.test(combined)) {
    user = "sếp";
  } else if (/\bchị\b/i.test(combined) && !/\banh\b/i.test(combined)) {
    user = "chị";
  } else if (/\b(thầy|cô)\b/i.test(combined) && !/\b(anh|chị)\b/i.test(combined)) {
    user = /\bcô\b/i.test(combined) ? "cô" : "thầy";
  } else if (/\b(bác|chú)\b/i.test(combined) && !/\b(anh|chị)\b/i.test(combined)) {
    user = /\bbác\b/i.test(combined) ? "bác" : "chú";
  } else if (/\bbạn\b/i.test(combined) && !/\b(anh|chị)\b/i.test(combined)) {
    user = "bạn";
  }

  let self = "em";
  if (user === "bạn") {
    self = /\btôi\b/i.test(combined) ? "tôi" : "mình";
  } else if (user === "bác" || user === "chú") {
    self = /\bcon\b/i.test(combined) ? "con" : "cháu";
  }
  return { self, user, lang: "vi" };
}

function transformReasonStepToLeadIn(
  rawStepText: string,
  pronouns: { self: string; user: string; lang: "vi" | "en" | "other" },
  isStepComplete: boolean
): string | null {
  if (!rawStepText) return null;
  const cleaned = rawStepText
    .replace(/^\s*\[LEAD_IN\]:?\s*/i, "")
    .replace(/\b[a-z0-9]+__[a-z0-9_]+\b/gi, "")
    .trim();
  if (!cleaned) return null;

  const lines = cleaned
    .split(/\n+/)
    .map((l) => l.trim())
    .filter(
      (l) =>
        l.length > 0 &&
        !/^(?:đang cân nhắc giữa|quyết định gọi|theo chỉ dẫn trong profile|according to my|bước \d)/i.test(l)
    );
  if (lines.length === 0) return null;

  const firstLine = lines[0];
  const firstSentence = firstLine.split(/(?<=[.!?])\s+/)[0]?.trim() || firstLine;
  if (!isStepComplete && firstSentence.length < 28 && !/[.!?]$/.test(firstSentence)) {
    return null;
  }

  const { self, user, lang } = pronouns;
  if (lang === "other") {
    return firstSentence.length <= 240 ? firstSentence : null;
  }

  if (lang === "en") {
    const en = firstSentence.replace(/[.]+$/, "").trim();
    const mUser = en.match(/^(?:the\s+user|user)\s+(?:wants|asked|is\s+asking|needs|requested)\s+to\s+(.+)$/i);
    if (mUser) return `Let me ${mUser[1]} for you.`;
    const mNeed = en.match(/^(?:need\s+to|must|should)\s+(.+)$/i);
    if (mNeed) return `Let me ${mNeed[1]} for you.`;
    const mDoing = en.match(/^((?:checking|searching|querying|fetching|running|preparing)\s+.+)$/i);
    if (mDoing) return `I'm ${mDoing[1].charAt(0).toLowerCase() + mDoing[1].slice(1)} for you...`;
    if (/^(?:let\s+me|i'll|i\s+will|i'm|i\s+am)\b/i.test(en)) return `${en}.`;
    return null;
  }

  const capSelf = self.charAt(0).toUpperCase() + self.slice(1);
  let body = firstSentence.replace(/[.!…]+$/, "").trim();
  body = body.replace(/\s+(?:của|cho)\s+(?:người\s+dùng|khách\s+hàng)\b/gi, "");

  // 1. Already written in first-person conversational style by SOUL.md contract
  if (new RegExp(`^(?:để\\s+${self}|${self}\\s+(?:đang|vừa|sẽ|tiếp\\s+tục|kiểm\\s+tra|rà\\s+soát|đối\\s+chiếu|xin))\\b`, "i").test(body)) {
    return `${body}.`;
  }

  const endsWithQuestionParticle = (s: string) =>
    /\b(?:không|chưa|chưa\s+nhỉ|bao\s+nhiêu|thế\s+nào|ra\s+sao|như\s+thế\s+nào|ở\s+đâu|gì|nào)$/i.test(s.trim());

  const attachForUser = (act: string, suffix: string) => {
    const hasForUser = new RegExp(`\\b(?:cho|giúp)\\s+${user}\\b`, "i").test(act);
    if (hasForUser) return `${act}${suffix}`;
    if (endsWithQuestionParticle(act)) {
      const withGiup = act.replace(/^(kiểm\s+tra|rà\s+soát|xem|tìm\s+kiếm|tra\s+cứu)\b/i, `$1 giúp ${user}`);
      return withGiup !== act ? `${withGiup}${suffix}` : `${act}${suffix}`;
    }
    return `${act} cho ${user}${suffix}`;
  };

  // 2. Fallback adapter for historical / 3rd-person reasoning summaries
  const mViCont = firstLine.match(/(?:^|\.\s*)tiếp\s+tục\s+([^.!?\n]+)/i);
  if (mViCont) {
    const act = mViCont[1].trim().replace(/[.!…]+$/, "");
    return `${capSelf} tiếp tục ${attachForUser(act, "...")}`;
  }

  const mViUser = body.match(/^(?:người\s+dùng|khách\s+hàng)\s+(?:đang\s+)?(?:muốn|yêu\s+cầu|cần|hỏi|đề\s+nghị)\s+(.+)$/i);
  if (mViUser) {
    let act = mViUser[1].trim();
    act = act.replace(/^biết\s+/i, "kiểm tra ");
    return `Để ${self} ${attachForUser(act, " nhé.")}`;
  }

  const mViNeed = body.match(/^cần\s+(?:phải\s+)?(.+)$/i);
  if (mViNeed) {
    const act = mViNeed[1].trim();
    return `Để ${self} ${attachForUser(act, " nhé.")}`;
  }

  const mViDoing = body.match(/^đang\s+(.+)$/i);
  if (mViDoing) {
    const act = mViDoing[1].trim();
    if (/^(?:cân\s+nhắc|suy\s+nghĩ\s+cách)/i.test(act)) return null;
    return `${capSelf} đang ${attachForUser(act, "...")}`;
  }

  return null;
}

/**
 * Soul-Driven & Structure-Pure Solo Turn Splitter:
 * - Priority 1 (Tool-Calling Turn with `reasonLeadIns`): Uses the pre-tool `reasonLeadIns` as the single source of truth for `leadInSegments`,
 *   and keeps `cleanContent` intact as `mainBodyContent` (only stripping an opening paragraph if it is a redundant "Em vừa đối chiếu..." ack).
 * - Priority 2 (Direct Turn without `reasonLeadIns`): Splits the opening conversational paragraph from `cleanContent` when separated by `\n\n`.
 */
function extractSoloTurnLeadInAndBody(
  msg: ChatMessage,
  cleanContent: string,
  sessionMessages: ChatMessage[],
  isTurnActivelyRunning: boolean,
  hasCallingStep: boolean,
  isRoomNarratorTurn: boolean,
  agentKey: string
): { leadInSegments: string[]; mainBodyContent: string } {
  if (isRoomNarratorTurn) {
    return { leadInSegments: [], mainBodyContent: cleanContent };
  }

  const pronouns = detectSessionPronouns(sessionMessages, msg);
  const { self } = pronouns;
  const soloSteps = Array.isArray(msg.steps) ? msg.steps : [];
  const soloTools =
    Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0
      ? msg.toolCalls
      : soloSteps.filter((s) => s.kind === "tool_call");
  const soloReasonList = soloSteps.filter((s) => s.kind === "reasoning" && s.text);
  const rawReasonSource =
    soloReasonList.length > 0
      ? soloReasonList.map((r) => r.text || "")
      : msg.reasoning
      ? [msg.reasoning]
      : [];

  const reasonLeadIns: string[] = [];
  for (let rIdx = 0; rIdx < rawReasonSource.length; rIdx++) {
    const rText = rawReasonSource[rIdx];
    const hasFirstLineBreakOrPunct = /[\n.!?…]/.test(rText.trim());
    const isStepComplete =
      !isTurnActivelyRunning ||
      soloTools.length > 0 ||
      rIdx < rawReasonSource.length - 1 ||
      Boolean(cleanContent) ||
      hasFirstLineBreakOrPunct;
    const transformed = transformReasonStepToLeadIn(rText, pronouns, isStepComplete);
    if (transformed && transformed.length >= 10 && transformed.length <= 280) {
      const normNew = transformed.toLowerCase().replace(/[^a-z0-9à-ỹ]+/gi, "");
      const isDup = reasonLeadIns.some((prev) => {
        const normPrev = prev.toLowerCase().replace(/[^a-z0-9à-ỹ]+/gi, "");
        return normPrev === normNew || normPrev.includes(normNew) || normNew.includes(normPrev);
      });
      if (!isDup && reasonLeadIns.length < 2) {
        reasonLeadIns.push(transformed);
      }
    }
  }

  const isShortSingleLinePara = (p: string) =>
    p.length >= 6 &&
    p.length <= 240 &&
    !p.includes("\n") &&
    !/^(?:#|\*|-|•|\d+\.|>|```|\|)/.test(p);

  const isRedundantPostToolAckPara = (p: string) => {
    if (!isShortSingleLinePara(p)) return false;
    const prefix = self ? `(?:để\\s+${self}|${self}\\s+(?:vừa|đã\\s+(?:kiểm\\s+tra|đối\\s+chiếu|rà\\s+soát|lấy))|giờ\\s+hệ\\s+thống\\s+${self}\\s+vừa)` : "(?:let\\s+me|i\\s+just\\s+checked|i've\\s+just\\s+checked)";
    return new RegExp(`^${prefix}\\b`, "i").test(p.trim());
  };

  // Priority 1: Turn already has pre-tool lead-in(s) from reasoning steps -> never double-stack a 2nd lead-in from cleanContent
  if (reasonLeadIns.length > 0) {
    let mainBody = cleanContent;
    if (cleanContent) {
      const paragraphs = cleanContent.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
      if (paragraphs.length >= 2 && isRedundantPostToolAckPara(paragraphs[0])) {
        mainBody = paragraphs.slice(1).join("\n\n");
      } else if (paragraphs.length === 1 && isTurnActivelyRunning && isRedundantPostToolAckPara(paragraphs[0]) && !cleanContent.includes("\n\n")) {
        mainBody = "";
      }
    }
    return {
      leadInSegments: reasonLeadIns,
      mainBodyContent: mainBody,
    };
  }

  // Priority 2: Direct turn (no pre-tool reasoning lead-in) -> split structured multi-segment or multi-paragraph opening
  const rawSegs = Array.isArray(msg.textSegments)
    ? msg.textSegments
        .map((s) => parseQuotedReplyFromContent(s, undefined, agentKey).cleanContent)
        .filter(Boolean)
    : [];

  if (rawSegs.length >= 2) {
    return {
      leadInSegments: rawSegs.slice(0, -1).slice(0, 2),
      mainBodyContent: rawSegs[rawSegs.length - 1],
    };
  }
  if (rawSegs.length === 1 && isTurnActivelyRunning && hasCallingStep && isShortSingleLinePara(rawSegs[0])) {
    return {
      leadInSegments: [rawSegs[0]],
      mainBodyContent: "",
    };
  }
  if (cleanContent) {
    const paragraphs = cleanContent.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
    const firstPara = paragraphs[0] || "";
    const isDirectConversationalOpening =
      isShortSingleLinePara(firstPara) &&
      !/^(?:không\b|em\s+(?:không|chưa\s+có)\b|hôm\s+nay\b|đây\s+là\b)/i.test(firstPara);

    if (paragraphs.length >= 2 && isDirectConversationalOpening) {
      return {
        leadInSegments: [firstPara],
        mainBodyContent: paragraphs.slice(1).join("\n\n"),
      };
    }
    if (paragraphs.length === 1 && isTurnActivelyRunning && isRedundantPostToolAckPara(firstPara) && !cleanContent.includes("\n\n")) {
      return {
        leadInSegments: [firstPara],
        mainBodyContent: "",
      };
    }
  }

  return {
    leadInSegments: [],
    mainBodyContent: cleanContent,
  };
}

export interface AttachmentFormatVariant {
  ext: string;
  fileName: string;
  url: string;
  storageUrl?: string;
}

export interface ParsedChatAttachmentItem {
  fileName: string;
  rawUrl: string;
  previewUrl: string;
  storageUrl?: string;
  isImage: boolean;
  kind: AttachmentFormatKind;
  ext: string;
  badgeColor: string;
  caption?: string;
  variants?: AttachmentFormatVariant[];
}

function normalizeAttachmentDedupeKey(rawNameOrUrl: string): string {
  const base = decodeURIComponent((rawNameOrUrl || "").split("?")[0].split("#")[0].replace(/\\/g, "/").split("/").pop() || "attachment")
    .trim()
    .toLowerCase()
    .replace(/^[0-9a-f]{32}_+/i, "")
    .replace(/^upl_[a-z0-9]+_+/i, "");
  // Unify format variants across images, audio, video, and documents (e.g. heo-de-thuong.png vs heo-de-thuong.jpg, voice.wav vs voice.mp3)
  const imgMatch = base.match(/^(.+)\.(png|jpe?g|webp|gif|bmp|avif|heic|heif)$/i);
  if (imgMatch && imgMatch[1]) return `img:${imgMatch[1]}`;
  const audioMatch = base.match(/^(.+)\.(mp3|wav|ogg|m4a|aac|flac)$/i);
  if (audioMatch && audioMatch[1]) return `aud:${audioMatch[1]}`;
  const videoMatch = base.match(/^(.+)\.(mp4|webm|mov|avi|mkv)$/i);
  if (videoMatch && videoMatch[1]) return `vid:${videoMatch[1]}`;
  return base;
}

function extractInlineToolResultMedia(
  resultStr?: string
): { dataUrl?: string; mediaType?: string; path?: string; storageUrl?: string; name?: string } | null {
  if (!resultStr || typeof resultStr !== "string") return null;
  let dataUrl: string | undefined;
  let mediaType: string | undefined;
  let pathVal: string | undefined;
  let storageUrl: string | undefined;
  let nameVal: string | undefined;

  const trimmed = resultStr.trim();
  if (trimmed.startsWith("[") || trimmed.startsWith("{")) {
    try {
      const parsed = JSON.parse(trimmed);
      const items = Array.isArray(parsed) ? parsed : [parsed];
      for (const item of items) {
        if (!item || typeof item !== "object") continue;
        if (item.type === "text" && typeof item.text === "string") {
          const pm = item.text.match(/(?:^|\n)\s*path:\s*([^\n\r]+)/i);
          if (pm && !pathVal) pathVal = pm[1].trim();
          const um = item.text.match(/(?:^|\n)\s*url:\s*(https?:\/\/[^\s\n\r]+)/i);
          if (um && !storageUrl) storageUrl = um[1].trim();
        }
        if ((item.type === "data" || item.type === "image") && item.source?.type === "base64" && typeof item.source?.data === "string" && item.source.data.length > 32) {
          const mime = item.source.media_type || item.mimeType || "image/jpeg";
          dataUrl = `data:${mime};base64,${item.source.data}`;
          mediaType = mime;
          if (typeof item.name === "string" && item.name.trim()) nameVal = item.name.trim();
        } else if (item.type === "image" && typeof item.data === "string" && item.data.length > 32) {
          const mime = item.mimeType || item.media_type || "image/png";
          dataUrl = `data:${mime};base64,${item.data}`;
          mediaType = mime;
          if (typeof item.name === "string" && item.name.trim()) nameVal = item.name.trim();
        }
      }
    } catch {}
  }

  if (!pathVal) {
    const pm = resultStr.match(/(?:^|\n|\\n)\s*path:\s*([^\n\r"\\]+)/i);
    if (pm) pathVal = pm[1].trim();
  }
  if (!storageUrl) {
    const um = resultStr.match(/\burl:\s*(https?:\/\/[^\s\n\r"\\]+)/i);
    if (um) storageUrl = um[1].trim();
  }
  if (!dataUrl) {
    const directDataUrl = resultStr.match(/data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]{64,}/);
    if (directDataUrl) dataUrl = directDataUrl[0];
  }

  if (!dataUrl && !pathVal && !storageUrl) return null;
  return { dataUrl, mediaType, path: pathVal, storageUrl, name: nameVal };
}

function extractToolSentAttachments(
  toolCalls?: ChatMessage["toolCalls"],
  steps?: ChatMessage["steps"],
  agentIdForUrl: string = "default"
): ParsedChatAttachmentItem[] {
  const results: ParsedChatAttachmentItem[] = [];
  const seen = new Set<string>();

  const addCandidate = (
    rawPath: string,
    rawFileName?: string,
    caption?: string,
    storageUrl?: string,
    explicitPreviewUrl?: string
  ) => {
    const cleanPath = (rawPath || "").trim();
    const cleanName = (rawFileName || cleanPath.replace(/\\/g, "/").split("/").pop() || "attachment").trim();
    if (!cleanPath && !cleanName && !explicitPreviewUrl) return;
    const isProtectedPath = /working\.secret/i.test(cleanPath);
    const effectiveUrl = (!cleanPath || isProtectedPath)
      ? (storageUrl || explicitPreviewUrl || `media/${cleanName}`)
      : cleanPath;
    const previewUrl = explicitPreviewUrl || storageUrl || resolveUploadedAttachmentPreviewUrl(effectiveUrl, agentIdForUrl);
    const fmt = classifyAttachmentFormat(cleanName || effectiveUrl);
    const variantItem: AttachmentFormatVariant = {
      ext: fmt.ext,
      fileName: cleanName,
      url: previewUrl,
      storageUrl,
    };
    const key = normalizeAttachmentDedupeKey(cleanName || effectiveUrl);
    if (seen.has(key)) {
      const existing = results.find((r) => normalizeAttachmentDedupeKey(r.fileName) === key || normalizeAttachmentDedupeKey(r.rawUrl) === key);
      if (existing) {
        if (!existing.variants) {
          existing.variants = [{ ext: existing.ext, fileName: existing.fileName, url: existing.previewUrl, storageUrl: existing.storageUrl }];
        }
        if (!existing.variants.some((v) => v.ext === variantItem.ext)) {
          existing.variants.push(variantItem);
        }
        if (explicitPreviewUrl && !existing.previewUrl.startsWith("data:")) existing.previewUrl = explicitPreviewUrl;
        if (storageUrl && !existing.storageUrl) existing.storageUrl = storageUrl;
      }
      return;
    }
    seen.add(key);

    results.push({
      fileName: cleanName,
      rawUrl: effectiveUrl,
      previewUrl,
      storageUrl,
      isImage: fmt.kind === "image",
      kind: fmt.kind,
      ext: fmt.ext,
      badgeColor: fmt.badgeColor,
      caption: caption?.trim() || undefined,
      variants: [variantItem],
    });
  };

  // Merge steps & toolCalls so that args from plugin_call and result from plugin_call_output are combined per call
  const mergedMap = new Map<string, { tool: string; args?: string; result?: string }>();
  const rawList = [...(steps || []).filter((s) => s.kind === "tool_call"), ...(toolCalls || [])];
  rawList.forEach((tc, idx) => {
    const key = tc.call_id || tc.id || `${tc.tool || "tool"}-${idx}`;
    const prev = mergedMap.get(key);
    if (!prev) {
      mergedMap.set(key, { tool: tc.tool || "", args: tc.args, result: tc.result });
    } else {
      if (tc.tool && (!prev.tool || prev.tool === "Tool Output" || prev.tool === "Tool Call")) prev.tool = tc.tool;
      if (tc.args && !prev.args) prev.args = tc.args;
      if (tc.result && !prev.result) prev.result = tc.result;
    }
  });
  const inspectList = Array.from(mergedMap.values());

  for (const tc of inspectList) {
    const toolName = (tc.tool || "").toLowerCase();
    const inlineMedia = extractInlineToolResultMedia(tc.result);

    // 1. Files explicitly sent or delivered by agent (send_file_to_user, send_telegram_file, etc.)
    if (
      toolName.includes("send_telegram_file") ||
      toolName.includes("send_file") ||
      toolName.includes("send_document") ||
      toolName.includes("send_photo") ||
      toolName.includes("send_video") ||
      toolName.includes("send_audio") ||
      toolName.includes("deliver_file") ||
      toolName.includes("media_send")
    ) {
      try {
        const argsObj = typeof tc.args === "string" && tc.args.trim().startsWith("{") ? JSON.parse(tc.args) : {};
        const filePath = argsObj.file_path || argsObj.path || argsObj.url || argsObj.media_url || inlineMedia?.path || "";
        const fileName = argsObj.filename || argsObj.file_name || argsObj.name || inlineMedia?.name || "";
        const caption = typeof argsObj.caption === "string" ? argsObj.caption : "Tệp do Agent tạo";
        if (filePath || fileName || inlineMedia?.dataUrl) {
          addCandidate(filePath, fileName, caption, inlineMedia?.storageUrl, inlineMedia?.dataUrl);
        }
      } catch {}
    }

    // 2. AI Image Generation / Editing tools (e.g. mcp-image__generate_image, generate_image, edit_image)
    if (
      toolName.includes("generate_image") ||
      toolName.includes("edit_image") ||
      toolName.includes("mcp-image") ||
      toolName.includes("mcp_image") ||
      toolName.includes("image_gen")
    ) {
      try {
        const argsObj = typeof tc.args === "string" && tc.args.trim().startsWith("{") ? JSON.parse(tc.args) : {};
        const outPath = inlineMedia?.path || argsObj.output_path || argsObj.path || "";
        const extFromMime = inlineMedia?.mediaType?.includes("png")
          ? "png"
          : inlineMedia?.mediaType?.includes("webp")
          ? "webp"
          : "jpg";
        const baseFromPath = outPath ? outPath.replace(/\\/g, "/").split("/").pop() || "" : "";
        let reqName = String(argsObj.fileName || argsObj.file_name || argsObj.filename || inlineMedia?.name || baseFromPath || "generated-image").trim();
        if (reqName && !/\.[a-z0-9]{2,5}$/i.test(reqName)) {
          reqName = `${reqName}.${extFromMime}`;
        }
        if (outPath || inlineMedia?.dataUrl || inlineMedia?.storageUrl) {
          addCandidate(
            outPath || `media/${reqName}`,
            baseFromPath || reqName,
            "Ảnh do Agent tạo",
            inlineMedia?.storageUrl,
            inlineMedia?.dataUrl
          );
        }
      } catch {}
    }

    // 3. Audio360 Speech Synthesis tools (e.g. audio360__audio360_synthesize_speech, audio360_create_audio_from_file)
    if (
      toolName.includes("audio360") ||
      toolName.includes("synthesize_speech") ||
      toolName.includes("create_audio")
    ) {
      try {
        const argsObj = typeof tc.args === "string" && tc.args.trim().startsWith("{") ? JSON.parse(tc.args) : {};
        const outPath = inlineMedia?.path || argsObj.outputPath || argsObj.output_path || argsObj.path || "";
        const baseFromPath = outPath ? outPath.replace(/\\/g, "/").split("/").pop() || "" : "";
        const reqName = baseFromPath || "audio-narration.mp3";
        if (outPath || inlineMedia?.dataUrl || inlineMedia?.storageUrl) {
          addCandidate(
            outPath || `media/${reqName}`,
            reqName,
            "Âm thanh do Agent tạo",
            inlineMedia?.storageUrl,
            inlineMedia?.dataUrl
          );
        }
      } catch {}
    }

    // 3. MinIO / S3 Storage upload tools (e.g. minio__upload_file, upload_file)
    if (toolName.includes("minio") || toolName.includes("storage") || toolName.includes("upload")) {
      try {
        const argsObj = typeof tc.args === "string" && tc.args.trim().startsWith("{") ? JSON.parse(tc.args) : {};
        const localPath = argsObj.path || argsObj.file_path || argsObj.filePath || inlineMedia?.path || "";
        const storageUrl = argsObj.url || inlineMedia?.storageUrl || "";
        if (localPath || storageUrl) {
          addCandidate(localPath || storageUrl, undefined, "Tệp đã lưu trữ trên Storage", storageUrl || undefined, inlineMedia?.dataUrl);
        }
      } catch {}
    }

    // 3b. Translate360 PDF Book Translation tools (e.g. translate__translate_book)
    if (toolName.includes("translate_book") || toolName.includes("translate__")) {
      try {
        if (tc.result && typeof tc.result === "string") {
          const parsedRes = JSON.parse(tc.result);
          const outerList = Array.isArray(parsedRes) ? parsedRes : [parsedRes];
          for (const outer of outerList) {
            const payload =
              outer?.type === "text" && typeof outer.text === "string" && outer.text.trim().startsWith("{")
                ? JSON.parse(outer.text)
                : outer;
            if (Array.isArray(payload?.artifacts)) {
              for (const art of payload.artifacts) {
                const localPath = art.local_media_path || art.path || "";
                const dlUrl = art.url || "";
                const artName = art.name || (localPath || dlUrl).split("/").pop() || "translated.pdf";
                const variantLabel = art.variant === "dual" ? "Bản dịch song ngữ (Dual PDF)" : art.variant === "mono" ? "Bản dịch tiếng Việt (Mono PDF)" : "Tài liệu đã dịch";
                if (localPath || dlUrl) {
                  addCandidate(localPath || dlUrl, artName, variantLabel, dlUrl || undefined);
                }
              }
            }
          }
        }
      } catch {}
    }

    // 3c. Studio360 Video Composition tools (e.g. studio360__compose_project_video)
    if (toolName.includes("studio360") && (toolName.includes("compose") || toolName.includes("video"))) {
      try {
        if (tc.result && typeof tc.result === "string") {
          const mp4Match = tc.result.match(/(?:https?:\/\/[^\s"\x27<>]+\.mp4|\/[^\s"\x27<>]+\.mp4)/i);
          if (mp4Match) {
            const rawVid = mp4Match[0];
            const vidName = rawVid.split("/").pop() || "studio360-video.mp4";
            const isHttp = /^https?:\/\//i.test(rawVid);
            addCandidate(rawVid, vidName, "Video quảng cáo Studio360", isHttp ? rawVid : undefined);
          }
        }
      } catch {}
    }

    // 4. Files authored or written by agent via write_file / edit_file
    if (toolName === "write_file" || toolName.endsWith("__write_file")) {
      try {
        const argsObj = typeof tc.args === "string" && tc.args.trim().startsWith("{") ? JSON.parse(tc.args) : {};
        const filePath = argsObj.file_path || argsObj.path || inlineMedia?.path || "";
        const baseName = filePath.replace(/\\/g, "/").split("/").pop() || "";
        // Exclude internal system logs, memory journals, and internal agent state while keeping user-facing media/docs
        const isInternalMd =
          baseName.endsWith(".md") &&
          (/^(AGENTS|BOOTSTRAP|HEARTBEAT|IDENTITY|MEMORY|PROFILE|SOUL)\.md$/i.test(baseName) ||
            /(?:^|\/)memory\//i.test(filePath) ||
            /(?:^|\/)digest\//i.test(filePath));
        if (baseName && !isInternalMd && !baseName.endsWith(".jsonl") && !baseName.endsWith(".yaml")) {
          addCandidate(filePath, baseName, "Tệp do Agent tạo");
        }
      } catch {}
    }

    if (tc.result && typeof tc.result === "string") {
      const fileOutMatch = tc.result.match(/FILE\s+(\/app\/working\/workspaces\/[^\s"']+)/i);
      if (fileOutMatch && (toolName.includes("send") || inspectList.some((x) => (x.tool || "").toLowerCase().includes("send")))) {
        addCandidate(fileOutMatch[1]);
      }
    }
  }

  return results;
}

function parseQuotedReplyFromContent(
  rawContent: string,
  explicitReplyTo?: ReplyToMessageInfo,
  agentIdForUrl: string = "default",
  toolCalls?: ChatMessage["toolCalls"],
  steps?: ChatMessage["steps"]
): { replyTo?: ReplyToMessageInfo; cleanContent: string; attachments: ParsedChatAttachmentItem[] } {
  let text = stripInternalExecutionArtifacts(stripSharedRoomContext(rawContent || ""));
  let resolvedReplyTo = explicitReplyTo;
  const match = text.match(/^\[Replying to ([^:\]]+):\s*"([^"]*)"\]\s*\n\n?([\s\S]*)$/);
  if (match) {
    resolvedReplyTo = explicitReplyTo || {
      authorName: match[1].trim(),
      snippet: match[2].trim(),
    };
    let tail = match[3];
    tail = tail.replace(/^\[Trọng tâm ngữ cảnh[^\]]*\][\s\S]*?\*\([^\n\r]*\)\*\s*(?:\r?\n)+/i, "");
    text = stripSharedRoomContext(tail);
  }

  const attachments: ParsedChatAttachmentItem[] = [];
  const seenKeys = new Set<string>();

  const decodeMimeBase64FileName = (name: string): string => {
    const m = (name || "").match(/__utf-8_B_([A-Za-z0-9+/=]+)__/i);
    if (m) {
      try {
        const b64 = m[1];
        const padded = b64 + "=".repeat((4 - (b64.length % 4)) % 4);
        const bin = atob(padded);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        const decoded = new TextDecoder("utf-8").decode(bytes).trim();
        if (decoded) return decoded;
      } catch {}
    }
    return name;
  };

  const pushAttachment = (rawName: string, rawUrl: string, caption?: string) => {
    const url = (rawUrl || "").trim().replace(/^file:\/\/+/, "/");
    const fallbackFile = decodeURIComponent(url.replace(/\\/g, "/").split("/").pop() || "attachment");
    const fileName = decodeMimeBase64FileName((rawName || fallbackFile).trim());
    const isExternalStorage = /^https?:\/\/[^/]*(?:storage\.|minio|translate\.antares\.vn\/gradio_api\/file=)/i.test(url);
    const previewUrl = isExternalStorage
      ? url
      : resolveUploadedAttachmentPreviewUrl(url, agentIdForUrl);
    const fmt = classifyAttachmentFormat(fileName || url);
    const variantItem: AttachmentFormatVariant = {
      ext: fmt.ext,
      fileName,
      url: previewUrl,
      storageUrl: isExternalStorage ? url : undefined,
    };

    const dedupeKey = normalizeAttachmentDedupeKey(fileName || url);
    if (seenKeys.has(dedupeKey)) {
      const existing = attachments.find((a) => normalizeAttachmentDedupeKey(a.fileName || a.rawUrl) === dedupeKey);
      if (existing) {
        if (!existing.variants) {
          existing.variants = [{ ext: existing.ext, fileName: existing.fileName, url: existing.previewUrl, storageUrl: existing.storageUrl }];
        }
        if (!existing.variants.some((v) => v.ext === variantItem.ext)) {
          existing.variants.push(variantItem);
        }
        if (isExternalStorage && !existing.storageUrl) existing.storageUrl = url;
      }
      return;
    }
    seenKeys.add(dedupeKey);

    attachments.push({
      fileName,
      rawUrl: url,
      previewUrl,
      storageUrl: isExternalStorage ? url : undefined,
      isImage: fmt.kind === "image",
      kind: fmt.kind,
      ext: fmt.ext,
      badgeColor: fmt.badgeColor,
      caption,
      variants: [variantItem],
    });
  };

  // Look for friendly display name in Telegram/Zalo history header: "[Đính kèm: <name>]"
  const friendlyNames: string[] = [];
  const friendlyRegex = /\[(?:Đính kèm|Attachment|File):\s*([^\]\n\r]+)\]/gi;
  let fm: RegExpExecArray | null;
  while ((fm = friendlyRegex.exec(text)) !== null) {
    if (fm[1]) friendlyNames.push(fm[1].trim());
  }

  // 1. Standard [Attached File: name (url)] (allows parentheses inside filename)
  const attachRegex = /\[Attached File:\s*([^\n\r]+?)\s*\(([^()\n\r]+)\)\]/gi;
  text = text.replace(attachRegex, (_full, rawName: string, rawUrl: string) => {
    pushAttachment(rawName, rawUrl);
    return "";
  });

  // 2. QwenPaw <system-reminder>An attached file is saved into file:///app/working/workspaces/...</system-reminder>
  const sysReminderRegex = /<system-reminder>\s*An attached file is saved into\s*(?:file:\/\/)?([^<\s]+?)\.?\s*<\/system-reminder>/gi;
  text = text.replace(sysReminderRegex, (_full, rawPath: string) => {
    const cleanPath = rawPath.replace(/\.$/, "");
    const friendly = friendlyNames.length > 0 ? friendlyNames[friendlyNames.length - 1] : "";
    pushAttachment(friendly, cleanPath);
    return "";
  });

  // 3. QwenPaw "User uploaded a file, downloaded to /app/working/workspaces/..."
  const uploadedLineRegex = /(?:^|\n)\s*User uploaded a file,\s*downloaded to\s*([^\s\n\r]+)\s*/gi;
  text = text.replace(uploadedLineRegex, (_full, rawPath: string) => {
    const friendly = friendlyNames.length > 0 ? friendlyNames[friendlyNames.length - 1] : "";
    pushAttachment(friendly, rawPath.trim());
    return "\n";
  });

  // 4. Strip Telegram/Zalo backlog wrapper if present so user bubble shows only the actual user message
  const currentMsgMarker = "[Tin nhắn hiện tại cần xử lý]:";
  const markerIdx = text.indexOf(currentMsgMarker);
  if (markerIdx >= 0 && text.includes("[Ngữ cảnh hội thoại gần đây")) {
    text = text.slice(markerIdx + currentMsgMarker.length);
  }

  // 5. Strip [Telegram replied-message context ...] block if embedded in user content
  text = text.replace(/\[Telegram replied-message context[^\]]*\]\s*\n\{[\s\S]*?\}(?=\n|$)/gi, "");

  // 5b. Extract markdown images ![alt](url) into attachment cards and remove from body text to avoid double image rendering
  const mdImgRegex = /!\[([^\]\n\r]*)\]\((https?:\/\/[^\s\)]+|\/[^\s\)]+|[^\s\)]+\.(?:png|jpe?g|webp|gif|svg|bmp|avif|heic|heif))\)/gi;
  text = text.replace(mdImgRegex, (_full, rawAlt: string, rawUrl: string) => {
    const cleanUrl = rawUrl.trim();
    const cleanFile = cleanUrl.split("?")[0].split("#")[0].replace(/\\/g, "/").split("/").pop() || rawAlt.trim() || "image.png";
    pushAttachment(cleanFile, cleanUrl, rawAlt.trim() || "Ảnh đính kèm");
    return "";
  });

  // 6. Extract markdown file links: [Label](url) or direct Storage URLs (negative lookbehind for !)
  const mdLinkRegex = /(?<!!)\[([^\]\n\r]+)\]\((https?:\/\/[^\s\)]+|[^\s\)]+\.(?:html?|pdf|xlsx?|csv|tsv|json|txt|md|docx?|pptx?|zip|png|jpe?g|webp|gif|svg|mp4|mp3|wav))\)/gi;
  let mdlMatch: RegExpExecArray | null;
  while ((mdlMatch = mdLinkRegex.exec(text)) !== null) {
    const label = mdlMatch[1].trim();
    const linkUrl = mdlMatch[2].trim();
    const cleanFile = linkUrl.split("?")[0].split("#")[0].replace(/\\/g, "/").split("/").pop() || label;
    pushAttachment(cleanFile, linkUrl, label !== cleanFile ? label : "Đường dẫn tải tài liệu");
  }

  // 7. Direct MinIO / S3 Storage URLs in text body
  const storageUrlRegex = /(https?:\/\/[^\s\)\"\'<>]+(?:storage\.[^\s\)\"\'<>]+|minio[^\s\)\"\'<>]*\/[^\s\)\"\'<>]+|\/[a-zA-Z0-9_\-\.]+\.(?:html?|pdf|xlsx?|csv|tsv|json|txt|md|docx?|pptx?|zip|png|jpe?g|webp|gif|svg|mp4|mp3|wav)))/gi;
  let stMatch: RegExpExecArray | null;
  while ((stMatch = storageUrlRegex.exec(text)) !== null) {
    const rawStorageUrl = stMatch[1].replace(/[.,;:!?]+$/, "");
    const cleanFile = rawStorageUrl.split("?")[0].split("#")[0].replace(/\\/g, "/").split("/").pop() || "storage_file";
    pushAttachment(cleanFile, rawStorageUrl, "Đường dẫn lưu trữ Storage");
  }

  // 8. Mentions of created/sent files in backticks: `file.ext`
  // Matches e.g. "File đã gửi: `zeroism-doanh-thu-2026.html`", "Đã xuất file `report.xlsx`"
  const backtickFileRegex = /`([a-zA-Z0-9_\-\.\/\\]+\.(?:html?|pdf|xlsx?|csv|tsv|json|txt|md|docx?|pptx?|zip|png|jpe?g|webp|gif|svg|mp4|mp3|wav))`(?=[.,;:!?\s]|$)/gi;
  let btMatch: RegExpExecArray | null;
  while ((btMatch = backtickFileRegex.exec(text)) !== null) {
    const rawFound = btMatch[1].trim();
    const cleanFile = rawFound.replace(/\\/g, "/").split("/").pop() || rawFound;
    pushAttachment(cleanFile, rawFound, "Tệp do Agent tạo");
  }

  // 9. Include any files sent by the assistant via tool calls (e.g. send_telegram_file, minio__upload_file, write_file)
  const toolSent = extractToolSentAttachments(toolCalls, steps, agentIdForUrl);
  for (const ts of toolSent) {
    const dedupeKey = normalizeAttachmentDedupeKey(ts.fileName || ts.rawUrl);
    if (!seenKeys.has(dedupeKey)) {
      seenKeys.add(dedupeKey);
      attachments.push(ts);
    } else {
      const existing = attachments.find((a) => normalizeAttachmentDedupeKey(a.fileName || a.rawUrl) === dedupeKey);
      if (existing) {
        if (!existing.variants) {
          existing.variants = [{ ext: existing.ext, fileName: existing.fileName, url: existing.previewUrl, storageUrl: existing.storageUrl }];
        }
        for (const v of ts.variants || [{ ext: ts.ext, fileName: ts.fileName, url: ts.previewUrl, storageUrl: ts.storageUrl }]) {
          if (!existing.variants.some((ev) => ev.ext === v.ext)) {
            existing.variants.push(v);
          }
        }
        if (ts.previewUrl.startsWith("data:") && !existing.previewUrl.startsWith("data:")) {
          existing.previewUrl = ts.previewUrl;
        } else if (ts.storageUrl && !existing.previewUrl.startsWith("data:") && !existing.previewUrl.startsWith("http")) {
          existing.previewUrl = ts.storageUrl;
        }
        if (ts.storageUrl && !existing.storageUrl) existing.storageUrl = ts.storageUrl;
      }
    }
  }

  return {
    replyTo: resolvedReplyTo,
    cleanContent: text.trim(),
    attachments,
  };
}
