function resolveChannelsFromText(text: string): SkyerInteractiveOption[] {
  if (!text) return [];
  const low = text.toLowerCase();
  const matched: SkyerInteractiveOption[] = [];
  const seen = new Set<string>();
  for (const ch of CHANNEL_CONNECTION_CATALOG) {
    const hit = ch.aliases.some((al) => low.includes(al));
    if (hit && !seen.has(ch.id)) {
      seen.add(ch.id);
      matched.push({
        id: ch.id,
        channelType: ch.id,
        channelMode: ch.defaultMode,
        requiresToken: ch.requiresToken,
        label: ch.name,
        description: ch.description,
        prompt: `Tôi đã thiết lập và bật kênh ${ch.name} (/${ch.id}), hãy kiểm tra kết nối và tiếp tục.`,
      });
    }
  }
  return matched;
}

function resolveCatalogAppsFromText(text: string): SkyerInteractiveOption[] {
  if (!text) return [];
  const low = text.toLowerCase();
  const matched: SkyerInteractiveOption[] = [];
  const seen = new Set<string>();
  const EXTRA_ALIASES: Record<string, string[]> = {
    gmail: ["gmail", "google mail", "email", "hộp thư"],
    googlecalendar: ["google calendar", "lịch google", "calendar"],
    googledrive: ["google drive", "drive"],
    googledocs: ["google docs", "docs"],
    googlesheets: ["google sheets", "sheets", "bảng tính"],
    github: ["github", "git repo", "pull request"],
    gitlab: ["gitlab"],
    notion: ["notion"],
    slack: ["slack"],
    discord: ["discord"],
    telegram: ["telegram"],
    jira: ["jira"],
    linear: ["linear"],
    trello: ["trello"],
    asana: ["asana"],
    clickup: ["clickup"],
    figma: ["figma"],
    canva: ["canva"],
    stripe: ["stripe"],
    shopify: ["shopify"],
    hubspot: ["hubspot"],
    salesforce: ["salesforce"],
    supabase: ["supabase"],
    cloudflare: ["cloudflare"],
    vercel: ["vercel"],
    postgres: ["postgres", "postgresql"],
  };
  for (const app of APPS_CATALOG) {
    const slug = app.id.toLowerCase();
    const aliases = EXTRA_ALIASES[slug] || [slug, app.name.toLowerCase()];
    const hit = aliases.some((al) => {
      if (al.length <= 3) {
        return new RegExp(`\\b${al}\\b`, "i").test(low);
      }
      return low.includes(al);
    });
    if (hit && !seen.has(slug)) {
      seen.add(slug);
      matched.push({
        id: slug,
        appSlug: slug,
        label: app.name,
        description: app.description,
        logoUrl: app.logoUrl,
        prompt: `Tôi đã kết nối ứng dụng ${app.name} (/${slug}), hãy tiếp tục thực hiện yêu cầu.`,
      });
    }
    if (matched.length >= 4) break;
  }
  return matched;
}

export interface BrowserExecutionSummary {
  hasBrowserAction: boolean;
  isActivelyCalling: boolean;
  activeToolName: string;
  actionLabel: string;
  url?: string;
  screenshotUrl?: string;
  stepCount: number;
}

function extractBrowserExecutionSummary(msg: ChatMessage): BrowserExecutionSummary | null {
  const rawSteps = [
    ...(Array.isArray(msg.steps) ? msg.steps.filter((s) => s.kind === "tool_call") : []),
    ...(Array.isArray(msg.toolCalls) ? msg.toolCalls : []),
  ];
  if (rawSteps.length === 0) return null;

  const mergedMap = new Map<string, { tool: string; args?: string; result?: string; state?: string }>();
  rawSteps.forEach((tc: any, idx: number) => {
    const k = tc.call_id || tc.id || `${tc.tool || "tool"}-${idx}`;
    const prev = mergedMap.get(k);
    if (!prev) {
      mergedMap.set(k, { tool: tc.tool || "", args: tc.args, result: tc.result, state: tc.state });
    } else {
      if (tc.tool && (!prev.tool || prev.tool === "Tool Output" || prev.tool === "Tool Call")) prev.tool = tc.tool;
      if (tc.args && !prev.args) prev.args = tc.args;
      if (tc.result && !prev.result) prev.result = tc.result;
      if (tc.state === "calling" || (!prev.state && tc.state)) prev.state = tc.state;
    }
  });

  const browserSteps: Array<{ tool: string; args?: string; result?: string; state?: string }> = [];
  for (const item of mergedMap.values()) {
    const tLow = (item.tool || "").toLowerCase();
    const isBrowserTool =
      tLow.includes("browser") ||
      tLow.includes("cdp") ||
      tLow.includes("playwright") ||
      tLow.includes("navigate") ||
      tLow.includes("take_screenshot") ||
      tLow.includes("take_snapshot") ||
      tLow.includes("open_url") ||
      tLow.includes("select_page") ||
      tLow.includes("click") ||
      tLow.includes("hover") ||
      tLow.includes("type_text") ||
      tLow.includes("evaluate_script");
    if (isBrowserTool) {
      browserSteps.push(item);
    }
  }

  if (browserSteps.length === 0) return null;

  let latestUrl: string | undefined;
  let latestScreenshot: string | undefined;
  let isCalling = false;
  let lastTool = browserSteps[browserSteps.length - 1].tool || "browser";

  for (const bs of browserSteps) {
    if (bs.state === "calling") {
      isCalling = true;
      lastTool = bs.tool || lastTool;
    }
    const combinedText = `${bs.args || ""} ${bs.result || ""}`;
    const urlMatches = combinedText.match(/https?:\/\/[^\s"',}\]\\]+/gi);
    if (urlMatches) {
      for (const u of urlMatches) {
        if (!/localhost:1922|127\.0\.0\.1|browser-test:922/i.test(u)) {
          if (/\.(?:png|jpe?g|webp)$/i.test(u)) {
            latestScreenshot = u;
          } else {
            latestUrl = u.replace(/[.,;]+$/, "");
          }
        }
      }
    }
    if (bs.result) {
      const b64 = bs.result.match(/data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]{64,}/);
      if (b64) latestScreenshot = b64[0];
    }
  }

  const shortTool = lastTool.includes("__") ? lastTool.split("__").pop()! : lastTool;
  let actionLabel = isCalling ? `Đang thao tác trên Web (${shortTool})...` : `Đã thực thi ${browserSteps.length} thao tác trên Computer`;
  if (shortTool.includes("navigate") || shortTool.includes("open")) {
    actionLabel = isCalling ? "Đang truy cập trang web..." : "Đã mở và kiểm tra trang web";
  } else if (shortTool.includes("screenshot") || shortTool.includes("snapshot")) {
    actionLabel = isCalling ? "Đang chụp màn hình trình duyệt..." : "Đã chụp màn hình và phân tích giao diện";
  } else if (shortTool.includes("click") || shortTool.includes("type") || shortTool.includes("fill")) {
    actionLabel = isCalling ? "Đang tương tác phần tử trên trang..." : "Đã điền biểu mẫu & tương tác trên Web";
  }

  return {
    hasBrowserAction: true,
    isActivelyCalling: isCalling,
    activeToolName: shortTool,
    actionLabel,
    url: latestUrl,
    screenshotUrl: latestScreenshot,
    stepCount: browserSteps.length,
  };
}

function extractInteractiveWidgetsFromTurn(msg: ChatMessage, cleanContent: string): SkyerInteractiveWidget[] {
  const widgets: SkyerInteractiveWidget[] = [];
  const seenIds = new Set<string>();

  const rawSteps = [
    ...(Array.isArray(msg.steps) ? msg.steps.filter((s) => s.kind === "tool_call") : []),
    ...(Array.isArray(msg.toolCalls) ? msg.toolCalls : []),
  ];
  const mergedMap = new Map<string, { tool: string; args?: string; result?: string }>();
  rawSteps.forEach((tc: any, idx: number) => {
    const k = tc.call_id || tc.id || `${tc.tool || "tool"}-${idx}`;
    const prev = mergedMap.get(k);
    if (!prev) {
      mergedMap.set(k, { tool: tc.tool || "", args: tc.args, result: tc.result });
    } else {
      if (tc.tool && (!prev.tool || prev.tool === "Tool Output" || prev.tool === "Tool Call")) prev.tool = tc.tool;
      if (tc.args && !prev.args) prev.args = tc.args;
      if (tc.result && !prev.result) prev.result = tc.result;
    }
  });

  for (const tc of mergedMap.values()) {
    const tLow = (tc.tool || "").toLowerCase();
    const isConnectChannelTool =
      tLow.includes("present_connect_channel") ||
      tLow.includes("request_channel_connection") ||
      tLow.includes("connect_channel") ||
      tLow.includes("setup_channel");
    const isConnectAppTool =
      !isConnectChannelTool &&
      (tLow.includes("present_connect_app") ||
        tLow.includes("request_app_connection") ||
        tLow.includes("connect_app"));
    const isPresentationTool =
      isConnectChannelTool ||
      isConnectAppTool ||
      tLow.includes("present_interactive_options") ||
      tLow.includes("present_telegram_poll") ||
      tLow.includes("present_telegram_input") ||
      tLow === "present" ||
      tLow.endsWith("__present");

    if (!isPresentationTool && (!tc.result || !tc.result.includes("skyer-interaction/v1"))) {
      continue;
    }

    let parsedObj: any = null;
    if (tc.result && typeof tc.result === "string") {
      try {
        const rawParsed = JSON.parse(tc.result);
        const items = Array.isArray(rawParsed) ? rawParsed : [rawParsed];
        for (const item of items) {
          if (item?.schema === "skyer-interaction/v1" || item?.options || item?.menu_token) {
            parsedObj = item;
            break;
          }
          if (item?.type === "text" && typeof item.text === "string" && item.text.trim().startsWith("{")) {
            const inner = JSON.parse(item.text);
            if (inner?.schema === "skyer-interaction/v1" || inner?.options || inner?.menu_token) {
              parsedObj = inner;
              break;
            }
          }
        }
      } catch {}
    }

    let argsObj: any = null;
    if (tc.args && typeof tc.args === "string" && tc.args.trim().startsWith("{")) {
      try {
        argsObj = JSON.parse(tc.args);
      } catch {}
    }

    const source = parsedObj || argsObj;
    if (!source) continue;

    const effective = source.intent && typeof source.intent === "object" ? source.intent : source;
    const rawOpts =
      effective.options ||
      effective.interaction?.options ||
      effective.content?.options ||
      argsObj?.options ||
      [];

    const kindRaw = String(
      effective.kind ||
        effective.interaction?.type ||
        effective.mode ||
        (tLow.includes("poll") ? "poll" : tLow.includes("input") ? argsObj?.mode || "force_reply" : "options")
    ).toLowerCase();

    const isConnectChannelKind =
      isConnectChannelTool ||
      kindRaw === "connect_channel" ||
      kindRaw === "connect_channels" ||
      kindRaw === "setup_channel" ||
      String(effective.action_type || "").toLowerCase() === "connect_channel" ||
      String(effective.action_type || "").toLowerCase() === "setup_channel";

    const isConnectKind =
      !isConnectChannelKind &&
      (isConnectAppTool ||
        kindRaw === "connect_app" ||
        kindRaw === "connect_apps" ||
        String(effective.action_type || "").toLowerCase() === "connect_app");

    const kind: SkyerInteractiveWidget["kind"] = isConnectChannelKind
      ? "connect_channel"
      : isConnectKind
      ? "connect_app"
      : kindRaw === "poll"
      ? "poll"
      : kindRaw === "force_reply"
      ? "force_reply"
      : kindRaw === "reply_keyboard"
      ? "reply_keyboard"
      : "options";

    const promptText = String(
      effective.prompt_text ||
        effective.question ||
        effective.text ||
        effective.content?.text ||
        argsObj?.text ||
        argsObj?.question ||
        "Chọn thao tác tiếp theo:"
    ).trim();

    const normOptions: SkyerInteractiveOption[] = [];
    if (Array.isArray(rawOpts)) {
      rawOpts.forEach((o: any, idx: number) => {
        if (typeof o === "string" && o.trim()) {
          normOptions.push({ id: `opt_${idx}`, label: o.trim(), prompt: o.trim() });
        } else if (o && typeof o === "object") {
          const label = String(o.label || o.text || o.title || o.id || "").trim();
          if (label) {
            normOptions.push({
              id: String(o.id || `opt_${idx}`).trim(),
              label,
              prompt: typeof o.prompt === "string" && o.prompt.trim() ? o.prompt.trim() : label,
              url: typeof o.url === "string" && /^https?:\/\//i.test(o.url.trim()) ? o.url.trim() : undefined,
              copy_text: typeof o.copy_text === "string" && o.copy_text.trim() ? o.copy_text.trim() : undefined,
            });
          }
        }
      });
    }

    if (kind === "connect_app") {
      const explicitApps = Array.isArray(effective.apps || argsObj?.apps)
        ? (effective.apps || argsObj?.apps)
        : effective.app_slug || effective.appSlug || argsObj?.app_slug || argsObj?.appSlug
        ? [effective.app_slug || effective.appSlug || argsObj?.app_slug || argsObj?.appSlug]
        : [];
      for (const item of explicitApps) {
        const rawSlug = typeof item === "string" ? item : item?.id || item?.slug || item?.app_slug || "";
        const cleanSlug = String(rawSlug).toLowerCase().replace(/^composio_/, "").trim();
        if (!cleanSlug) continue;
        const catalogApp = APPS_CATALOG.find((a) => a.id.toLowerCase() === cleanSlug);
        normOptions.push({
          id: cleanSlug,
          appSlug: cleanSlug,
          label: catalogApp?.name || (typeof item === "object" && item?.name) || cleanSlug,
          description: catalogApp?.description || (typeof item === "object" && item?.description) || `Tích hợp công cụ ${cleanSlug} qua Composio MCP`,
          logoUrl: catalogApp?.logoUrl || `https://logos.composio.dev/api/${cleanSlug}`,
          prompt: `Tôi đã kết nối ứng dụng ${catalogApp?.name || cleanSlug} (/${cleanSlug}), hãy tiếp tục.`,
        });
      }
      if (normOptions.length === 0) {
        const inferred = resolveCatalogAppsFromText(`${promptText} ${cleanContent}`);
        normOptions.push(...inferred);
      }
    }
    if (kind === "connect_channel") {
      const explicitChannels = Array.isArray(effective.channels || argsObj?.channels)
        ? (effective.channels || argsObj?.channels)
        : effective.channel_type || effective.channelType || effective.channel || argsObj?.channel_type || argsObj?.channelType || argsObj?.channel
        ? [effective.channel_type || effective.channelType || effective.channel || argsObj?.channel_type || argsObj?.channelType || argsObj?.channel]
        : [];
      for (const item of explicitChannels) {
        const rawType = typeof item === "string" ? item : item?.type || item?.channel_type || item?.id || "";
        const cleanType = String(rawType).toLowerCase().trim();
        if (!cleanType) continue;
        const catCh = CHANNEL_CONNECTION_CATALOG.find((c) => c.id === cleanType);
        if (normOptions.some((o) => (o.channelType || o.id).toLowerCase() === cleanType)) continue;
        normOptions.push({
          id: cleanType,
          channelType: cleanType,
          channelMode: (typeof item === "object" && item?.mode) || catCh?.defaultMode || (cleanType === "zalo" ? "web" : "bot"),
          requiresToken: catCh ? catCh.requiresToken : cleanType !== "zalo",
          label: catCh?.name || (typeof item === "object" && item?.name) || cleanType.toUpperCase(),
          description:
            catCh?.description ||
            (typeof item === "object" && item?.description) ||
            `Thiết lập và bật kênh giao tiếp ${cleanType.toUpperCase()} cho Agent`,
          prompt: `Tôi đã thiết lập và bật kênh ${catCh?.name || cleanType.toUpperCase()} (/${cleanType}), hãy tiếp tục.`,
        });
      }
      if (normOptions.length === 0) {
        const inferred = resolveChannelsFromText(`${promptText} ${cleanContent}`);
        normOptions.push(...inferred);
      }
      if (normOptions.length === 0) {
        for (const ch of CHANNEL_CONNECTION_CATALOG) {
          normOptions.push({
            id: ch.id,
            channelType: ch.id,
            channelMode: ch.defaultMode,
            requiresToken: ch.requiresToken,
            label: ch.name,
            description: ch.description,
            prompt: `Tôi đã thiết lập và bật kênh ${ch.name} (/${ch.id}), hãy tiếp tục.`,
          });
        }
      }
    }
    if (kind !== "force_reply" && kind !== "connect_app" && kind !== "connect_channel" && normOptions.length === 0) continue;

    const interactionId = String(
      effective.interaction_id || effective.menu_token || `ix_${msg.id}_${widgets.length}`
    );
    if (seenIds.has(interactionId)) continue;
    seenIds.add(interactionId);

    widgets.push({
      interactionId,
      kind,
      promptText,
      actionType: String(effective.action_type || "general"),
      columns: Number(effective.columns) || 2,
      allowsMultiple: Boolean(effective.allows_multiple || effective.allows_multiple_answers || argsObj?.allows_multiple),
      placeholder: String(effective.placeholder || argsObj?.placeholder || "Nhập thông tin phản hồi..."),
      options: normOptions,
    });
  }

  // Parse inline ```skyer-interaction/v1 or JSON fenced blocks from assistant prose
  if (cleanContent && (cleanContent.includes("skyer-interaction/v1") || cleanContent.includes('"connect_channel"') || cleanContent.includes('"connect_app"'))) {
    const fencedRegex = /```(?:skyer-interaction\/v1|json)?\s*\n([\s\S]*?)```/gi;
    let fm: RegExpExecArray | null;
    while ((fm = fencedRegex.exec(cleanContent)) !== null) {
      const rawBlock = (fm[1] || "").trim();
      if (!rawBlock.startsWith("{")) continue;
      try {
        const parsed = JSON.parse(rawBlock);
        const eff = parsed.intent && typeof parsed.intent === "object" ? parsed.intent : parsed;
        const kRaw = String(eff.kind || eff.type || eff.action_type || "").toLowerCase();
        const isMisleadingChannelMethodChoice =
          (kRaw === "choice" || kRaw === "options" || !kRaw) &&
          Array.isArray(eff.options) &&
          eff.options.some((o: any) =>
            /(?:zalo\s*oa|official\s*account|zns|webhook|nền\s*tảng\s*trung\s*gian|botfather|zalo\s*web)/i.test(
              typeof o === "string" ? o : `${o?.label || ""} ${o?.text || ""} ${o?.description || ""}`
            )
          );

        if (kRaw === "connect_channel" || kRaw === "connect_channels" || kRaw === "setup_channel" || isMisleadingChannelMethodChoice) {
          const explicitChannels = Array.isArray(eff.channels)
            ? eff.channels
            : eff.channel_type || eff.channel
            ? [eff.channel_type || eff.channel]
            : [];
          const normChOpts: SkyerInteractiveOption[] = [];
          for (const item of explicitChannels) {
            const rawType = typeof item === "string" ? item : item?.type || item?.channel_type || item?.id || "";
            const cleanType = String(rawType).toLowerCase().trim();
            if (!cleanType) continue;
            const catCh = CHANNEL_CONNECTION_CATALOG.find((c) => c.id === cleanType);
            if (normChOpts.some((o) => (o.channelType || o.id).toLowerCase() === cleanType)) continue;
            normChOpts.push({
              id: cleanType,
              channelType: cleanType,
              channelMode: cleanType === "zalo" ? ((typeof item === "object" && item?.mode === "webhook") ? "webhook" : "web") : (catCh?.defaultMode || "bot"),
              requiresToken: catCh ? catCh.requiresToken : cleanType !== "zalo",
              label: catCh?.name || cleanType.toUpperCase(),
              description: catCh?.description || `Thiết lập và bật kênh ${cleanType.toUpperCase()} cho Agent`,
              prompt: `Tôi đã thiết lập và bật kênh ${catCh?.name || cleanType.toUpperCase()} (/${cleanType}), hãy kiểm tra kết nối và tiếp tục.`,
            });
          }
          if (normChOpts.length === 0) {
            normChOpts.push(...resolveChannelsFromText(`${eff.title || ""} ${eff.prompt_text || ""} ${cleanContent}`));
          }
          if (normChOpts.length === 0) {
            for (const ch of CHANNEL_CONNECTION_CATALOG) {
              normChOpts.push({
                id: ch.id,
                channelType: ch.id,
                channelMode: ch.defaultMode,
                requiresToken: ch.requiresToken,
                label: ch.name,
                description: ch.description,
                prompt: `Tôi đã thiết lập và bật kênh ${ch.name} (/${ch.id}), hãy kiểm tra kết nối và tiếp tục.`,
              });
            }
          }
          const ixId = String(eff.id || eff.interaction_id || `ix_fenced_channel_${msg.id}`);
          if (!seenIds.has(ixId)) {
            seenIds.add(ixId);
            widgets.push({
              interactionId: ixId,
              kind: "connect_channel",
              promptText: String(eff.title || eff.prompt_text || `Thiết lập kênh giao tiếp (${normChOpts.map((c) => c.label).join(", ")})`),
              actionType: "connect_channel",
              options: normChOpts,
            });
          }
        } else if (kRaw === "connect_app" || kRaw === "connect_apps") {
          const detectedApps = resolveCatalogAppsFromText(`${JSON.stringify(eff.apps || [])} ${cleanContent}`);
          const ixId = String(eff.id || eff.interaction_id || `ix_fenced_app_${msg.id}`);
          if (!seenIds.has(ixId)) {
            seenIds.add(ixId);
            widgets.push({
              interactionId: ixId,
              kind: "connect_app",
              promptText: String(eff.title || eff.prompt_text || "Kết nối ứng dụng & công cụ MCP"),
              actionType: "connect_app",
              options: detectedApps,
            });
          }
        } else if ((kRaw === "choice" || kRaw === "options") && Array.isArray(eff.options) && eff.options.length > 0) {
          const ixId = String(eff.id || eff.interaction_id || `ix_fenced_opt_${msg.id}_${widgets.length}`);
          if (!seenIds.has(ixId)) {
            seenIds.add(ixId);
            widgets.push({
              interactionId: ixId,
              kind: "options",
              promptText: String(eff.title || eff.prompt_text || eff.question || "Chọn hướng thực hiện"),
              actionType: "fenced_choice",
              columns: Number(eff.columns) || 2,
              options: eff.options.map((o: any, idx: number) => ({
                id: String(o?.id || `opt_${idx}`),
                label: String(o?.label || o?.text || o?.title || o || `Lựa chọn ${idx + 1}`).trim(),
                prompt: String(o?.value || o?.prompt || o?.label || o?.text || o || "").trim(),
              })),
            });
          }
        }
      } catch {}
    }
  }

  // Automatic Smart Fallback: detect structured follow-up choices at the end of assistant prose
  if (widgets.length === 0 && cleanContent && cleanContent.length > 20) {
    const lines = cleanContent.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    const tailLines = lines.slice(-10);
    const hasChoiceQuestionCue = lines.some((l) =>
      /(?:bạn muốn|anh muốn|chị muốn|anh chọn|bạn chọn|chị chọn|chọn số|chọn hướng|chọn mục|bước tiếp theo|hướng nào|phương án nào|chọn 1 trong|lựa chọn|đưa \d+ hướng|would you like|which option|next step)/i.test(l)
    ) || (lines[lines.length - 1] || "").endsWith("?");
    if (hasChoiceQuestionCue) {
      const extractedChoices: SkyerInteractiveOption[] = [];
      for (const line of tailLines) {
        // Match "1. **Title** — description" or "1. Title: description" or "- **Title**"
        const boldMatch = line.match(/^(?:(\d+)[.)]|[-•*]|\[([A-D1-4])\])\s+\*\*([^*\n]{2,68})\*\*(?:\s*[:–—\-].*)?$/);
        const plainMatch = !boldMatch
          ? line.match(/^(?:(\d+)[.)]|[-•*]|\[([A-D1-4])\])\s+([^:*–—?\n]{3,68})(?:\s*[:–—\-]\s*(.+))?$/)
          : null;
        const m = boldMatch || plainMatch;
        if (m) {
          const cleanLabel = (m[3] || "").replace(/\*+/g, "").trim();
          const fullPrompt = line.replace(/^(?:(\d+)[.)]|[-•*]|\[([A-D1-4])\])\s+/, "").replace(/\*+/g, "").trim();
          if (cleanLabel && cleanLabel.length >= 2 && cleanLabel.length <= 68 && !cleanLabel.endsWith("?")) {
            extractedChoices.push({
              id: `auto_opt_${extractedChoices.length}`,
              label: cleanLabel,
              prompt: fullPrompt.length <= 160 ? fullPrompt : cleanLabel,
            });
          }
        }
      }
      if (extractedChoices.length >= 2 && extractedChoices.length <= 6) {
        widgets.push({
          interactionId: `ix_auto_${msg.id}`,
          kind: "options",
          promptText: "Chọn hướng thực hiện",
          actionType: "auto_followup",
          columns: 2,
          options: extractedChoices,
        });
      }
    }
  }

  // Automatic Channel Connection Card detection when assistant invites or guides setting up Telegram / Zalo / messaging channels
  const hasConnectChannelWidget = widgets.some((w) => w.kind === "connect_channel");
  if (!hasConnectChannelWidget && cleanContent && cleanContent.length > 12) {
    const channelCueRegex =
      /(?:kết nối kênh|thiết lập kênh|cấu hình kênh|bật kênh|bật kết nối tới kênh|connect channel|setup channel|configure channel|kết nối(?:\s+tài\s+khoản)?\s+telegram|thiết lập telegram|cấu hình telegram|bot telegram|@botfather|bot_token|bot token|kết nối(?:\s+tài\s+khoản)?\s+zalo|tích hợp(?:\s+tài\s+khoản)?\s+zalo|thiết lập zalo|cấu hình zalo|zalo web|chat\.zalo\.me|zalo oa|zalo zns|zalo cá nhân|kênh zalo|kênh liên lạc|kênh chat|kết nối discord|kết nối slack|kết nối whatsapp|kết nối feishu|kết nối lark|kết nối dingtalk|kết nối matrix)/i;
    if (channelCueRegex.test(cleanContent)) {
      const detectedChannels = resolveChannelsFromText(cleanContent);
      const effectiveChannels =
        detectedChannels.length > 0
          ? detectedChannels
          : CHANNEL_CONNECTION_CATALOG.map((ch) => ({
              id: ch.id,
              channelType: ch.id,
              channelMode: ch.defaultMode,
              requiresToken: ch.requiresToken,
              label: ch.name,
              description: ch.description,
              prompt: `Tôi đã thiết lập và bật kênh ${ch.name} (/${ch.id}), hãy kiểm tra kết nối và tiếp tục.`,
            }));
      widgets.push({
        interactionId: `ix_connect_channel_${msg.id}`,
        kind: "connect_channel",
        promptText:
          detectedChannels.length === 1
            ? `Thiết lập kênh ${detectedChannels[0].label}`
            : "Bạn muốn kết nối mình với kênh chat nào?",
        actionType: "connect_channel",
        options: effectiveChannels,
      });
    }
  }

  // Automatic Connect App Card detection when assistant invites or needs app/tool connection
  const hasConnectAppWidget = widgets.some((w) => w.kind === "connect_app");
  if (!hasConnectAppWidget && !widgets.some((w) => w.kind === "connect_channel") && cleanContent && cleanContent.length > 12) {
    const connectCueRegex =
      /(?:kết nối ứng dụng|kết nối app|connect app|connect applications?|chưa kết nối|cần kết nối|hãy kết nối|bấm connect apps|mở connect apps|cấp quyền oauth|liên kết tài khoản|chưa được kết nối|integrat(?:e|ion) with|connect your .* account)/i;
    if (connectCueRegex.test(cleanContent)) {
      const detectedApps = resolveCatalogAppsFromText(cleanContent);
      widgets.push({
        interactionId: `ix_connect_app_${msg.id}`,
        kind: "connect_app",
        promptText:
          detectedApps.length > 0
            ? `Kết nối ứng dụng (${detectedApps.map((a) => a.label).join(", ")})`
            : "Kết nối ứng dụng & công cụ MCP",
        actionType: "connect_app",
        options: detectedApps,
      });
    }
  }

  if (widgets.some((w) => w.kind === "connect_channel")) {
    const filtered = widgets.filter((w) => {
      if (w.kind !== "options") return true;
      const combinedOpts = (w.options || []).map((o) => `${o.label} ${o.prompt || ""}`).join(" ");
      return !/(?:zalo\s*oa|official\s*account|zns|webhook|nền\s*tảng\s*trung\s*gian|botfather|zalo\s*web)/i.test(combinedOpts);
    });
    filtered.sort((a, b) => (a.kind === "connect_channel" ? -1 : b.kind === "connect_channel" ? 1 : 0));
    return filtered;
  }

  return widgets;
}

function InlineLiveComputerPreviewCard({
  summary,
  agentId,
  onExtendSplitView,
  onOpenFullscreenModal,
}: {
  summary: BrowserExecutionSummary;
  agentId: string;
  onExtendSplitView: () => void;
  onOpenFullscreenModal: () => void;
}) {
  const [refreshTick, setRefreshTick] = useState(0);
  const cleanAgent = (agentId || "mons").replace(/^bot:agent360:/i, "");
  const displayHostname = (() => {
    if (!summary.url) return "computer.workspace";
    try {
      return new URL(summary.url).hostname;
    } catch {
      return summary.url;
    }
  })();

  return (
    <div
      data-testid="inline-live-computer-card"
      className="group/compcard relative w-full max-w-[360px] sm:max-w-[400px] my-1.5 rounded-2xl overflow-hidden border border-[#ECE5DC] dark:border-[#22222e] bg-white dark:bg-[#11151f] shadow-2xs hover:border-[var(--agent-primary)]/50 transition-all select-none"
    >
      {/* Single Unified Top Bar: Status Dot + Domain + Step Count + Hover Action Icons */}
      <div className="flex items-center justify-between gap-2 px-3 py-1.5 bg-[#F8F3ED]/90 dark:bg-[#0b0e15] border-b border-[#ECE5DC] dark:border-[#22222e] text-[11px] font-mono">
        <div className="flex items-center gap-1.5 min-w-0">
          <span
            title={summary.actionLabel}
            className={`h-2 w-2 rounded-full shrink-0 ${
              summary.isActivelyCalling ? "bg-emerald-400 animate-ping" : "bg-emerald-500"
            }`}
          />
          <Globe size={12} className="text-[#57534e] dark:text-neutral-400 shrink-0" />
          <span className="font-medium text-[#252522] dark:text-[#eceef2] truncate" title={summary.url || summary.actionLabel}>
            {displayHostname}
          </span>
          <span
            title={summary.actionLabel}
            className="px-1.5 py-0.2 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 text-[9px] shrink-0"
          >
            {summary.isActivelyCalling ? "LIVE" : `${summary.stepCount}`}
          </span>
        </div>

        {/* Single Icon-Only Toolbar in Header (Reveals extra actions on hover, zero duplicate overlay) */}
        <div className="flex items-center gap-0.5 shrink-0">
          <button
            type="button"
            data-ux-target-min="24"
            data-testid="computer-card-refresh-btn"
            aria-label="Làm mới màn hình Computer"
            title="Làm mới màn hình Computer"
            onClick={(e) => {
              e.stopPropagation();
              setRefreshTick((t) => t + 1);
            }}
            className="h-6 w-6 rounded-lg flex items-center justify-center opacity-0 group-hover/compcard:opacity-100 hover:bg-black/5 dark:hover:bg-white/10 text-[#57534e] dark:text-neutral-400 hover:text-[#252522] dark:hover:text-white transition-all cursor-pointer"
          >
            <RefreshCw size={11} />
          </button>

          <button
            type="button"
            data-ux-target-min="24"
            data-testid="computer-hover-fullscreen-btn"
            aria-label="Phóng to toàn màn hình Computer"
            title="Phóng to toàn màn hình Computer"
            onClick={(e) => {
              e.stopPropagation();
              onOpenFullscreenModal();
            }}
            className="h-6 w-6 rounded-lg flex items-center justify-center opacity-0 group-hover/compcard:opacity-100 hover:bg-black/5 dark:hover:bg-white/10 text-[#57534e] dark:text-neutral-400 hover:text-[#252522] dark:hover:text-white transition-all cursor-pointer"
          >
            <Maximize2 size={11} />
          </button>

          {summary.url && (
            <a
              href={summary.url}
              target="_blank"
              rel="noopener noreferrer"
              data-ux-target-min="24"
              aria-label="Mở trang web trong tab mới"
              title="Mở trang web trong tab mới"
              onClick={(e) => e.stopPropagation()}
              className="h-6 w-6 rounded-lg flex items-center justify-center opacity-0 group-hover/compcard:opacity-100 hover:bg-black/5 dark:hover:bg-white/10 text-[#57534e] dark:text-neutral-400 hover:text-[#252522] dark:hover:text-white transition-all"
            >
              <ExternalLink size={11} />
            </a>
          )}

          <button
            type="button"
            data-ux-target-min="24"
            data-testid="computer-card-extend-btn"
            aria-label="Mở rộng Computer sang khung bên phải (Extend Split View)"
            title="Mở rộng Computer sang khung bên phải (Extend Split View)"
            onClick={(e) => {
              e.stopPropagation();
              onExtendSplitView();
            }}
            className="h-6 w-6 rounded-lg flex items-center justify-center bg-[var(--agent-primary)]/15 hover:bg-[var(--agent-primary)]/25 text-[#252522] dark:text-white border border-[var(--agent-primary)]/30 transition-colors cursor-pointer"
          >
            <PanelLeftClose size={12} />
          </button>
        </div>
      </div>

      {/* Clean 16:10 Authenticated Preview Viewport (No duplicate floating dock or dark bottom bar) */}
      <div
        onClick={(e) => {
          e.stopPropagation();
          onExtendSplitView();
        }}
        title={`${summary.actionLabel} — Bấm để mở rộng Computer`}
        className="relative w-full h-[168px] sm:h-[188px] bg-[#FAF6F0] dark:bg-[#080a0f] flex items-center justify-center overflow-hidden cursor-pointer"
      >
        {summary.screenshotUrl ? (
          <img
            src={summary.screenshotUrl}
            alt=""
            className="w-full h-full object-cover object-top transition-transform duration-300 group-hover/compcard:scale-[1.01]"
            loading="lazy"
          />
        ) : (
          <AgentBrowserPreview
            key={`${cleanAgent}-${refreshTick}`}
            agentId={cleanAgent}
            enabled={true}
            intervalMs={summary.isActivelyCalling ? 3500 : 12000}
          />
        )}
      </div>
    </div>
  );
}

function InteractiveTurnWidgetsSection({
  widgets,
  messageId,
  claimedMap,
  isTurnBusy,
  connectedAppIds = [],
  onOpenConnectApps,
  onQuickConnectApp,
  channels = [],
  onOpenChannelsSettings,
  onOpenChannelConfig,
  onQuickSetupChannel,
  onOpenZaloWebBrowser,
  onSelectOption,
  onSubmitPoll,
  onSubmitInput,
  themePrimary,
  agentName,
  agentBrowser,
}: {
  widgets: SkyerInteractiveWidget[];
  messageId: string;
  claimedMap: Record<string, ClaimedInteractionRecord>;
  isTurnBusy?: boolean;
  connectedAppIds?: string[];
  onOpenConnectApps?: (searchQuery?: string) => void;
  onQuickConnectApp?: (widget: SkyerInteractiveWidget, appOpt: SkyerInteractiveOption) => Promise<void> | void;
  channels?: AgentChannelConfig[];
  onOpenChannelsSettings?: () => void;
  onOpenChannelConfig?: (channelType: string) => void;
  onQuickSetupChannel?: (
    widget: SkyerInteractiveWidget,
    chOpt: SkyerInteractiveOption,
    inlineConfig?: { botToken?: string; mode?: "web" | "webhook" | "bot" }
  ) => Promise<void> | void;
  onOpenZaloWebBrowser?: () => void;
  onSelectOption: (widget: SkyerInteractiveWidget, opt: SkyerInteractiveOption) => void;
  onSubmitPoll: (widget: SkyerInteractiveWidget, selectedOpts: SkyerInteractiveOption[]) => void;
  onSubmitInput: (widget: SkyerInteractiveWidget, value: string) => void;
  themePrimary?: string;
  agentName?: string;
  agentBrowser?: AgentBrowserInfo | null;
}) {
  const [pollSelections, setPollSelections] = useState<Record<string, string[]>>({});
  const [inputValues, setInputValues] = useState<Record<string, string>>({});
  const [channelTokens, setChannelTokens] = useState<Record<string, string>>({});
  const [channelModes, setChannelModes] = useState<Record<string, "web" | "webhook" | "bot">>({});
  const [selectedChannelIds, setSelectedChannelIds] = useState<Record<string, string>>({});
  const [expandedTokenInputs, setExpandedTokenInputs] = useState<Record<string, boolean>>({});
  const [focusedInputId, setFocusedInputId] = useState<string | null>(null);
  const [submittingId, setSubmittingId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  if (!widgets || widgets.length === 0) return null;

  return (
    <div
      data-testid={`chat-interactive-widgets-${messageId}`}
      className="flex flex-col items-start gap-2 w-full max-w-[85%] sm:max-w-[80%] mt-1"
    >
      {widgets.map((w) => {
        const claimed = claimedMap[w.interactionId];
        const isCardClaimed = Boolean(claimed);
        const isSubmittingThis = submittingId === w.interactionId && Boolean(isTurnBusy);

        const triggerSubmitState = () => {
          setSubmittingId(w.interactionId);
          setTimeout(() => {
            setSubmittingId((prev) => (prev === w.interactionId ? null : prev));
          }, 1800);
        };

        if (w.kind === "connect_channel") {
          const displayChannels: SkyerInteractiveOption[] =
            w.options && w.options.length > 0
              ? w.options
              : CHANNEL_CONNECTION_CATALOG.map((ch) => ({
                  id: ch.id,
                  channelType: ch.id,
                  channelMode: ch.defaultMode,
                  requiresToken: ch.requiresToken,
                  label: ch.name,
                  description: ch.description,
                  prompt: `Tôi đã thiết lập và bật kênh ${ch.name} (/${ch.id}), hãy tiếp tục.`,
                }));

          const rawAgentName = (agentName || "Agent").trim();
          const displayAgentName = rawAgentName.replace(/\s*\([^)]*\)/g, "").trim() || rawAgentName;
          const claimedId = (claimed?.selected_ids || [])[0] || "";
          const chosenChannelId =
            displayChannels.length === 1
              ? (displayChannels[0].channelType || displayChannels[0].id).toLowerCase().trim()
              : (selectedChannelIds[w.interactionId] || claimedId || "").toLowerCase().trim();

          const chosenChannelOpt = chosenChannelId
            ? displayChannels.find(
                (c) => (c.channelType || c.id).toLowerCase().trim() === chosenChannelId
              ) || displayChannels[0]
            : null;
          const chosenIdx = chosenChannelOpt
            ? Math.max(0, displayChannels.indexOf(chosenChannelOpt))
            : 0;
          const chosenLetter = String.fromCharCode(65 + (chosenIdx % 26));

          const renderSingleLeanChannelCard = (chOpt: SkyerInteractiveOption) => {
            const chType = (chOpt.channelType || chOpt.id).toLowerCase().trim();
            const liveCh = channels.find((c) => c.type.toLowerCase() === chType);
            const isZalo = chType === "zalo";
            const isTelegram = chType === "telegram";
            const tokenKey = `${w.interactionId}_${chType}`;
            const inlineToken = channelTokens[tokenKey] || "";
            const currentMode: "web" | "webhook" | "bot" =
              channelModes[tokenKey] ||
              (isZalo
                ? liveCh?.details?.mode === "webhook"
                  ? "webhook"
                  : "web"
                : "bot");
            const requiresTokenNow =
              (chOpt.requiresToken ?? (chType !== "zalo" && chType !== "whatsapp")) ||
              (isZalo && currentMode === "webhook");

            const isConfigEnabled =
              Boolean(liveCh?.enabled) ||
              (claimed?.selected_ids || []).includes(chType) ||
              (claimed?.selected_ids || []).includes(chOpt.id);

            const hasConfiguredToken = Boolean(
              liveCh?.details?.bot_token ||
                liveCh?.details?.client_secret ||
                liveCh?.details?.access_token ||
                inlineToken.trim()
            );

            // Real Channel Authentication & Connectivity Determination across all channels:
            // 1. Zalo in Web mode (QR login):
            // Check agent browser tabs: if tab is at id.zalo.me or contains QR login text, user hasn't finished login!
            const zaloBrowserTabs = agentBrowser?.tabs || [];
            const hasZaloLoginTab = zaloBrowserTabs.some(
              (t: AgentBrowserTab) => !t.anchor && (t.url || "").includes("id.zalo.me")
            );
            const hasZaloChatTab = zaloBrowserTabs.some(
              (t: AgentBrowserTab) => !t.anchor && (t.url || "").includes("chat.zalo.me") && !(t.url || "").includes("id.zalo.me")
            );

            let isConnected = false;
            let channelStatusLabel = "Connect";

            if (isZalo && currentMode === "web") {
              if (isConfigEnabled && hasZaloChatTab && !hasZaloLoginTab) {
                isConnected = true;
                channelStatusLabel = "Connected";
              } else if (isConfigEnabled) {
                isConnected = false;
                channelStatusLabel = "Quét QR";
              } else {
                isConnected = false;
                channelStatusLabel = "Bật Zalo Web";
              }
            } else if (requiresTokenNow) {
              if (isConfigEnabled && hasConfiguredToken) {
                isConnected = true;
                channelStatusLabel = "Connected";
              } else if (isConfigEnabled && !hasConfiguredToken) {
                isConnected = false;
                channelStatusLabel = "Nhập Token";
              } else {
                isConnected = false;
                channelStatusLabel = "Connect";
              }
            } else {
              isConnected = isConfigEnabled;
              channelStatusLabel = isConnected ? "Connected" : "Connect";
            }

            const isEnabled = isConnected;
            const isTokenDrawerOpen = Boolean(expandedTokenInputs[tokenKey]);
            const isThisChannelSubmitting =
              submittingId === `${w.interactionId}_${chType}` || isSubmittingThis;

            const triggerChannelSubmitting = () => {
              const key = `${w.interactionId}_${chType}`;
              setSubmittingId(key);
              setTimeout(() => {
                setSubmittingId((prev) => (prev === key ? null : prev));
              }, 1600);
            };

            return (
              <div
                key={chType}
                data-testid={`interactive-connect-channel-item-${chType}`}
                className="w-full max-w-md space-y-1.5"
              >
                <div className="flex flex-col gap-2.5 rounded-2xl px-4 py-3.5 bg-white dark:bg-[#16161d] border border-neutral-200/90 dark:border-[#262632] shadow-2xs transition-all">
                  <div className="flex items-center justify-between gap-3">
                    {/* Left: Rounded Squircle Logo + Channel Title with Verified Badge + Let <Agent> use <Channel> */}
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                      <div className="h-11 w-11 rounded-xl bg-neutral-50 dark:bg-white border border-neutral-200/80 dark:border-white/15 flex items-center justify-center p-2 shrink-0 overflow-hidden shadow-2xs">
                        <ChannelChatIcon channel={chType} isSelected={true} size={26} activeColor={themePrimary} />
                      </div>
                      <div className="flex flex-col min-w-0">
                        <div className="flex items-center gap-1.5">
                          <span className="text-[14.5px] font-semibold text-slate-900 dark:text-white truncate">
                            {chOpt.label}
                          </span>
                          {/* Official Verified Badge (Matching Image 3 & 4) */}
                          <svg
                            width="15"
                            height="15"
                            viewBox="0 0 24 24"
                            fill="none"
                            className="shrink-0"
                            aria-label="Verified Skyer Channel"
                          >
                            <circle cx="12" cy="12" r="10" fill="#3B82F6" />
                            <path
                              d="M8.5 12.3L10.8 14.6L15.6 9.8"
                              stroke="white"
                              strokeWidth="2.2"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                        </div>
                        <span className="text-[12.5px] text-neutral-500 dark:text-neutral-400 truncate">
                          {`Let ${displayAgentName} use ${chOpt.label}`}
                        </span>
                      </div>
                    </div>

                    {/* Right: Pill Connect Button / Loading Spinner Pill (Image 3 & 4) */}
                    <div className="flex items-center gap-1.5 shrink-0">
                      <button
                        type="button"
                        data-ux-target-min="24"
                        data-testid={`interactive-connect-channel-open-settings-${w.interactionId}`}
                        onClick={() => onOpenChannelsSettings?.()}
                        className="hidden"
                        aria-hidden="true"
                        tabIndex={-1}
                      />
                      <button
                        type="button"
                        data-ux-target-min="24"
                        data-testid={`interactive-connect-channel-config-${chType}`}
                        onClick={() => onOpenChannelConfig?.(chType)}
                        className="h-8 w-8 rounded-full flex items-center justify-center text-neutral-400 hover:text-slate-900 dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-white/10 transition-colors cursor-pointer"
                        title={`Cấu hình chi tiết kênh ${chOpt.label}`}
                        aria-label={`Cấu hình chi tiết kênh ${chOpt.label}`}
                      >
                        <SlidersHorizontal size={13} />
                      </button>

                      <button
                        type="button"
                        data-ux-target-min="24"
                        data-testid={`interactive-connect-channel-setup-${chType}`}
                        onClick={() => {
                          if (isZalo && currentMode === "web" && isConfigEnabled && !isConnected) {
                            onOpenZaloWebBrowser?.();
                            window.dispatchEvent(new CustomEvent("agent360_channel_browser_refresh"));
                            return;
                          }
                          if (requiresTokenNow && !hasConfiguredToken && !inlineToken.trim() && !isTokenDrawerOpen) {
                            setExpandedTokenInputs((prev) => ({ ...prev, [tokenKey]: true }));
                            return;
                          }
                          triggerChannelSubmitting();
                          if (onQuickSetupChannel) {
                            void onQuickSetupChannel(w, chOpt, {
                              botToken: inlineToken.trim() || undefined,
                              mode: currentMode,
                            });
                          } else {
                            onOpenChannelConfig?.(chType);
                          }
                        }}
                        className={`min-w-[96px] h-9 px-4 rounded-full text-[13px] font-semibold transition-all cursor-pointer shrink-0 flex items-center justify-center gap-1.5 active:scale-95 ${
                          isThisChannelSubmitting
                            ? "bg-neutral-200/80 dark:bg-[#2a2a35] text-neutral-500 dark:text-neutral-300 border border-neutral-300/60 dark:border-white/10"
                            : isEnabled
                            ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/25"
                            : "bg-slate-900 dark:bg-white text-white dark:text-slate-950 hover:opacity-90 shadow-2xs"
                        }`}
                      >
                        {isThisChannelSubmitting ? (
                          <Loader2 size={15} className="animate-spin text-neutral-500 dark:text-neutral-300" />
                        ) : isConnected ? (
                          <>
                            <Check size={13} />
                            <span>{inlineToken.trim() ? "Update" : "Connected"}</span>
                          </>
                        ) : isZalo && currentMode === "web" && isConfigEnabled ? (
                          <>
                            <QrCode size={13} />
                            <span>Quét QR</span>
                          </>
                        ) : requiresTokenNow && isConfigEnabled && !hasConfiguredToken ? (
                          <span>Nhập Token</span>
                        ) : (
                          <span>{channelStatusLabel}</span>
                        )}
                      </button>
                    </div>
                  </div>

                  {/* Compact Inline Token Input Drawer (only when a token-based channel needs a token or user toggled mode) */}
                  {(isTokenDrawerOpen || (requiresTokenNow && inlineToken.trim().length > 0)) && (
                    <div className="flex items-center gap-1.5 pt-2 border-t border-neutral-200/60 dark:border-white/10">
                      <input
                        type="password"
                        data-testid={`interactive-connect-channel-token-${chType}`}
                        value={inlineToken}
                        onChange={(e) =>
                          setChannelTokens((prev) => ({ ...prev, [tokenKey]: e.target.value }))
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter" && inlineToken.trim()) {
                            e.preventDefault();
                            triggerChannelSubmitting();
                            void onQuickSetupChannel?.(w, chOpt, {
                              botToken: inlineToken.trim(),
                              mode: currentMode,
                            });
                          }
                        }}
                        placeholder={
                          hasConfiguredToken
                            ? `•••••••• (Đã cấu hình ${chOpt.label} Token — nhập mới để cập nhật)`
                            : isTelegram
                            ? "Nhập Telegram Bot Token từ @BotFather (VD: 123456:ABC-DEF...)"
                            : isZalo
                            ? "Nhập Zalo Bot / OA Token..."
                            : `Nhập ${chOpt.label} Bot / Access Token...`
                        }
                        className="flex-1 bg-neutral-50 dark:bg-[#111117] border border-neutral-200 dark:border-[#2a2a38] rounded-xl px-3 py-1.5 text-[12px] text-slate-900 dark:text-white font-mono placeholder:text-neutral-400 focus:outline-none focus:border-blue-500"
                        autoFocus
                      />
                      {isZalo && (
                        <button
                          type="button"
                          data-testid={`interactive-connect-channel-zalo-mode-web-${w.interactionId}`}
                          onClick={() => {
                            setChannelModes((prev) => ({ ...prev, [tokenKey]: "web" }));
                            setExpandedTokenInputs((prev) => ({ ...prev, [tokenKey]: false }));
                          }}
                          className="px-2.5 py-1.5 rounded-xl text-[11px] font-mono bg-blue-500/15 text-blue-500 hover:bg-blue-500/25 cursor-pointer shrink-0"
                        >
                          Zalo Web (QR • Mặc định)
                        </button>
                      )}
                    </div>
                  )}

                  {/* Subtle Secondary Actions for Zalo (Open QR Browser or switch to Bot Token/OA) */}
                  {isZalo && !isTokenDrawerOpen && (
                    <div className="flex items-center justify-between gap-2 pt-1 text-[11px] text-neutral-400">
                      <span className="truncate font-mono">
                        Mặc định: Zalo Web (Quét QR trên trình duyệt Agent)
                      </span>
                      <div className="flex items-center gap-2.5 shrink-0">
                        {onOpenZaloWebBrowser && (
                          <button
                            type="button"
                            data-testid={`interactive-connect-channel-zalo-browser-${w.interactionId}`}
                            onClick={() => onOpenZaloWebBrowser()}
                            className="text-blue-500 hover:text-blue-400 hover:underline font-mono cursor-pointer flex items-center gap-1"
                          >
                            <Globe size={11} />
                            <span>Mở Zalo Web</span>
                          </button>
                        )}
                        <button
                          type="button"
                          data-testid={`interactive-connect-channel-zalo-mode-webhook-${w.interactionId}`}
                          onClick={() => {
                            setChannelModes((prev) => ({ ...prev, [tokenKey]: "webhook" }));
                            setExpandedTokenInputs((prev) => ({ ...prev, [tokenKey]: true }));
                          }}
                          className="hover:text-slate-700 dark:hover:text-neutral-200 hover:underline font-mono cursor-pointer"
                        >
                          Dùng Bot Token
                        </button>
                      </div>
                    </div>
                  )}
                </div>


              </div>
            );
          };

          return (
            <div
              key={w.interactionId}
              data-testid={`interactive-connect-channel-card-${w.interactionId}`}
              className="w-full max-w-md space-y-2.5 font-sans"
            >
              {/* Multi-channel Selector Card (Style Image 2 & Collapsed State in Image 3/4) */}
              {displayChannels.length > 1 && (
                <div
                  data-testid={`interactive-connect-channel-selector-${w.interactionId}`}
                  className="w-full rounded-2xl p-4 bg-white dark:bg-[#16161d] border border-neutral-200/90 dark:border-[#262632] shadow-2xs space-y-3"
                >
                  <div className="text-[14px] font-semibold text-slate-900 dark:text-neutral-100 leading-snug">
                    {w.promptText && !w.promptText.startsWith("Thiết lập kênh")
                      ? w.promptText
                      : "Bạn muốn kết nối mình với kênh chat nào?"}
                  </div>

                  {chosenChannelOpt ? (
                    /* Collapsed Selected Pill Row (Style Image 3 & 4 top card) */
                    <div className="flex items-center justify-between gap-2">
                      <button
                        type="button"
                        onClick={() =>
                          setSelectedChannelIds((prev) => {
                            const next = { ...prev };
                            delete next[w.interactionId];
                            return next;
                          })
                        }
                        className="inline-flex items-center gap-2.5 text-left group/selch cursor-pointer"
                        title="Bấm để đổi kênh kết nối khác"
                      >
                        <span className="h-6 w-6 rounded-lg bg-blue-600 text-white text-[12px] font-semibold flex items-center justify-center shrink-0 shadow-2xs">
                          {chosenLetter}
                        </span>
                        <span className="text-[14px] font-medium text-slate-900 dark:text-white group-hover/selch:underline">
                          {chosenChannelOpt.label}
                        </span>
                      </button>

                      <button
                        type="button"
                        onClick={() =>
                          setSelectedChannelIds((prev) => {
                            const next = { ...prev };
                            delete next[w.interactionId];
                            return next;
                          })
                        }
                        className="text-[11px] font-mono text-neutral-400 hover:text-slate-800 dark:hover:text-neutral-200 cursor-pointer"
                      >
                        Đổi kênh
                      </button>
                    </div>
                  ) : (
                    /* Full A / B / C / D Channel Option List (Style Image 2) */
                    <div className="space-y-1.5">
                      {displayChannels.map((chOpt, idx) => {
                        const letter = String.fromCharCode(65 + (idx % 26));
                        const cType = (chOpt.channelType || chOpt.id).toLowerCase().trim();
                        const isLiveEnabled = channels.some(
                          (c) => c.type.toLowerCase() === cType && c.enabled
                        );
                        return (
                          <button
                            key={`${cType}-${idx}`}
                            type="button"
                            data-testid={`interactive-connect-channel-option-${cType}`}
                            onClick={() =>
                              setSelectedChannelIds((prev) => ({
                                ...prev,
                                [w.interactionId]: cType,
                              }))
                            }
                            className="w-full flex items-center justify-between gap-3 px-2.5 py-2 rounded-xl hover:bg-neutral-100/80 dark:hover:bg-white/5 text-left transition-colors cursor-pointer group/chopt"
                          >
                            <div className="flex items-center gap-3 min-w-0">
                              <span className="h-6 w-6 rounded-lg bg-neutral-100 dark:bg-[#22222c] border border-neutral-200/80 dark:border-white/10 group-hover/chopt:bg-blue-600 group-hover/chopt:border-blue-600 group-hover/chopt:text-white text-neutral-600 dark:text-neutral-300 text-[12px] font-medium flex items-center justify-center shrink-0 transition-colors">
                                {letter}
                              </span>
                              <ChannelChatIcon channel={cType} isSelected={true} size={16} />
                              <span className="text-[13.5px] font-medium text-slate-900 dark:text-neutral-100 truncate">
                                {chOpt.label}
                              </span>
                            </div>
                            {isLiveEnabled && (
                              <span className="text-[10.5px] font-mono text-emerald-500 shrink-0">
                                Connected
                              </span>
                            )}
                          </button>
                        );
                      })}

                      <button
                        type="button"
                        onClick={() => onOpenChannelsSettings?.()}
                        className="w-full flex items-center gap-3 px-2.5 py-2 rounded-xl hover:bg-neutral-100/80 dark:hover:bg-white/5 text-left transition-colors cursor-pointer group/chopt"
                      >
                        <span className="h-6 w-6 rounded-lg bg-neutral-100 dark:bg-[#22222c] border border-neutral-200/80 dark:border-white/10 text-neutral-500 dark:text-neutral-400 text-[12px] font-medium flex items-center justify-center shrink-0">
                          {String.fromCharCode(65 + (displayChannels.length % 26))}
                        </span>
                        <span className="text-[13.5px] text-neutral-400 dark:text-neutral-500">
                          Something else
                        </span>
                      </button>
                    </div>
                  )}
                </div>
              )}

              {/* Lean Single-Row Connect Card (Style Image 3 & 4) */}
              {chosenChannelOpt && renderSingleLeanChannelCard(chosenChannelOpt)}
            </div>
          );
        }

        if (w.kind === "connect_app") {
          const displayApps: SkyerInteractiveOption[] =
            w.options && w.options.length > 0
              ? w.options
              : APPS_CATALOG.slice(0, 4).map((a) => ({
                  id: a.id,
                  appSlug: a.id,
                  label: a.name,
                  description: a.description,
                  logoUrl: a.logoUrl,
                  prompt: `Tôi đã kết nối ứng dụng ${a.name} (/${a.id}), hãy tiếp tục.`,
                }));
          const allTargetConnected =
            displayApps.length > 0 &&
            displayApps.every((a) => connectedAppIds.includes((a.appSlug || a.id).toLowerCase()));

          return (
            <div
              key={w.interactionId}
              data-testid={`interactive-connect-app-card-${w.interactionId}`}
              className="group/ixcard w-full max-w-md rounded-2xl p-3 sm:p-3.5 bg-white dark:bg-[#121218] border border-neutral-200/90 dark:border-[#22222e] hover:border-[var(--agent-primary)]/45 shadow-2xs space-y-2.5 font-sans transition-all duration-200"
            >
              {/* Header */}
              <div className="flex items-center justify-between gap-2 px-0.5">
                <div className="flex items-center gap-2 min-w-0">
                  <div
                    style={{ color: themePrimary }}
                    className="h-6 w-6 rounded-lg bg-[var(--agent-primary)]/15 border border-[var(--agent-primary)]/30 flex items-center justify-center shrink-0"
                  >
                    <Layers size={12} />
                  </div>
                  <span className="text-[13.5px] font-semibold text-slate-900 dark:text-white leading-snug truncate">
                    {w.promptText || "Kết nối ứng dụng & công cụ MCP"}
                  </span>
                </div>

                <button
                  type="button"
                  data-ux-target-min="24"
                  data-testid={`interactive-connect-app-open-modal-${w.interactionId}`}
                  onClick={() => onOpenConnectApps?.(w.options.length === 1 ? w.options[0].label : "")}
                  style={{ color: themePrimary }}
                  className="text-[11px] font-mono font-semibold px-2 py-0.5 rounded-lg bg-[var(--agent-primary)]/10 hover:bg-[var(--agent-primary)]/20 border border-[var(--agent-primary)]/25 transition-colors cursor-pointer shrink-0 flex items-center gap-1"
                  title="Mở kho ứng dụng Connect Apps"
                >
                  <Plus size={10} />
                  <span>Connect Apps</span>
                </button>
              </div>

              {/* App Items List */}
              <div className="space-y-1.5">
                {displayApps.map((appOpt, aIdx) => {
                  const slug = (appOpt.appSlug || appOpt.id).toLowerCase().replace(/^composio_/, "");
                  const isConnected =
                    connectedAppIds.includes(slug) ||
                    (claimed?.selected_ids || []).includes(slug) ||
                    (claimed?.selected_ids || []).includes(appOpt.id);
                  const logoUrl = appOpt.logoUrl || `https://logos.composio.dev/api/${slug}`;

                  return (
                    <div
                      key={`${slug}-${aIdx}`}
                      data-testid={`interactive-connect-app-item-${slug}`}
                      className="flex items-center justify-between gap-2.5 p-2 rounded-xl bg-neutral-50/90 dark:bg-[#171721] border border-neutral-200/80 dark:border-[#242432] hover:border-[var(--agent-primary)]/35 transition-all"
                    >
                      <div className="flex items-center gap-2.5 min-w-0 flex-1">
                        <div className="h-8 w-8 rounded-lg bg-white dark:bg-[#20202e] border border-neutral-200/80 dark:border-[#2c2c3e] flex items-center justify-center p-1.5 shrink-0 overflow-hidden shadow-2xs">
                          <img
                            src={logoUrl}
                            alt={appOpt.label}
                            className="h-full w-full object-contain"
                            onError={(e) => {
                              (e.currentTarget as HTMLElement).style.display = "none";
                            }}
                          />
                        </div>
                        <div className="flex flex-col min-w-0">
                          <span className="text-[13px] font-semibold text-slate-900 dark:text-white truncate">
                            {appOpt.label}
                          </span>
                          <span className="text-[11px] text-neutral-500 dark:text-neutral-400 truncate">
                            {appOpt.description || `Tích hợp ${appOpt.label} qua Composio MCP`}
                          </span>
                        </div>
                      </div>

                      <button
                        type="button"
                        data-ux-target-min="24"
                        data-testid={`interactive-connect-app-action-${slug}`}
                        onClick={() => {
                          triggerSubmitState();
                          if (onQuickConnectApp) {
                            void onQuickConnectApp(w, appOpt);
                          } else {
                            onOpenConnectApps?.(appOpt.label);
                          }
                        }}
                        style={!isConnected ? { backgroundColor: themePrimary } : undefined}
                        className={`px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-all cursor-pointer shrink-0 flex items-center gap-1 active:scale-95 ${
                          isConnected
                            ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/25"
                            : "text-white shadow-2xs hover:brightness-105"
                        }`}
                      >
                        {isSubmittingThis ? (
                          <Loader2 size={11} className="animate-spin" />
                        ) : isConnected ? (
                          <>
                            <Check size={11} />
                            <span>Đã kết nối</span>
                          </>
                        ) : (
                          <>
                            <Plus size={11} />
                            <span>Kết nối</span>
                          </>
                        )}
                      </button>
                    </div>
                  );
                })}
              </div>

              {/* Footer Status / Browse All Apps */}
              <div className="flex items-center justify-between pt-0.5 px-0.5 text-[11px] text-neutral-500 dark:text-neutral-400">
                <span className="truncate">
                  {allTargetConnected
                    ? "✓ Tất cả ứng dụng yêu cầu đã sẵn sàng"
                    : `Đang kết nối ${connectedAppIds.length} ứng dụng trên Agent`}
                </span>
                <button
                  type="button"
                  onClick={() => onOpenConnectApps?.("")}
                  className="hover:text-slate-900 dark:hover:text-white hover:underline font-mono text-[10.5px] cursor-pointer shrink-0"
                >
                  Xem tất cả 60+ apps →
                </button>
              </div>
            </div>
          );
        }

        if (w.kind === "poll") {
          const currentSelected = pollSelections[w.interactionId] || claimed?.selected_ids || [];
          const hasDirtyPollSelection =
            Boolean(pollSelections[w.interactionId]) &&
            pollSelections[w.interactionId].length > 0 &&
            JSON.stringify(pollSelections[w.interactionId]) !== JSON.stringify(claimed?.selected_ids || []);
          const isPollActivelyInteracting = (!isCardClaimed && currentSelected.length > 0) || hasDirtyPollSelection;

          const pollCardSurfaceClass = isPollActivelyInteracting
            ? "ring-1 ring-[var(--agent-primary)]/45 border-[var(--agent-primary)]/60 opacity-100 blur-none shadow-sm transition-all duration-200"
            : isCardClaimed
            ? "opacity-45 blur-[1.2px] hover:opacity-100 hover:blur-none focus-within:opacity-100 focus-within:blur-none border-neutral-200/90 dark:border-[#22222e] transition-all duration-200"
            : "border-neutral-200/90 dark:border-[#22222e] transition-all duration-200";

          const togglePollChoice = (optId: string) => {
            setPollSelections((prev) => {
              const cur = prev[w.interactionId] || claimed?.selected_ids || [];
              if (w.allowsMultiple) {
                return {
                  ...prev,
                  [w.interactionId]: cur.includes(optId) ? cur.filter((x) => x !== optId) : [...cur, optId],
                };
              }
              return { ...prev, [w.interactionId]: [optId] };
            });
          };

          return (
            <div
              key={w.interactionId}
              data-testid={`interactive-poll-card-${w.interactionId}`}
              className={`group/ixcard w-full max-w-md rounded-2xl p-3 bg-white dark:bg-[#121218] border shadow-2xs space-y-2 font-sans ${pollCardSurfaceClass}`}
            >
              <div className="flex items-center justify-between gap-2 px-1">
                <div className="flex items-center gap-1.5 min-w-0">
                  <span
                    title={
                      isSubmittingThis
                        ? "Đang gửi lựa chọn..."
                        : isPollActivelyInteracting
                        ? `Đang chọn ${currentSelected.length} mục — bấm Gửi để xác nhận`
                        : isCardClaimed
                        ? "Đã gửi lựa chọn — rê chuột vào để chọn lại"
                        : "Chờ bạn chọn phương án"
                    }
                    className={`h-2 w-2 rounded-full shrink-0 ${
                      isSubmittingThis || isPollActivelyInteracting
                        ? "bg-amber-400 animate-pulse"
                        : isCardClaimed
                        ? "bg-emerald-500"
                        : "bg-neutral-300 dark:bg-neutral-600"
                    }`}
                  />
                  <span className="text-[13.5px] font-semibold text-slate-900 dark:text-white leading-snug truncate">
                    {w.promptText}
                  </span>
                </div>
                <span
                  title={w.allowsMultiple ? "Cho phép chọn nhiều phương án" : "Chỉ chọn 1 phương án"}
                  className={`text-[10px] font-mono px-1.5 py-0.5 rounded-md border shrink-0 transition-colors ${
                    isPollActivelyInteracting
                      ? "bg-[var(--agent-primary)]/15 border-[var(--agent-primary)]/40 text-[#252522] dark:text-white font-semibold"
                      : "bg-neutral-100 dark:bg-[#1c1c26] border-neutral-200/80 dark:border-[#2b2b3a] text-neutral-500 dark:text-neutral-400"
                  }`}
                >
                  {isPollActivelyInteracting ? `${currentSelected.length} chọn` : w.allowsMultiple ? "Multi" : "1x"}
                </span>
              </div>

              <div className="space-y-1">
                {w.options.map((opt, oIdx) => {
                  const optionLetter = String.fromCharCode(65 + (oIdx % 26));
                  const isChecked =
                    currentSelected.includes(opt.id) ||
                    (!pollSelections[w.interactionId] && (claimed?.selected_labels || []).includes(opt.label));
                  return (
                    <button
                      key={opt.id}
                      type="button"
                      onClick={() => togglePollChoice(opt.id)}
                      className={`w-full px-2.5 py-1.5 rounded-xl text-left transition-all cursor-pointer group/ixbtn flex items-center justify-between gap-2.5 min-w-0 border ${
                        isChecked
                          ? isCardClaimed && !isPollActivelyInteracting
                            ? "bg-[var(--agent-primary)]/10 border-[var(--agent-primary)]/50 text-slate-950 dark:text-white font-medium opacity-55 blur-[0.8px] group-hover/ixcard:opacity-100 group-hover/ixcard:blur-none hover:opacity-100 hover:blur-none"
                            : "bg-[var(--agent-primary)]/15 border-[var(--agent-primary)]/60 text-slate-950 dark:text-white font-medium shadow-2xs"
                          : "border-transparent hover:bg-neutral-100/80 dark:hover:bg-[#1a1a24] text-slate-800 dark:text-neutral-200"
                      }`}
                    >
                      <div className="flex items-center gap-2.5 min-w-0 flex-1">
                        <span
                          className={`h-5 w-5 rounded-md border text-[11px] font-mono font-medium flex items-center justify-center shrink-0 transition-colors ${
                            isChecked
                              ? "bg-[var(--agent-primary)] border-[var(--agent-primary)] text-white"
                              : "bg-neutral-100 dark:bg-[#1c1c26] border-neutral-200/90 dark:border-[#2b2b3a] text-neutral-600 dark:text-neutral-300"
                          }`}
                        >
                          {isChecked ? <Check size={11} /> : optionLetter}
                        </span>
                        <span className="text-[13.5px] truncate">{opt.label}</span>
                      </div>
                    </button>
                  );
                })}
              </div>

              <div className="flex items-center justify-between gap-2 pt-1 px-1">
                {claimed && !isPollActivelyInteracting ? (
                  <div className="flex items-center gap-1.5 text-[11px] font-mono text-emerald-600 dark:text-emerald-400 truncate">
                    <Check size={11} className="shrink-0" />
                    <span className="truncate">{(claimed.selected_labels || []).join(", ")}</span>
                  </div>
                ) : <span />}
                <button
                  type="button"
                  data-ux-target-min="24"
                  data-testid={`interactive-poll-submit-${w.interactionId}`}
                  aria-label="Gửi lựa chọn khảo sát"
                  title="Gửi lựa chọn khảo sát"
                  disabled={currentSelected.length === 0}
                  onClick={() => {
                    const chosen = w.options.filter((o) => currentSelected.includes(o.id));
                    if (chosen.length > 0) {
                      triggerSubmitState();
                      onSubmitPoll(w, chosen);
                    }
                  }}
                  style={{ backgroundColor: themePrimary }}
                  className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-white text-xs font-semibold shadow-2xs disabled:opacity-40 transition-all cursor-pointer active:scale-95 ${
                    claimed && !isPollActivelyInteracting ? "opacity-0 group-hover/ixcard:opacity-100" : "opacity-100"
                  }`}
                >
                  {isSubmittingThis ? <Loader2 size={11} className="animate-spin" /> : <Send size={11} />}
                  <span>{currentSelected.length}</span>
                </button>
              </div>
            </div>
          );
        }

        if (w.kind === "force_reply") {
          const val = inputValues[w.interactionId] ?? claimed?.input_value ?? "";
          const trimmedVal = val.trim();
          const isFocused = focusedInputId === w.interactionId;
          const isEditedSinceClaim =
            inputValues[w.interactionId] !== undefined &&
            trimmedVal !== (claimed?.input_value || "").trim();
          const isInputActivelyInteracting =
            isFocused || (!isCardClaimed && trimmedVal.length > 0) || (isCardClaimed && isEditedSinceClaim && trimmedVal.length > 0);
          const isUrlLike = /^https?:\/\/[^\s]+$/i.test(trimmedVal);

          const inputCardSurfaceClass = isInputActivelyInteracting
            ? "ring-1 ring-[var(--agent-primary)]/45 border-[var(--agent-primary)]/60 opacity-100 blur-none shadow-sm transition-all duration-200"
            : isCardClaimed
            ? "opacity-45 blur-[1.2px] hover:opacity-100 hover:blur-none focus-within:opacity-100 focus-within:blur-none border-neutral-200/90 dark:border-[#22222e] transition-all duration-200"
            : "border-neutral-200/90 dark:border-[#22222e] transition-all duration-200";

          return (
            <div
              key={w.interactionId}
              data-testid={`interactive-input-card-${w.interactionId}`}
              className={`group/ixcard w-full max-w-md rounded-2xl p-3 bg-white dark:bg-[#121218] border shadow-2xs space-y-2 font-sans ${inputCardSurfaceClass}`}
            >
              <div className="flex items-center justify-between gap-2 px-0.5">
                <div className="flex items-center gap-1.5 min-w-0">
                  <span
                    title={
                      isSubmittingThis
                        ? "Đang gửi phản hồi..."
                        : isInputActivelyInteracting
                        ? "Đang nhập liệu — nhấn Enter hoặc bấm nút Gửi"
                        : isCardClaimed
                        ? `Đã gửi: ${claimed?.input_value || ""}`
                        : "Đang chờ bạn nhập thông tin"
                    }
                    className={`h-2 w-2 rounded-full shrink-0 transition-colors ${
                      isSubmittingThis || isInputActivelyInteracting
                        ? "bg-amber-400 animate-pulse"
                        : isCardClaimed
                        ? "bg-emerald-500"
                        : "bg-neutral-300 dark:bg-neutral-600"
                    }`}
                  />
                  <span className="text-[13px] font-semibold text-slate-800 dark:text-neutral-200 truncate">
                    {w.promptText}
                  </span>
                </div>

                {/* Live Contextual Micro-Indicator (Icon-Only + Tooltip) */}
                <div className="flex items-center gap-1 shrink-0">
                  {isSubmittingThis ? (
                    <span
                      title="Đang gửi phản hồi..."
                      className="h-5 w-5 rounded-md bg-[var(--agent-primary)]/15 text-[var(--agent-primary)] flex items-center justify-center"
                    >
                      <Loader2 size={11} className="animate-spin" />
                    </span>
                  ) : isInputActivelyInteracting && trimmedVal.length > 0 ? (
                    <span
                      title="Nhấn Enter để gửi nhanh"
                      className="px-1.5 py-0.2 rounded-md bg-neutral-100 dark:bg-[#1c1c26] border border-neutral-200/80 dark:border-[#2b2b3a] text-[9.5px] font-mono text-neutral-500 dark:text-neutral-400 select-none"
                    >
                      ↵
                    </span>
                  ) : isCardClaimed ? (
                    <span
                      title={`Đã gửi: ${claimed?.input_value || ""} — Bấm vào ô để sửa và gửi lại`}
                      className="h-5 w-5 rounded-md bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center justify-center"
                    >
                      <Check size={11} />
                    </span>
                  ) : null}
                </div>
              </div>

              <div className="flex items-center gap-1.5">
                <div className="relative flex-1 flex items-center min-w-0">
                  {isUrlLike && (
                    <Globe
                      size={12}
                      style={{ color: themePrimary }}
                      className="absolute left-2.5 pointer-events-none shrink-0 transition-opacity"
                    />
                  )}
                  <input
                    type="text"
                    value={val}
                    placeholder={w.placeholder || "Nhập phản hồi..."}
                    onFocus={() => setFocusedInputId(w.interactionId)}
                    onBlur={() => setFocusedInputId((prev) => (prev === w.interactionId ? null : prev))}
                    onChange={(e) => setInputValues((prev) => ({ ...prev, [w.interactionId]: e.target.value }))}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && trimmedVal) {
                        e.preventDefault();
                        triggerSubmitState();
                        onSubmitInput(w, trimmedVal);
                      }
                    }}
                    className={`w-full ${isUrlLike ? "pl-7" : "pl-2.5"} ${
                      trimmedVal && isInputActivelyInteracting ? "pr-7" : "pr-2.5"
                    } py-1.5 rounded-lg bg-neutral-50 dark:bg-[#181822] border text-[13px] text-slate-900 dark:text-white focus:outline-none transition-all ${
                      isInputActivelyInteracting
                        ? "border-[var(--agent-primary)] bg-white dark:bg-[#14141d] ring-2 ring-[var(--agent-primary)]/15"
                        : isCardClaimed
                        ? "border-emerald-500/35 text-slate-700 dark:text-neutral-300"
                        : "border-neutral-200/90 dark:border-[#2b2b3a]"
                    }`}
                  />
                  {trimmedVal && isInputActivelyInteracting && (
                    <button
                      type="button"
                      aria-label="Xóa nội dung đang nhập"
                      title="Xóa nội dung đang nhập"
                      onMouseDown={(e) => {
                        e.preventDefault();
                        setInputValues((prev) => ({ ...prev, [w.interactionId]: "" }));
                      }}
                      className="absolute right-1.5 h-5 w-5 rounded-md hover:bg-neutral-200/70 dark:hover:bg-white/10 text-neutral-400 hover:text-neutral-700 dark:hover:text-white flex items-center justify-center transition-colors cursor-pointer"
                    >
                      <X size={11} />
                    </button>
                  )}
                </div>

                <button
                  type="button"
                  data-ux-target-min="24"
                  data-testid={`interactive-input-submit-${w.interactionId}`}
                  aria-label={isCardClaimed && !isEditedSinceClaim ? "Đã gửi (Bấm để gửi lại)" : "Gửi thông tin"}
                  title={isCardClaimed && !isEditedSinceClaim ? "Đã gửi (Bấm để gửi lại)" : "Gửi thông tin (Enter)"}
                  disabled={!trimmedVal}
                  onClick={() => {
                    if (trimmedVal) {
                      triggerSubmitState();
                      onSubmitInput(w, trimmedVal);
                    }
                  }}
                  style={{
                    backgroundColor: isCardClaimed && !isInputActivelyInteracting ? undefined : themePrimary,
                  }}
                  className={`h-8 w-8 rounded-lg flex items-center justify-center disabled:opacity-35 cursor-pointer shrink-0 transition-all active:scale-95 ${
                    isCardClaimed && !isInputActivelyInteracting
                      ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/25"
                      : "text-white shadow-2xs hover:brightness-105"
                  }`}
                >
                  {isSubmittingThis ? (
                    <Loader2 size={12} className="animate-spin" />
                  ) : isCardClaimed && !isInputActivelyInteracting ? (
                    <Check size={13} />
                  ) : (
                    <Send size={12} />
                  )}
                </button>
              </div>
            </div>
          );
        }

        // Default: "options" or "reply_keyboard" -> Blur when claimed, unblur on hover to allow re-selection
        const optionsCardSurfaceClass = isCardClaimed
          ? "opacity-45 blur-[1.2px] hover:opacity-100 hover:blur-none focus-within:opacity-100 focus-within:blur-none border-neutral-200/90 dark:border-[#22222e] transition-all duration-200"
          : "border-neutral-200/90 dark:border-[#22222e] hover:border-[var(--agent-primary)]/40 transition-all duration-200";

        return (
          <div
            key={w.interactionId}
            data-testid={`interactive-options-card-${w.interactionId}`}
            className={`group/ixcard w-full max-w-md rounded-2xl bg-white dark:bg-[#121218] border p-3 sm:p-3.5 shadow-2xs space-y-2 font-sans ${optionsCardSurfaceClass}`}
          >
            {w.promptText && w.actionType !== "auto_followup" && (
              <div className="flex items-center justify-between gap-2 px-1">
                <div className="flex items-center gap-1.5 min-w-0">
                  <span
                    title={
                      isSubmittingThis
                        ? "Đang gửi lựa chọn..."
                        : isCardClaimed
                        ? "Đã chọn — rê chuột vào để chọn lại"
                        : "Chọn một phương án bên dưới"
                    }
                    className={`h-2 w-2 rounded-full shrink-0 ${
                      isSubmittingThis
                        ? "bg-amber-400 animate-pulse"
                        : isCardClaimed
                        ? "bg-emerald-500"
                        : "bg-[var(--agent-primary)]"
                    }`}
                  />
                  <span className="text-[13.5px] font-semibold text-slate-900 dark:text-white leading-snug truncate">
                    {w.promptText}
                  </span>
                </div>
                {claimed && (
                  <span
                    title="Đã chọn — Rê chuột vào để chọn lại"
                    aria-label="Đã chọn — Rê chuột vào để chọn lại"
                    className="h-5 w-5 rounded-md bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center justify-center shrink-0"
                  >
                    <Check size={11} />
                  </span>
                )}
              </div>
            )}

            <div className="space-y-1">
              {w.options.map((opt, oIdx) => {
                const optionLetter = String.fromCharCode(65 + (oIdx % 26));
                const isSelected =
                  (claimed?.selected_ids || []).includes(opt.id) ||
                  (claimed?.selected_labels || []).includes(opt.label);

                if (opt.url) {
                  return (
                    <a
                      key={opt.id + oIdx}
                      href={opt.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      data-testid={`cta-option-url-${opt.id}`}
                      title={`Mở liên kết: ${opt.url}`}
                      className="w-full px-2.5 py-1.5 rounded-xl hover:bg-neutral-100/80 dark:hover:bg-[#1a1a24] text-left transition-all cursor-pointer group flex items-center justify-between gap-2.5 min-w-0"
                    >
                      <div className="flex items-center gap-2.5 min-w-0 flex-1">
                        <span className="h-6 w-6 rounded-md bg-neutral-100 dark:bg-[#1c1c26] border border-neutral-200/90 dark:border-[#2b2b3a] text-neutral-600 dark:text-neutral-300 group-hover:border-[var(--agent-primary)]/50 flex items-center justify-center shrink-0 transition-colors">
                          <ExternalLink size={11} />
                        </span>
                        <span className="text-[13.5px] text-slate-800 dark:text-neutral-200 group-hover:text-slate-950 dark:group-hover:text-white truncate">
                          {opt.label}
                        </span>
                      </div>
                      <ArrowUpRight size={13} style={{ color: themePrimary }} className="transition-all opacity-0 group-hover:opacity-100 shrink-0" />
                    </a>
                  );
                }

                if (opt.copy_text) {
                  const isCopied = copiedId === `${w.interactionId}:${opt.id}`;
                  return (
                    <button
                      key={opt.id + oIdx}
                      type="button"
                      data-testid={`cta-option-copy-${opt.id}`}
                      title={`Sao chép: ${opt.copy_text}`}
                      aria-label={`Sao chép ${opt.label}`}
                      onClick={() => {
                        navigator.clipboard.writeText(opt.copy_text!);
                        setCopiedId(`${w.interactionId}:${opt.id}`);
                        setTimeout(() => setCopiedId(null), 1800);
                      }}
                      className="w-full px-2.5 py-1.5 rounded-xl hover:bg-neutral-100/80 dark:hover:bg-[#1a1a24] text-left transition-all cursor-pointer group flex items-center justify-between gap-2.5 min-w-0"
                    >
                      <div className="flex items-center gap-2.5 min-w-0 flex-1">
                        <span className="h-6 w-6 rounded-md bg-neutral-100 dark:bg-[#1c1c26] border border-neutral-200/90 dark:border-[#2b2b3a] text-neutral-600 dark:text-neutral-300 flex items-center justify-center shrink-0">
                          {isCopied ? <Check size={11} className="text-emerald-500" /> : <Copy size={11} />}
                        </span>
                        <span className="text-[13.5px] text-slate-800 dark:text-neutral-200 truncate">
                          {opt.label}
                        </span>
                      </div>
                    </button>
                  );
                }

                return (
                  <button
                    key={opt.id + oIdx}
                    type="button"
                    data-testid={`cta-option-btn-${opt.id}`}
                    title={isSelected ? `Đã chọn: ${opt.label} (Bấm để chọn lại)` : (opt.prompt || opt.label)}
                    onClick={() => {
                      triggerSubmitState();
                      onSelectOption(w, opt);
                    }}
                    className={`w-full px-2.5 py-1.5 rounded-xl text-left transition-all duration-150 cursor-pointer group/ixbtn flex items-center justify-between gap-2.5 min-w-0 border active:scale-[0.99] ${
                      isSelected
                        ? "bg-[var(--agent-primary)]/10 border-[var(--agent-primary)]/40 text-slate-950 dark:text-white font-medium opacity-50 blur-[0.8px] hover:opacity-100 hover:blur-none"
                        : "border-transparent hover:bg-neutral-100/80 dark:hover:bg-[#1a1a24] text-slate-800 dark:text-neutral-200"
                    }`}
                  >
                    <div className="flex items-center gap-2.5 min-w-0 flex-1">
                      <span
                        className={`h-6 w-6 rounded-md border text-[12px] font-medium flex items-center justify-center shrink-0 transition-colors ${
                          isSelected
                            ? "bg-[var(--agent-primary)] border-[var(--agent-primary)] text-white"
                            : "bg-neutral-100 dark:bg-[#1c1c26] border-neutral-200/90 dark:border-[#2b2b3a] text-neutral-600 dark:text-neutral-300 group-hover/ixbtn:border-[var(--agent-primary)]/50 group-hover/ixbtn:text-slate-900 dark:group-hover/ixbtn:text-white"
                        }`}
                      >
                        {isSelected && isSubmittingThis ? (
                          <Loader2 size={11} className="animate-spin" />
                        ) : isSelected ? (
                          <Check size={12} />
                        ) : (
                          optionLetter
                        )}
                      </span>
                      <span className="text-[13.5px] group-hover/ixbtn:text-slate-950 dark:group-hover/ixbtn:text-white transition-colors block truncate">
                        {opt.label}
                      </span>
                    </div>
                    <ArrowRight
                      size={13}
                      style={{ color: themePrimary }}
                      className="transition-all shrink-0 opacity-0 group-hover/ixbtn:opacity-100 group-hover/ixbtn:translate-x-0.5"
                    />
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// Formatted assistant message content with word wrapping and code block containment
function FormattedMessageContent({
  content,
  onRunCode,
  agentNode,
  onSpeakSentence,
  onImageClick,
  themeColor,
}: {
  content: string;
  onRunCode?: (code: string, lang: string) => void;
  agentNode?: string;
  onSpeakSentence?: (sentence: string) => void;
  onImageClick?: (url: string, name: string) => void;
  themeColor?: string;
}) {
  const [runningBlock, setRunningBlock] = useState<number | null>(null);
  const [runOutputs, setRunOutputs] = useState<Record<number, { output: string; exitCode: number }>>({});
  const [copiedBlock, setCopiedBlock] = useState<number | null>(null);
  const [expandedBlock, setExpandedBlock] = useState<number | null>(null);

  const handleCopyCode = (code: string, idx: number) => {
    playMicroClick();
    navigator.clipboard.writeText(code);
    setCopiedBlock(idx);
    setTimeout(() => setCopiedBlock(null), 1800);
  };

  if (!content) return null;

  const cleanedDisplayContent = content
    .replace(/```skyer-interaction\/v1\s*\n[\s\S]*?```/gi, "")
    .replace(/```(?:json)?\s*\n\s*\{[\s\S]*?"(?:skyer-interaction\/v1|connect_channel|connect_app)"[\s\S]*?\}\s*```/gi, "")
    .trim();
  if (!cleanedDisplayContent) return null;

  // Split code blocks: ```lang ... ```
  const codeBlockRegex = /(```[\s\S]*?```)/g;
  const parts = cleanedDisplayContent.split(codeBlockRegex);

  return (
    <div className="space-y-1.5 text-[14.5px] sm:text-[15px] leading-snug select-text min-w-0 max-w-full break-words">
      {parts.map((part, idx) => {
        if (part.startsWith("```") && part.endsWith("```")) {
          const match = part.match(/^```(\w+)?\s*\n([\s\S]*?)```$/);
          const lang = match ? match[1] || "shell" : "code";
          const code = match ? match[2] : part.slice(3, -3);

          if (lang === "mermaid") {
            return <MermaidDiagram key={idx} code={code} />;
          }

          return (
            <div
              key={idx}
              className={`my-2 rounded-xl overflow-hidden border border-slate-200 dark:border-[#222230] bg-slate-900 dark:bg-[#0c0c12] font-mono text-xs shadow-md transition-all max-w-full ${
                expandedBlock === idx ? "fixed inset-2 sm:inset-4 z-50 flex flex-col bg-[#0a0a0f]/95 border-[#f8a87c]/40 shadow-2xl p-2" : ""
              }`}
            >
              {/* Clean Minimal Header */}
              <div className="px-3 py-1.5 bg-slate-800/80 dark:bg-[#14141c] border-b border-slate-700/60 dark:border-[#1e1e28] flex items-center justify-between gap-1.5 text-[11px] text-neutral-400 select-none min-w-0">
                <div className="flex items-center gap-1.5 min-w-0 truncate">
                  <Terminal size={12} className="text-[#f8a87c] shrink-0" />
                  <span className="font-semibold text-slate-200 truncate capitalize">{lang}</span>
                  <span className="text-[10px] text-neutral-500 font-mono hidden md:inline">
                    ({code.trim().split("\n").length} lines)
                  </span>
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  {onRunCode && (lang === "bash" || lang === "sh" || lang === "shell" || lang === "python" || lang === "sql") && (
                    <button
                      aria-label="Execute code on node"
                      data-ux-target-min="24"
                      type="button"
                      onClick={() => {
                        setRunningBlock(idx);
                        onRunCode(code, lang);
                        setTimeout(() => {
                          setRunOutputs((prev) => ({
                            ...prev,
                            [idx]: {
                              output: `Dispatched to ${agentNode || "Agent Sandbox"} terminal process.\nExit code 0 (Verified).`,
                              exitCode: 0,
                            },
                          }));
                          setRunningBlock(null);
                        }, 700);
                      }}
                      className="hidden sm:flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-mono text-emerald-400 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/30 transition-colors cursor-pointer"
                      title="Run code snippet"
                    >
                      <Play size={10} fill="currentColor" />
                      <span>{runningBlock === idx ? "Running..." : "Run"}</span>
                    </button>
                  )}
                  <button
                    aria-label={expandedBlock === idx ? "Collapse code block" : "Expand code block"}
                    data-ux-target-min="24"
                    type="button"
                    onClick={() => setExpandedBlock(expandedBlock === idx ? null : idx)}
                    className="p-1 rounded hover:bg-white/10 text-neutral-400 hover:text-white transition-colors cursor-pointer"
                    title={expandedBlock === idx ? "Collapse code block" : "Expand code block"}
                  >
                    {expandedBlock === idx ? <Minimize2 size={12} /> : <Maximize2 size={12} />}
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      const extMap: Record<string, string> = {
                        bash: "sh", sh: "sh", shell: "sh", zsh: "sh",
                        python: "py", py: "py",
                        javascript: "js", js: "js", typescript: "ts", ts: "ts",
                        sql: "sql", json: "json", yaml: "yaml", yml: "yml",
                        html: "html", css: "css", markdown: "md", md: "md"
                      };
                      const ext = extMap[lang.toLowerCase()] || "txt";
                      const blob = new Blob([code], { type: "text/plain;charset=utf-8" });
                      const a = document.createElement("a");
                      a.href = URL.createObjectURL(blob);
                      a.download = `snippet-${Date.now()}.${ext}`;
                      a.click();
                      URL.revokeObjectURL(a.href);
                    }}
                    className="hidden sm:flex items-center text-neutral-400 hover:text-white transition-colors cursor-pointer p-1 rounded hover:bg-white/10"
                    title="Tải mã nguồn về máy"
                  >
                    <Download size={11} />
                  </button>

                  <button
                    type="button"
                    onClick={() => handleCopyCode(code, idx)}
                    className={`flex items-center gap-1 px-2 py-0.5 rounded-md transition-all cursor-pointer text-[10px] font-mono ${
                      copiedBlock === idx
                        ? "text-emerald-400 bg-emerald-500/15 border border-emerald-500/30 shadow-xs scale-105"
                        : "text-neutral-300 hover:text-white hover:bg-white/10 border border-transparent active:scale-95"
                    }`}
                    title="Sao chép toàn bộ khối mã"
                  >
                    {copiedBlock === idx ? (
                      <>
                        <Check size={11} className="text-emerald-400 stroke-[2.5]" />
                        <span className="text-emerald-400 font-semibold">Copied</span>
                      </>
                    ) : (
                      <>
                        <Copy size={11} />
                        <span>Copy</span>
                      </>
                    )}
                  </button>
                </div>
              </div>

              {/* Code Body with Smooth Responsive Horizontal Scroll */}
              <pre className="p-3 sm:p-3.5 overflow-x-auto text-neutral-200 font-mono text-[11px] sm:text-xs leading-relaxed whitespace-pre max-h-80 overflow-y-auto overscroll-contain">
                <code>{code}</code>
              </pre>
              {runOutputs[idx] && (
                <div className="px-3 py-2 bg-[#0c0c12] border-t border-[#1e1e28] text-[10px] font-mono text-emerald-400">
                  <div className="flex items-center gap-1.5 text-neutral-400 mb-1">
                    <Check size={11} className="text-emerald-400" />
                    <span>Terminal Output (Exit Code {runOutputs[idx].exitCode}):</span>
                  </div>
                  <pre className="text-neutral-300 whitespace-pre-wrap">{runOutputs[idx].output}</pre>
                </div>
              )}
            </div>
          );
        }

        // Preprocess: join split markdown links [label]\n(url) -> [label](url)
        const normalizedPart = part.replace(/\[([^\]\n]+)\]\s*\n\s*\((https?:\/\/[^\s)]+)\)/g, "[$1]($2)");
        const rawLines = normalizedPart.split("\n");

        type BlockItem =
          | { type: "table"; headers: string[]; rows: string[][] }
          | { type: "line"; line: string; trimmed: string };

        const blockItems: BlockItem[] = [];
        let tableBuffer: string[] = [];

        const flushTableBuffer = () => {
          if (tableBuffer.length > 0) {
            blockItems.push({ type: "table", ...parseMarkdownTableBlock(tableBuffer) });
            tableBuffer = [];
          }
        };

        for (let l = 0; l < rawLines.length; l++) {
          const rawLine = rawLines[l];
          const tr = rawLine.trim();
          if (tr.startsWith("|") && (tr.endsWith("|") || tr.includes("|", 1))) {
            tableBuffer.push(tr);
            continue;
          }
          flushTableBuffer();
          blockItems.push({ type: "line", line: rawLine, trimmed: tr });
        }
        flushTableBuffer();

        return (
          <div key={idx} className="space-y-1.5 max-w-full overflow-hidden">
            {blockItems.map((blk, blkIdx) => {
              if (blk.type === "table") {
                return (
                  <div key={blkIdx} className="relative group/tbl my-2.5 max-w-full">
                    <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-[#252532] bg-white/70 dark:bg-[#0e0e14]/90 shadow-2xs">
                    <table className="w-full text-left text-xs border-collapse">
                      {blk.headers.length > 0 && (
                        <thead>
                          <tr className="border-b border-slate-200 dark:border-[#252532] bg-slate-50 dark:bg-[#161620]">
                            {blk.headers.map((h, hIdx) => (
                              <th key={hIdx} className="px-3 py-2 font-semibold text-slate-800 dark:text-white font-mono text-[11px] whitespace-nowrap">
                                {renderInlineMarkdown(h, themeColor)}
                              </th>
                            ))}
                          </tr>
                        </thead>
                      )}
                      <tbody className="divide-y divide-slate-100 dark:divide-[#1d1d28]">
                        {blk.rows.map((row, rIdx) => (
                          <tr key={rIdx} className="hover:bg-slate-50/60 dark:hover:bg-[#14141e]/70 transition-colors">
                            {row.map((cell, cIdx) => (
                              <td key={cIdx} className="px-3 py-2 text-slate-700 dark:text-neutral-300 align-top leading-relaxed text-[12px]">
                                {renderInlineMarkdown(cell, themeColor)}
                              </td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="pointer-events-none absolute inset-y-0 right-0 w-6 rounded-r-xl bg-gradient-to-l from-black/20 dark:from-black/40 to-transparent opacity-0 sm:group-hover/tbl:opacity-100 transition-opacity" />
                </div>
                );
              }

              const line = blk.line;
              const trimmed = blk.trimmed;
              if (!trimmed) {
                return <div key={blkIdx} className="h-2" />;
              }

              // Subtle split dash separator (---, ***, ___)
              if (trimmed === "---" || trimmed === "***" || trimmed === "___" || /^[-*_]{3,}$/.test(trimmed)) {
                return (
                  <div key={blkIdx} className="my-3 py-1 flex items-center">
                    <div className="w-full border-t border-dashed border-[#2b2b38]/70" />
                  </div>
                );
              }

              if (trimmed.startsWith("### ")) {
                return (
                  <div key={blkIdx} className="pt-2 pb-0.5">
                    <h4 className="text-xs font-bold text-slate-900 dark:text-neutral-200 tracking-wide font-mono flex items-center gap-2">
                      <span style={{ backgroundColor: themeColor || "#f8a87c" }} className="h-1 w-1 rounded-full opacity-80" />
                      {trimmed.slice(4)}
                    </h4>
                  </div>
                );
              }
              if (trimmed.startsWith("## ")) {
                return (
                  <div key={blkIdx} className="pt-3 pb-1 border-b border-dashed border-slate-200 dark:border-[#232330]">
                    <h3 className="text-sm font-semibold text-slate-900 dark:text-white tracking-tight flex items-center gap-2">
                      <span style={{ color: themeColor || "#f8a87c" }} className="text-xs">§</span>
                      {trimmed.slice(3)}
                    </h3>
                  </div>
                );
              }
              if (trimmed.startsWith("# ")) {
                return (
                  <div key={blkIdx} className="pt-3 pb-1.5 border-b border-dashed border-slate-200 dark:border-[#2b2b3a]">
                    <h2 style={{ color: themeColor || "#f8a87c" }} className="text-base font-bold tracking-tight">
                      {trimmed.slice(2)}
                    </h2>
                  </div>
                );
              }
              if (trimmed.startsWith("- ") || trimmed.startsWith("* ") || trimmed.startsWith("• ") || trimmed.startsWith("↳ ")) {
                const bulletSymbol = trimmed.startsWith("↳ ") ? "↳" : "•";
                const sliceLen = trimmed.startsWith("↳ ") ? 2 : (trimmed.startsWith("• ") ? 2 : 2);
                return (
                  <div key={blkIdx} className="flex items-start gap-2.5 pl-1.5 py-1 text-slate-700 dark:text-neutral-300 leading-relaxed">
                    <span style={{ color: themeColor || "#f8a87c" }} className="shrink-0 text-[12px] font-mono select-none mt-0.5 opacity-90 font-bold">{bulletSymbol}</span>
                    <span className="flex-1 break-words leading-relaxed">{renderInlineMarkdown(trimmed.slice(sliceLen), themeColor)}</span>
                  </div>
                );
              }

              // Numbered list items: 1. 2. 3. (Với khoảng thở rõ ràng chuẩn Claude/Grok)
              const numMatch = trimmed.match(/^(\d+)\.\s+(.*)$/);
              if (numMatch) {
                return (
                  <div key={blkIdx} className="flex items-start gap-2.5 pl-1.5 py-1 text-slate-700 dark:text-neutral-300 leading-relaxed">
                    <span style={{ color: themeColor || "#f8a87c" }} className="font-mono text-[12px] shrink-0 select-none mt-0.5 opacity-95 font-bold">
                      {numMatch[1]}.
                    </span>
                    <span className="flex-1 break-words leading-relaxed">{renderInlineMarkdown(numMatch[2], themeColor)}</span>
                  </div>
                );
              }

              // Markdown image detection (![alt](url/base64))
              const imgMatch = trimmed.match(/^!\[([^\]]*)\]\((data:image\/[a-zA-Z]+;base64,[A-Za-z0-9+/=]+|https?:\/\/[^\s\)]+|\/[^\s\)]+)\)$/);
              if (imgMatch) {
                const alt = imgMatch[1] || "Browser Screenshot Preview";
                const src = imgMatch[2];
                return (
                  <div key={blkIdx} className="my-2.5 max-w-full">
                    <div
                      onClick={() => onImageClick?.(src, alt)}
                      className="group relative inline-block max-w-full rounded-xl overflow-hidden border border-slate-200 dark:border-[#2b2b3c] bg-white dark:bg-[#0c0c12] shadow-sm hover:border-[var(--agent-primary)]/50 transition-all cursor-zoom-in"
                    >
                      <img
                        src={src}
                        alt={alt}
                        className="max-h-[360px] w-auto max-w-full object-contain block rounded-lg transition-transform duration-200 group-hover:scale-[1.01]"
                        loading="lazy"
                      />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1.5 text-white font-mono text-[11px] select-none pointer-events-none">
                        <Maximize2 size={13} />
                        <span>Xem ảnh toàn màn hình</span>
                      </div>
                      {alt && (
                        <div className="px-3 py-1 bg-slate-50 dark:bg-[#14141c] border-t border-slate-200 dark:border-[#22222e] text-[11px] font-mono text-slate-600 dark:text-neutral-400 truncate">
                          {alt}
                        </div>
                      )}
                    </div>
                  </div>
                );
              }

              return (
                <p
                  key={blkIdx}
                  onDoubleClick={() => onSpeakSentence?.(trimmed)}
                  title="Double click to read this sentence aloud"
                  className="text-slate-800 dark:text-neutral-200 leading-relaxed break-words hover:text-slate-900 dark:hover:text-white transition-colors cursor-text"
                >
                  {renderInlineMarkdown(line, themeColor)}
                </p>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}


export interface AgentBrowserMeta {
  url: string;
  label: string;
  isLive: boolean;
  hostNode: string;
  profile: string;
  mode: string;
}

// Per-agent browser identity resolved by the backend (/api/agents/{id}/browser). Each instance
// has one Selkies desktop; agents differ by their own Chromium profile window.
export function inferAgentViewerUrlFallback(agent?: InfraAgent | null): string {
  if (!agent) return "";
  const slug = (agent.slug || agent.id || "").replace(/^bot:agent360:/i, "").toLowerCase();
  const node = (agent.node || "").toLowerCase();
  if (slug.startsWith("gm-") || slug === "gm" || node.includes("6th")) return "https://browser-gm.antares.vn";
  if (slug.startsWith("climax") || node.includes("climax")) return "https://browser-climax.antares.vn";
  if (slug.startsWith("planthy") || node.includes("planthy")) return "https://browser-planthy.hmz.one";
  if (slug.startsWith("its-") || slug === "its") return "https://browser-its.antares.vn";
  if (slug.startsWith("gl-") || slug === "gl" || node.includes("8th")) return "https://browser-gl.antares.vn";
  if (slug.startsWith("qwenpaw-test") || node.includes("7th")) return "https://browser-test.antares.vn";
  if (["mons", "ken", "zen", "mkai", "default-core", "default"].includes(slug) || node.includes("3rd") || node.includes("core")) {
    return "https://browser.hmz.one";
  }
  return "";
}

export function getAgentBrowserUrl(agent: InfraAgent, info?: AgentBrowserInfo | null): AgentBrowserMeta {
  // The backend is authoritative: an agent without a browser MCP binding (404) gets no guessed desktop host.
  const fallbackUrl = info || hasNoBrowser(agent.slug || agent.id || "") ? "" : inferAgentViewerUrlFallback(agent);
  return {
    url: info?.viewerUrl || fallbackUrl,
    label: `${agent.name} Computer`,
    isLive: info ? Boolean(info.cdpReachable && info.profileWindowOpen) : Boolean(fallbackUrl),
    hostNode: info ? `${info.node} · ${info.service}` : agent.node || "",
    profile: info?.profile || (agent.slug || agent.id || ""),
    mode: "Selkies desktop · CDP",
  };
}

/**
 * Interactive Selkies desktop for one agent. Focuses the agent's own profile window first,
 * reloads the stream when the page returns from background (mobile Safari/Chrome suspend
 * websockets), and retries with backoff if the desktop is unreachable.
 */
function SelkiesViewer({
  agentId,
  url,
  title,
  profile,
  reloadKey = 0,
  isResizing = false,
  onCaptureScreenshot,
  isScreenshotCaptured = false,
  screenshotTooltip,
  onReloadSession,
  isReloadingSession = false,
  reloadSessionTooltip,
  onToggleMaximize,
  isMaximized = false,
  maximizeTooltip,
  onCloseBrowser,
  closeTooltip,
}: {
  agentId: string;
  url: string;
  title: string;
  profile: string;
  reloadKey?: number;
  isResizing?: boolean;
  onCaptureScreenshot?: () => void;
  isScreenshotCaptured?: boolean;
  screenshotTooltip?: string;
  onReloadSession?: () => void;
  isReloadingSession?: boolean;
  reloadSessionTooltip?: string;
  onToggleMaximize?: () => void;
  isMaximized?: boolean;
  maximizeTooltip?: string;
  onCloseBrowser?: () => void;
  closeTooltip?: string;
}) {
  const [mobileInteractionMode, setMobileInteractionMode] = useState<"touch" | "mouse">("touch");
  const [attempt, setAttempt] = useState(0);
  const [isLandscapeRotated, setIsLandscapeRotated] = useState<boolean>(false);
  const [isPhoneClient, setIsPhoneClient] = useState<boolean>(() => {
    if (typeof window !== "undefined") {
      const uaDataMob = typeof navigator !== "undefined" && Boolean((navigator as any).userAgentData?.mobile);
      const uaMob = uaDataMob || (typeof navigator !== "undefined" && /Android|iPhone|iPod|Windows Phone|Mobile|Silk|CriOS|FxiOS/i.test(navigator.userAgent || ""));
      const hasTouch = typeof navigator !== "undefined" && Number(navigator.maxTouchPoints || 0) > 0;
      const coarse =
        typeof window.matchMedia === "function" &&
        window.matchMedia("(pointer: coarse)").matches &&
        (window.innerWidth < 960 || window.innerHeight < 560 || Math.min(window.screen.width, window.screen.height) < 600);
      return window.innerWidth < 768 || coarse || uaMob || (hasTouch && Math.min(window.innerWidth, window.innerHeight) < 600);
    }
    return false;
  });
  const [browserViewModeOverride, setBrowserViewModeOverride] = useState<"phone" | "desktop" | null>(() => {
    try {
      const saved = sessionStorage.getItem(`skyer_browser_view_mode_${agentId}`);
      if (saved === "phone" || saved === "desktop") return saved;
    } catch {}
    return null;
  });
  useEffect(() => {
    try {
      const saved = sessionStorage.getItem(`skyer_browser_view_mode_${agentId}`);
      setBrowserViewModeOverride(saved === "phone" || saved === "desktop" ? saved : null);
    } catch {}
    selectedTabIdRef.current = "";
    setSelectedTabId("");
    setBrowserTabs([]);
    setAddressInput("");
    setTabLoadingById({});
    liveTabMetaRef.current = {};
  }, [agentId]);
  const effectiveViewMode: "phone" | "desktop" = browserViewModeOverride ?? (isPhoneClient ? "phone" : "desktop");
  const isDesktopSiteMode = effectiveViewMode === "desktop";
  const setIsDesktopSiteMode = (next: boolean | ((prev: boolean) => boolean)) => {
    const curDesktop = effectiveViewMode === "desktop";
    const resolved = typeof next === "function" ? next(curDesktop) : next;
    const nextMode = resolved ? "desktop" : "phone";
    setBrowserViewModeOverride(nextMode);
    try {
      sessionStorage.setItem(`skyer_browser_view_mode_${agentId}`, nextMode);
    } catch {}
  };
  const [isVirtualKeyboardOpen, setIsVirtualKeyboardOpen] = useState<boolean>(false);
  const [virtualKeyboardHeight, setVirtualKeyboardHeight] = useState<number>(0);
  const isVirtualKeyboardOpenRef = useRef<boolean>(false);
  const [boxSize, setBoxSize] = useState<{ w: number; h: number }>({ w: 0, h: 0 });
  const [browserTabs, setBrowserTabs] = useState<AgentBrowserTab[]>([]);
  const browserTabsRef = useRef<AgentBrowserTab[]>([]);
  browserTabsRef.current = browserTabs;
  const [selectedTabId, setSelectedTabId] = useState<string>("");
  const [addressInput, setAddressInput] = useState<string>("");
  const [isEditingAddress, setIsEditingAddress] = useState<boolean>(false);
  const [isNavigating, setIsNavigating] = useState<boolean>(false);
  // Real page loading state per tab, pushed by the backend screencast (Page.loadingState from CDP lifecycle events)
  const [tabLoadingById, setTabLoadingById] = useState<Record<string, boolean>>({});
  const tabLoadingByIdRef = useRef<Record<string, boolean>>({});
  tabLoadingByIdRef.current = tabLoadingById;
  const loadingSafetyTimersRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({});
  // Latest URL/title pushed by the live stream per tab; overrides possibly stale polled tab metadata for a short window.
  const liveTabMetaRef = useRef<Record<string, { url: string; title: string; at: number }>>({});
  // Optimistically show loading the instant a navigation is requested; Page.loadingState events then own the state.
  const markTabLoading = (tabId: string, loading: boolean) => {
    if (!tabId) return;
    const prevTimer = loadingSafetyTimersRef.current[tabId];
    if (prevTimer) clearTimeout(prevTimer);
    delete loadingSafetyTimersRef.current[tabId];
    if (loading) {
      loadingSafetyTimersRef.current[tabId] = setTimeout(() => {
        delete loadingSafetyTimersRef.current[tabId];
        setTabLoadingById((prev) => (prev[tabId] ? { ...prev, [tabId]: false } : prev));
      }, 20000);
    }
    setTabLoadingById((prev) => (Boolean(prev[tabId]) === loading ? prev : { ...prev, [tabId]: loading }));
  };
  useEffect(() => () => {
    Object.values(loadingSafetyTimersRef.current).forEach((t) => clearTimeout(t));
  }, []);
  const [isHistoryOpen, setIsHistoryOpen] = useState<boolean>(false);
  const [isBrowserMoreMenuOpen, setIsBrowserMoreMenuOpen] = useState<boolean>(false);
  const [historyItems, setHistoryItems] = useState<AgentBrowserHistoryItem[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState<boolean>(false);
  const [isFindOpen, setIsFindOpen] = useState<boolean>(false);
  const [findQuery, setFindQuery] = useState<string>("");
  const [browserZoomPercent, setBrowserZoomPercent] = useState<number>(100);
  const [vpnStatus, setVpnStatus] = useState<AgentBrowserVpnStatus | null>(null);
  const [isTogglingVpn, setIsTogglingVpn] = useState<boolean>(false);
  const findInputRef = useRef<HTMLInputElement>(null);

  // Stream Engine Mode: "canvas" (CDP GPU <canvas> + predictive 120Hz scroll) vs "webrtc" (Selkies WebRTC H.264/VP9 60fps stream)
  const [streamEngineMode, setStreamEngineMode] = useState<"canvas" | "webrtc">("canvas");
  const [webrtcSignedUrl, setWebrtcSignedUrl] = useState<string>("");
  const [webrtcStatus, setWebrtcStatus] = useState<"idle" | "connecting" | "ready" | "fallback">("idle");
  const [webrtcErrorMsg, setWebrtcErrorMsg] = useState<string>("");

  // Chrome Omnibox Autocomplete State (History + Recent Searches + Live Google Suggestions)
  const [searchSuggestions, setSearchSuggestions] = useState<string[]>([]);
  const [omniboxActiveIdx, setOmniboxActiveIdx] = useState<number>(0);
  const [localHistoryEntries, setLocalHistoryEntries] = useState<Array<{ title: string; url: string; isSearch?: boolean }>>(() => {
    try {
      const raw = localStorage.getItem(`skyer_browser_omnibox_hist_${agentId}`);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {}
    return [];
  });

  const containerRef = useRef<HTMLDivElement>(null);
  const addressInputRef = useRef<HTMLInputElement>(null);
  const hiddenAt = useRef<number>(0);
  const tabFrameCacheRef = useRef<Record<string, string>>({});
  const tabOrderRef = useRef<string[]>([]);
  const tabOrderLoadedForRef = useRef<string>("");
  const closedTabsUntilRef = useRef<Map<string, number>>(new Map());
  const tabMutationLockUntilRef = useRef<number>(0);
  const lastNonAnchorTabsRef = useRef<{ tabs: AgentBrowserTab[]; at: number }>({ tabs: [], at: 0 });
  const autoNewTabAttemptedAtRef = useRef<Record<string, number>>({});
  const selectedTabIdRef = useRef<string>("");
  selectedTabIdRef.current = selectedTabId;
  const isEditingAddressRef = useRef<boolean>(false);
  isEditingAddressRef.current = isEditingAddress;
  const activeAgentIdRef = useRef<string>(agentId);
  activeAgentIdRef.current = agentId;
  const tabOpQueueRef = useRef<Promise<void>>(Promise.resolve());
  const enqueueTabMutation = (op: () => Promise<void>) => {
    tabOpQueueRef.current = tabOpQueueRef.current.then(op).catch(() => {});
    return tabOpQueueRef.current;
  };
  const computeActiveBrowserViewport = (modeOverride?: "phone" | "desktop") => {
    const hideChromeHeaderOnPhoneFullscreen = Boolean(isMaximized && isPhoneClient);
    const chromeHeaderOffset = hideChromeHeaderOnPhoneFullscreen ? 0 : 76;
    const rawW = isLandscapeRotated
      ? Math.max(320, boxSize.h)
      : Math.max(320, boxSize.w);
    const rawH = isLandscapeRotated
      ? Math.max(240, boxSize.w - chromeHeaderOffset)
      : Math.max(240, boxSize.h - chromeHeaderOffset);
    const scaleFactor = browserZoomPercent < 100 ? 100 / Math.max(50, browserZoomPercent) : 1;
    const targetMode = modeOverride ?? effectiveViewMode;
    const effectiveMob = targetMode === "phone";
    if (effectiveMob) {
      const isLandscape = isLandscapeRotated || rawW > rawH;
      if (!isPhoneClient) {
        if (isLandscape) {
          return {
            w: Math.min(932, Math.max(640, Math.round(844 * scaleFactor))),
            h: Math.min(480, Math.max(320, Math.round(390 * scaleFactor))),
            isMobile: true,
          };
        }
        return {
          w: Math.min(430, Math.max(375, Math.round(390 * scaleFactor))),
          h: Math.min(932, Math.max(640, Math.round(844 * scaleFactor))),
          isMobile: true,
        };
      }
      if (isLandscape) {
        const mobH = Math.max(320, Math.min(480, rawH));
        const mobW = Math.round(rawW * (mobH / Math.max(1, rawH)));
        return {
          w: Math.min(1080, Math.max(480, Math.round(mobW * scaleFactor))),
          h: Math.min(480, Math.max(240, Math.round(mobH * scaleFactor))),
          isMobile: true,
        };
      }
      const mobW = Math.max(360, rawW);
      const mobH = Math.round(rawH * (mobW / Math.max(1, rawW)));
      return {
        w: Math.min(480, Math.round(mobW * scaleFactor)),
        h: Math.min(1080, Math.round(mobH * scaleFactor)),
        isMobile: true,
      };
    }
    const aspect = rawH / Math.max(1, rawW);
    let fhdW = 1920;
    let fhdH = Math.round(fhdW * aspect);
    if (fhdH > 1080) {
      fhdH = 1080;
      fhdW = Math.round(fhdH / Math.max(0.2, aspect));
    }
    return {
      w: Math.max(640, Math.min(1920, Math.round(fhdW * scaleFactor))),
      h: Math.max(360, Math.min(1080, Math.round(fhdH * scaleFactor))),
      isMobile: false,
    };
  };

  const handleSetBrowserViewMode = async (nextMode: "phone" | "desktop") => {
    triggerHaptic(8);
    setBrowserViewModeOverride(nextMode);
    try {
      sessionStorage.setItem(`skyer_browser_view_mode_${agentId}`, nextMode);
    } catch {}
    setIsBrowserMoreMenuOpen(false);
    const nextVp = computeActiveBrowserViewport(nextMode);
    setIsNavigating(true);
    try {
      await dispatchAgentBrowserInput(agentId, {
        action: "resize",
        width: nextVp.w,
        height: nextVp.h,
        pageId: selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined,
        isMobile: nextVp.isMobile,
        deviceType: nextVp.isMobile ? "phone" : "desktop",
        reloadOnModeChange: true,
      });
    } finally {
      setIsNavigating(false);
      setTimeout(refreshBrowserTabs, 260);
    }
  };
  if (tabOrderLoadedForRef.current !== agentId) {
    tabOrderLoadedForRef.current = agentId;
    tabMutationLockUntilRef.current = 0;
    closedTabsUntilRef.current.clear();
    lastNonAnchorTabsRef.current = { tabs: [], at: 0 };
    try {
      const saved = sessionStorage.getItem(`skyer_browser_tab_order_${agentId}`);
      const parsed = saved ? JSON.parse(saved) : null;
      tabOrderRef.current = Array.isArray(parsed) ? parsed : [];
    } catch {
      tabOrderRef.current = [];
    }
  }
  const draggingTabIdRef = useRef<string | null>(null);
  const [draggingTabId, setDraggingTabId] = useState<string | null>(null);
  const [dragOverTabId, setDragOverTabId] = useState<string | null>(null);

  const persistTabOrder = (order: string[]) => {
    tabOrderRef.current = order;
    try {
      sessionStorage.setItem(`skyer_browser_tab_order_${agentId}`, JSON.stringify(order));
    } catch {}
  };

  const reconcileTabsWithOrder = (incoming: AgentBrowserTab[]): AgentBrowserTab[] => {
    const now = Date.now();
    for (const [cid, exp] of closedTabsUntilRef.current.entries()) {
      if (now > exp) closedTabsUntilRef.current.delete(cid);
    }
    const filtered = incoming
      .filter((t) => !closedTabsUntilRef.current.has(t.targetId))
      .map((t) => {
        const live = liveTabMetaRef.current[t.targetId];
        if (!live || now - live.at > 15000) return t;
        return { ...t, url: live.url || t.url, title: live.title || t.title };
      });
    const currentOrder = tabOrderRef.current;
    const byId = new Map<string, AgentBrowserTab>();
    filtered.forEach((t) => byId.set(t.targetId, t));

    const ordered: AgentBrowserTab[] = [];
    for (const tid of currentOrder) {
      const found = byId.get(tid);
      if (found) {
        ordered.push(found);
        byId.delete(tid);
      }
    }
    for (const remaining of byId.values()) {
      ordered.push(remaining);
    }
    persistTabOrder(ordered.map((t) => t.targetId));
    return ordered;
  };

  const reorderTabsInPlace = (sourceId: string, targetId: string) => {
    if (!sourceId || !targetId || sourceId === targetId) return;
    setBrowserTabs((prev) => {
      const fromIdx = prev.findIndex((t) => t.targetId === sourceId);
      const toIdx = prev.findIndex((t) => t.targetId === targetId);
      if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return prev;
      const next = [...prev];
      const [moved] = next.splice(fromIdx, 1);
      next.splice(toIdx, 0, moved);
      persistTabOrder(next.map((t) => t.targetId));
      return next;
    });
  };

  const saveOmniboxEntry = (titleText: string, urlText: string, isSearch = false) => {
    if (!urlText || urlText.startsWith("data:") || urlText.startsWith("about:")) return;
    setLocalHistoryEntries((prev) => {
      const filtered = prev.filter((item) => item.url !== urlText && item.title !== titleText);
      const next = [{ title: titleText || urlText, url: urlText, isSearch }, ...filtered].slice(0, 40);
      try {
        localStorage.setItem(`skyer_browser_omnibox_hist_${agentId}`, JSON.stringify(next));
      } catch {}
      return next;
    });
  };

  const handleToggleStreamEngine = (_nextMode?: "canvas" | "webrtc") => {
    triggerHaptic(8);
    setStreamEngineMode("canvas");
    try {
      sessionStorage.setItem(`skyer_browser_stream_engine_${agentId}`, "canvas");
    } catch {}
  };

  // Pre-warm or connect signed Selkies WebRTC H.264/VP9 stream URL with automatic graceful fallback to CDP GPU Canvas
  useEffect(() => {
    if (!agentId) return;
    if (streamEngineMode !== "webrtc") {
      setWebrtcStatus("idle");
      setWebrtcErrorMsg("");
      void prefetchAgentDesktopUrl(agentId, "control");
      return;
    }
    let cancelled = false;
    setWebrtcStatus("connecting");
    setWebrtcErrorMsg("");
    void focusAgentBrowser(agentId);
    issueAgentDesktopUrl(agentId, "control")
      .then((signedUrl) => {
        if (cancelled) return;
        const hashSuffix = signedUrl.includes("#") ? "" : "#collab";
        setWebrtcSignedUrl(`${signedUrl}${hashSuffix}`);
        setWebrtcStatus("ready");
      })
      .catch((err) => {
        if (cancelled) return;
        setWebrtcErrorMsg(err instanceof Error ? err.message : "WebRTC stream unavailable");
        setWebrtcStatus("fallback");
        setStreamEngineMode("canvas");
        try {
          sessionStorage.setItem(`skyer_browser_stream_engine_${agentId}`, "canvas");
        } catch {}
      });
    return () => {
      cancelled = true;
    };
  }, [agentId, streamEngineMode, reloadKey, attempt]);

  // Sync live tabs & active URL from the agent's Chromium profile across both Desktop and Mobile
  const refreshBrowserTabs = async () => {
    const reqAgentId = agentId;
    if (!agentId || draggingTabIdRef.current) return;
    try {
      const info = await fetchAgentBrowser(reqAgentId);
      if (draggingTabIdRef.current || activeAgentIdRef.current !== reqAgentId) return;
      if (info?.vpn) {
        setVpnStatus(info.vpn);
      }
      if (info && Array.isArray(info.tabs)) {
        const realTabs = info.tabs.filter((t) => !t.anchor);
        const nowMs = Date.now();
        if (realTabs.length > 0) {
          lastNonAnchorTabsRef.current = { tabs: realTabs, at: nowMs };
        }
        const canHoldPreviousNonAnchorTabs =
          realTabs.length === 0 &&
          lastNonAnchorTabsRef.current.tabs.length > 0 &&
          nowMs - lastNonAnchorTabsRef.current.at < 20000;
        if (
          realTabs.length === 0 &&
          !canHoldPreviousNonAnchorTabs &&
          nowMs >= tabMutationLockUntilRef.current &&
          nowMs - (autoNewTabAttemptedAtRef.current[reqAgentId] || 0) > 8000
        ) {
          autoNewTabAttemptedAtRef.current[reqAgentId] = nowMs;
          void handleCreateNewTab();
          return;
        }
        const rawList =
          realTabs.length > 0
            ? realTabs
            : canHoldPreviousNonAnchorTabs
              ? lastNonAnchorTabsRef.current.tabs
              : info.tabs;
        const list = reconcileTabsWithOrder(rawList);
        if (nowMs < tabMutationLockUntilRef.current) {
          // Preserve any optimistic tabs during the mutation lock window
          setBrowserTabs((prev) => {
            const optimistic = prev.filter((t) => t.targetId.startsWith("optimistic-"));
            const merged = [...list];
            for (const opt of optimistic) {
              if (!merged.some((m) => m.targetId === opt.targetId)) merged.push(opt);
            }
            return merged;
          });
        } else {
          setBrowserTabs(list);
        }
        // Record discovered tabs into local omnibox history & pre-warm tabFrameCacheRef for 0ms first-time tab switch!
        list.forEach((t) => {
          if (t.url && !t.anchor && !t.url.startsWith("data:") && !t.url.startsWith("about:")) {
            saveOmniboxEntry(t.title || t.url, t.url, false);
          }
          // Do not pre-fetch unscaled /browser/image.jpg snapshots into tabFrameCacheRef: tabFrameCacheRef is populated exclusively from scaled WebSocket stream frames so switching tabs never flashes an unscaled image
        });
        const curTabId = selectedTabIdRef.current;
        const activeTab =
          (curTabId && list.find((t) => t.targetId === curTabId)) ||
          list[list.length - 1] ||
          list[0];
        if (activeTab && Date.now() >= tabMutationLockUntilRef.current) {
          if (!curTabId || (!curTabId.startsWith("optimistic-") && !list.some((t) => t.targetId === curTabId))) {
            selectedTabIdRef.current = activeTab.targetId;
            setSelectedTabId(activeTab.targetId);
          }
          if (!isEditingAddressRef.current && !selectedTabIdRef.current.startsWith("optimistic-")) {
            const cleanUrl = activeTab.anchor ? "" : (activeTab.url || "");
            setAddressInput(cleanUrl);
          }
        }
      }
    } catch {}
  };

  // Adaptive tab sync: 1s while any tab is loading (titles/URLs/new agent tabs land fast), 3s when idle, paused while hidden
  useEffect(() => {
    let alive = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const loop = async () => {
      if (!alive) return;
      if (typeof document === "undefined" || !document.hidden) {
        await refreshBrowserTabs();
      }
      if (!alive) return;
      const anyLoading = Object.values(tabLoadingByIdRef.current).some(Boolean);
      timer = setTimeout(loop, anyLoading ? 1000 : 3000);
    };
    void loop();
    const onVisible = () => {
      if (!document.hidden && alive) {
        if (timer) clearTimeout(timer);
        void loop();
      }
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      alive = false;
      if (timer) clearTimeout(timer);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, [agentId, reloadKey]);

  // Fetch live Google autocomplete suggestions and tab navigation history when typing in Omnibox
  useEffect(() => {
    if (!isEditingAddress) {
      setSearchSuggestions([]);
      return;
    }
    const q = addressInput.trim();
    if (!q || q.startsWith("http://") || q.startsWith("https://")) {
      setSearchSuggestions([]);
      return;
    }
    let alive = true;
    const timer = setTimeout(async () => {
      const res = await fetchAgentBrowserSuggestions(agentId, q);
      if (alive) {
        setSearchSuggestions(res);
      }
    }, 110);
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [agentId, addressInput, isEditingAddress]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const vv = window.visualViewport;
    let maxWindowInnerH = Math.max(window.innerHeight, vv?.height || 0);
    const updateDeviceAndKeyboard = () => {
      const uaDataMob = typeof navigator !== "undefined" && Boolean((navigator as any).userAgentData?.mobile);
      const uaMob = uaDataMob || (typeof navigator !== "undefined" && /Android|iPhone|iPod|Windows Phone|Mobile|Silk|CriOS|FxiOS/i.test(navigator.userAgent || ""));
      const hasTouch = typeof navigator !== "undefined" && Number(navigator.maxTouchPoints || 0) > 0;
      const coarse =
        typeof window.matchMedia === "function" &&
        window.matchMedia("(pointer: coarse)").matches &&
        (window.innerWidth < 960 || window.innerHeight < 560 || Math.min(window.screen.width, window.screen.height) < 600);
      const phoneNow = window.innerWidth < 768 || coarse || uaMob || (hasTouch && Math.min(window.innerWidth, window.innerHeight) < 600);
      setIsPhoneClient(phoneNow);
      const curInnerH = window.innerHeight;
      if (curInnerH > maxWindowInnerH || Math.abs(window.innerWidth - (vv?.width || window.innerWidth)) > 80) {
        maxWindowInnerH = Math.max(curInnerH, vv?.height || 0);
      }
      const vvHeight = vv ? vv.height : curInnerH;
      const kbDiff = Math.max(curInnerH - vvHeight, maxWindowInnerH - vvHeight);
      const kbOpen = phoneNow && kbDiff > 110;
      isVirtualKeyboardOpenRef.current = kbOpen;
      setIsVirtualKeyboardOpen(kbOpen);
      setVirtualKeyboardHeight(kbOpen ? Math.round(kbDiff) : 0);
    };
    updateDeviceAndKeyboard();
    window.addEventListener("resize", updateDeviceAndKeyboard);
    vv?.addEventListener("resize", updateDeviceAndKeyboard);
    vv?.addEventListener("scroll", updateDeviceAndKeyboard);
    return () => {
      window.removeEventListener("resize", updateDeviceAndKeyboard);
      vv?.removeEventListener("resize", updateDeviceAndKeyboard);
      vv?.removeEventListener("scroll", updateDeviceAndKeyboard);
    };
  }, []);

  useLayoutEffect(() => {
    const checkViewport = () => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
          const nw = Math.round(rect.width);
          const nh = Math.round(rect.height);
          setBoxSize((prev) => {
            if (isVirtualKeyboardOpenRef.current && prev.w > 0 && prev.h > 0 && Math.abs(prev.w - nw) <= 16 && nh < prev.h) {
              return prev;
            }
            return Math.abs(prev.w - nw) > 1 || Math.abs(prev.h - nh) > 1 ? { w: nw, h: nh } : prev;
          });
        }
      }
    };
    checkViewport();
    window.addEventListener("resize", checkViewport);

    let ro: ResizeObserver | null = null;
    let roRaf = 0;
    let pendingRoRect: { w: number; h: number } | null = null;
    if (typeof ResizeObserver !== "undefined" && containerRef.current) {
      ro = new ResizeObserver((entries) => {
        const cr = entries[0]?.contentRect;
        if (cr && cr.width > 0 && cr.height > 0) {
          pendingRoRect = { w: Math.round(cr.width), h: Math.round(cr.height) };
          if (!roRaf) {
            roRaf = requestAnimationFrame(() => {
              roRaf = 0;
              if (!pendingRoRect) return;
              const { w: nw, h: nh } = pendingRoRect;
              pendingRoRect = null;
              setBoxSize((prev) => {
                if (isVirtualKeyboardOpenRef.current && prev.w > 0 && prev.h > 0 && Math.abs(prev.w - nw) <= 16 && nh < prev.h) {
                  return prev;
                }
                return Math.abs(prev.w - nw) > 1 || Math.abs(prev.h - nh) > 1 ? { w: nw, h: nh } : prev;
              });
            });
          }
        }
      });
      ro.observe(containerRef.current);
    }
    return () => {
      window.removeEventListener("resize", checkViewport);
      if (roRaf) cancelAnimationFrame(roRaf);
      ro?.disconnect();
    };
  }, [agentId, reloadKey]);

  useEffect(() => {
    const onVis = () => {
      if (document.hidden) { hiddenAt.current = Date.now(); return; }
      if (hiddenAt.current && Date.now() - hiddenAt.current > 30000) setAttempt((a) => a + 1);
      hiddenAt.current = 0;
    };
    const onOnline = () => setAttempt((a) => a + 1);
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("online", onOnline);
    return () => { document.removeEventListener("visibilitychange", onVis); window.removeEventListener("online", onOnline); };
  }, []);

  const activeTabObj =
    browserTabs.find((t) => t.targetId === selectedTabId) ||
    browserTabs[browserTabs.length - 1] ||
    browserTabs[0];
  const isActivePageLoading = isNavigating || Boolean(activeTabObj && tabLoadingById[activeTabObj.targetId]);

  const getTabFaviconUrl = (tabUrl?: string, isAnchor?: boolean) => {
    if (!tabUrl || isAnchor || tabUrl.startsWith("data:") || tabUrl.startsWith("about:") || tabUrl.startsWith("chrome:")) {
      return null;
    }
    try {
      const parsed = new URL(tabUrl);
      if (parsed.hostname && parsed.hostname.includes(".")) {
        return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(parsed.hostname)}&sz=32`;
      }
    } catch {}
    return null;
  };

  const handleNavigateUrl = async (rawTargetUrl: string) => {
    const rawTarget = rawTargetUrl.trim();
    if (!rawTarget) return;
    setIsNavigating(true);
    setIsEditingAddress(false);
    setIsHistoryOpen(false);
    addressInputRef.current?.blur();

    const isDirectUrl = rawTarget.includes("://") || (rawTarget.includes(".") && !rawTarget.includes(" "));
    const normalizedUrl = !rawTarget.includes("://") && !rawTarget.startsWith("about:")
      ? (isDirectUrl ? `https://${rawTarget}` : `https://www.google.com/search?q=${encodeURIComponent(rawTarget)}`)
      : rawTarget;

    saveOmniboxEntry(rawTarget, normalizedUrl, !isDirectUrl);
    if (selectedTabIdRef.current) markTabLoading(selectedTabIdRef.current, true);

    setBrowserTabs((prev) =>
      prev.map((t) =>
        t.targetId === selectedTabId ? { ...t, url: normalizedUrl, title: rawTarget } : t
      )
    );
    setAddressInput(normalizedUrl);

    const navVp = computeActiveBrowserViewport();
    const res = await dispatchAgentBrowserInput(agentId, {
      action: "navigate",
      text: rawTarget,
      pageId: selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined,
      width: navVp.w,
      height: navVp.h,
      isMobile: navVp.isMobile,
      deviceType: navVp.isMobile ? "phone" : "desktop",
    });
    if (res.tabs && Array.isArray(res.tabs)) {
      const real = res.tabs.filter((t) => !t.anchor);
      setBrowserTabs(reconcileTabsWithOrder(real.length > 0 ? real : res.tabs));
    }
    setAttempt((a) => a + 1);
    setIsNavigating(false);
    setTimeout(refreshBrowserTabs, 220);
  };

  const handleNavigateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const suggestionsList = buildOmniboxSuggestions();
    if (omniboxActiveIdx >= 0 && omniboxActiveIdx < suggestionsList.length) {
      await handleNavigateUrl(suggestionsList[omniboxActiveIdx].targetValue);
    } else {
      await handleNavigateUrl(addressInput);
    }
  };

  const handleBrowserAction = async (act: "back" | "forward" | "reload") => {
    triggerHaptic(8);
    setIsNavigating(true);
    if (selectedTabIdRef.current) markTabLoading(selectedTabIdRef.current, true);
    const actVp = computeActiveBrowserViewport();
    await dispatchAgentBrowserInput(agentId, {
      action: act,
      pageId: selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined,
      width: actVp.w,
      height: actVp.h,
      isMobile: actVp.isMobile,
      deviceType: actVp.isMobile ? "phone" : "desktop",
      reloadOnModeChange: act === "reload",
    });
    setAttempt((a) => a + 1);
    setIsNavigating(false);
    refreshBrowserTabs();
  };

  const handlePageLoadingState = (state: { loading: boolean; url: string; title: string }) => {
    const tabId = selectedTabIdRef.current;
    if (!tabId || tabId.startsWith("optimistic-")) return;
    markTabLoading(tabId, state.loading);
    const cleanUrl = state.url && !state.url.startsWith("data:") ? state.url : "";
    if (cleanUrl || state.title) {
      const prevLive = liveTabMetaRef.current[tabId];
      const urlChanged = Boolean(cleanUrl && prevLive && prevLive.url !== cleanUrl);
      liveTabMetaRef.current[tabId] = {
        url: cleanUrl || prevLive?.url || "",
        title: state.title && !(urlChanged && state.loading && state.title === prevLive?.title) ? state.title : (urlChanged ? "" : prevLive?.title || ""),
        at: Date.now(),
      };
      setBrowserTabs((prev) => {
        let changed = false;
        const next = prev.map((t) => {
          if (t.targetId !== tabId) return t;
          const live = liveTabMetaRef.current[tabId];
          const isTransientBlank = live.url === "about:blank" && Boolean(t.url && t.url !== "about:blank");
          const url = (!isTransientBlank && live.url) || t.url;
          const title = live.title || (!isTransientBlank && url !== t.url ? url : t.title);
          if (url === t.url && title === t.title) return t;
          changed = true;
          return { ...t, url, title };
        });
        return changed ? next : prev;
      });
    }
    if (cleanUrl && !cleanUrl.startsWith("about:") && !isEditingAddressRef.current) {
      setAddressInput(cleanUrl);
    }
    if (!state.loading) {
      setIsNavigating(false);
      if (cleanUrl && !cleanUrl.startsWith("about:")) saveOmniboxEntry(state.title || cleanUrl, cleanUrl, false);
    }
  };

  // A page opened a popup/new window (OAuth/QR login, target=_blank): poll until the new target shows up, then follow it like Chrome does.
  const handlePopupOpened = async (popup: { openerId: string; url: string }) => {
    const reqAgentId = agentId;
    const knownIds = new Set(browserTabsRef.current.map((t) => t.targetId));
    const popupUrl = popup.url || "";
    for (let attemptIdx = 0; attemptIdx < 12; attemptIdx++) {
      await new Promise((r) => setTimeout(r, attemptIdx === 0 ? 250 : 500));
      if (activeAgentIdRef.current !== reqAgentId) return;
      let info: Awaited<ReturnType<typeof fetchAgentBrowser>> | null = null;
      try {
        info = await fetchAgentBrowser(reqAgentId);
      } catch {
        continue;
      }
      const realTabs = (info?.tabs || []).filter((t) => !t.anchor);
      const fresh = realTabs.filter((t) => !knownIds.has(t.targetId));
      const popupTab =
        fresh.find((t) => popupUrl && popupUrl !== "about:blank" && (t.url === popupUrl || t.url.startsWith(popupUrl.split("#")[0]))) ||
        fresh[fresh.length - 1];
      if (!popupTab) continue;
      const list = reconcileTabsWithOrder(realTabs);
      setBrowserTabs(list);
      handleActivateTab(popupTab);
      return;
    }
  };

  const handleStopLoading = async () => {
    triggerHaptic(8);
    const tabId = selectedTabIdRef.current;
    setIsNavigating(false);
    if (tabId) markTabLoading(tabId, false);
    await dispatchAgentBrowserInput(agentId, {
      action: "stop",
      pageId: tabId && !tabId.startsWith("optimistic-") ? tabId : undefined,
    });
  };

  const handleActivateTab = (tab: AgentBrowserTab) => {
    if (!tab || tab.targetId === selectedTabIdRef.current) return;
    tabMutationLockUntilRef.current = Date.now() + 1200;
    selectedTabIdRef.current = tab.targetId;
    setSelectedTabId(tab.targetId);
    if (!isEditingAddressRef.current) {
      setAddressInput(tab.anchor ? "" : (tab.url || ""));
    }
    if (!tab.targetId.startsWith("optimistic-")) {
      const tabVp = computeActiveBrowserViewport();
      void enqueueTabMutation(async () => {
        await dispatchAgentBrowserInput(agentId, {
          action: "activate_tab",
          pageId: tab.targetId,
          width: tabVp.w,
          height: tabVp.h,
          isMobile: tabVp.isMobile,
          deviceType: tabVp.isMobile ? "phone" : "desktop",
        });
      });
    }
  };

// Instant 0ms Crisp Google New Tab Seed Frame (Eliminates stale-tab flash or blank screen while Chromium creates the tab)
const INSTANT_GOOGLE_NEW_TAB_DATA_URL =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 800" width="1280" height="800">
      <rect width="1280" height="800" fill="#ffffff"/>
      <g transform="translate(640, 290)" text-anchor="middle" font-family="Arial, sans-serif" font-weight="700" font-size="88">
        <text y="0">
          <tspan fill="#4285F4">G</tspan><tspan fill="#EA4335">o</tspan><tspan fill="#FBBC05">o</tspan><tspan fill="#4285F4">g</tspan><tspan fill="#34A853">l</tspan><tspan fill="#EA4335">e</tspan>
        </text>
      </g>
      <rect x="350" y="340" width="580" height="48" rx="24" fill="#ffffff" stroke="#dfe1e5" stroke-width="1.5"/>
      <circle cx="380" cy="364" r="7" fill="none" stroke="#9aa0a6" stroke-width="2"/>
      <line x1="385" y1="369" x2="391" y2="375" stroke="#9aa0a6" stroke-width="2" stroke-linecap="round"/>
      <text x="406" y="369" font-family="Arial, sans-serif" font-size="15" fill="#9aa0a6">Tìm kiếm trên Google hoặc nhập một URL</text>
      <rect x="495" y="416" width="136" height="36" rx="6" fill="#f8f9fa"/>
      <text x="563" y="439" text-anchor="middle" font-family="Arial, sans-serif" font-size="13.5" fill="#3c4043">Tìm trên Google</text>
      <rect x="645" y="416" width="146" height="36" rx="6" fill="#f8f9fa"/>
      <text x="718" y="439" text-anchor="middle" font-family="Arial, sans-serif" font-size="13.5" fill="#3c4043">Xem trang đầu tiên</text>
    </svg>`
  );

  // Instant 0ms Optimistic New Tab creation with crisp Google homepage seed & seamless target ID swap
  const handleCreateNewTab = async () => {
    const reqAgentId = agentId;
    triggerHaptic(8);
    setIsNavigating(true);
    tabMutationLockUntilRef.current = Date.now() + 3200;

    const existingGoogleTab = browserTabs.find((t) => (t.url || "").includes("google.com"));
    const cachedGoogleFrame = existingGoogleTab ? tabFrameCacheRef.current[`${reqAgentId}:${existingGoogleTab.targetId}`] : "";
    const googleSeedFrame =
      cachedGoogleFrame && cachedGoogleFrame !== "__loading__"
        ? cachedGoogleFrame
        : INSTANT_GOOGLE_NEW_TAB_DATA_URL;

    const optId = `optimistic-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    tabFrameCacheRef.current[`${reqAgentId}:${optId}`] = googleSeedFrame;
    const prevSelectedId = selectedTabIdRef.current;

    const optTab: AgentBrowserTab = {
      targetId: optId,
      title: "Google",
      url: "https://www.google.com",
      anchor: false,
    };

    setBrowserTabs((prev) => {
      const next = [...prev, optTab];
      persistTabOrder(next.map((t) => t.targetId));
      return next;
    });
    selectedTabIdRef.current = optId;
    setSelectedTabId(optId);
    setAddressInput("https://www.google.com");

    const vp = computeActiveBrowserViewport();
    await enqueueTabMutation(async () => {
      try {
        const res = await dispatchAgentBrowserInput(reqAgentId, {
          action: "new_tab",
          text: "https://www.google.com",
          pageId: prevSelectedId && !prevSelectedId.startsWith("optimistic-") ? prevSelectedId : undefined,
          width: vp.w,
          height: vp.h,
          isMobile: vp.isMobile,
          deviceType: vp.isMobile ? "phone" : "desktop",
        });
        if (activeAgentIdRef.current !== reqAgentId) return;

        const realNewId = res.createdTargetId || (res.targetId && res.targetId !== prevSelectedId ? res.targetId : undefined);
        if (realNewId && (!tabFrameCacheRef.current[`${reqAgentId}:${realNewId}`] || tabFrameCacheRef.current[`${reqAgentId}:${realNewId}`] === "__loading__")) {
          tabFrameCacheRef.current[`${reqAgentId}:${realNewId}`] = googleSeedFrame;
        }

        if (realNewId) {
          const replacedOrder = tabOrderRef.current.map((id) => (id === optId ? realNewId : id));
          if (!replacedOrder.includes(realNewId)) replacedOrder.push(realNewId);
          persistTabOrder(Array.from(new Set(replacedOrder)));
        }

        if (res.tabs && Array.isArray(res.tabs) && res.tabs.length > 0) {
          const real = res.tabs.filter((t) => !t.anchor);
          const list = reconcileTabsWithOrder(real.length > 0 ? real : res.tabs);
          setBrowserTabs(list);
          const chosen = (realNewId && list.find((t) => t.targetId === realNewId)) || list[list.length - 1];
          if (chosen && (selectedTabIdRef.current === optId || selectedTabIdRef.current === chosen.targetId)) {
            selectedTabIdRef.current = chosen.targetId;
            setSelectedTabId(chosen.targetId);
            setAddressInput(chosen.url || "https://www.google.com");
          }
        } else if (realNewId) {
          const newTabEntry: AgentBrowserTab = {
            targetId: realNewId,
            title: "Google",
            url: "https://www.google.com",
            anchor: false,
          };
          setBrowserTabs((prev) => {
            const next = prev.map((t) => (t.targetId === optId ? newTabEntry : t));
            if (!next.some((t) => t.targetId === realNewId)) next.push(newTabEntry);
            return next;
          });
          if (selectedTabIdRef.current === optId) {
            selectedTabIdRef.current = realNewId;
            setSelectedTabId(realNewId);
            setAddressInput("https://www.google.com");
          }
        } else {
          tabMutationLockUntilRef.current = 0;
          await refreshBrowserTabs();
        }
      } finally {
        delete tabFrameCacheRef.current[`${reqAgentId}:${optId}`];
        if (activeAgentIdRef.current === reqAgentId) {
          setIsNavigating(false);
        }
      }
    });
  };

  const handleCloseTab = async (tabId: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    triggerHaptic(8);
    if (browserTabs.length <= 1) return;

    closedTabsUntilRef.current.set(tabId, Date.now() + 8000);
    tabMutationLockUntilRef.current = Date.now() + 2200;
    delete tabFrameCacheRef.current[`${agentId}:${tabId}`];

    const closeIdx = browserTabs.findIndex((t) => t.targetId === tabId);
    const remaining = browserTabs.filter((t) => t.targetId !== tabId);
    const remainingNonAnchor = remaining.filter((t) => !t.anchor);
    lastNonAnchorTabsRef.current = { tabs: remainingNonAnchor, at: Date.now() };
    persistTabOrder(remaining.map((t) => t.targetId));
    setBrowserTabs(remaining);

    let nextActiveTargetId = "";
    if (selectedTabIdRef.current === tabId && remaining.length > 0) {
      const nextIdx = Math.min(Math.max(0, closeIdx), remaining.length - 1);
      const nextActive = remaining[nextIdx] || remaining[remaining.length - 1];
      nextActiveTargetId = nextActive.targetId;
      selectedTabIdRef.current = nextActive.targetId;
      setSelectedTabId(nextActive.targetId);
      setAddressInput(nextActive.anchor ? "" : (nextActive.url || ""));
    }

    if (tabId.startsWith("optimistic-")) return;

    await enqueueTabMutation(async () => {
      if (nextActiveTargetId && !nextActiveTargetId.startsWith("optimistic-")) {
        void dispatchAgentBrowserInput(agentId, { action: "activate_tab", pageId: nextActiveTargetId });
      }
      const res = await dispatchAgentBrowserInput(agentId, {
        action: "close_tab",
        pageId: tabId,
      });
      if (res.tabs && Array.isArray(res.tabs) && res.tabs.length > 0) {
        const real = res.tabs.filter((t) => !t.anchor);
        setBrowserTabs(reconcileTabsWithOrder(real.length > 0 ? real : res.tabs));
      }
    });
  };

  const handleToggleHistory = async () => {
    const nextOpen = !isHistoryOpen;
    setIsHistoryOpen(nextOpen);
    if (nextOpen) {
      setIsLoadingHistory(true);
      const items = await fetchAgentBrowserHistory(
        agentId,
        selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined
      );
      setHistoryItems(items);
      items.forEach((it) => {
        if (it.url) saveOmniboxEntry(it.title || it.url, it.url, false);
      });
      setIsLoadingHistory(false);
    }
  };

  const handleFindInPage = async (queryText: string, direction: "next" | "prev" = "next") => {
    await dispatchAgentBrowserInput(agentId, {
      action: "find",
      text: queryText,
      key: direction,
      pageId: selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined,
    });
  };

  const handleToggleFindBar = () => {
    setIsFindOpen((prev) => {
      const next = !prev;
      if (next) {
        setTimeout(() => findInputRef.current?.focus(), 40);
      } else {
        void handleFindInPage("", "next");
      }
      return next;
    });
  };

  const handleZoomStep = (deltaPct: number | "reset") => {
    setBrowserZoomPercent((prev) => {
      if (deltaPct === "reset") return 100;
      return Math.max(50, Math.min(250, prev + deltaPct));
    });
  };

  const handleToggleVpn = async (forceRotate = false) => {
    if (isTogglingVpn || !agentId) return;
    triggerHaptic(8);
    setIsTogglingVpn(true);
    try {
      const nextEnabled = forceRotate ? true : !(vpnStatus?.enabled);
      const updated = await setAgentBrowserVpn(agentId, {
        enabled: nextEnabled,
        mode: forceRotate ? "rotate" : "auto",
        region: "VN",
        rotate: forceRotate,
      });
      if (updated) {
        setVpnStatus(updated);
      }
      const vpnVp = computeActiveBrowserViewport();
      await dispatchAgentBrowserInput(agentId, {
        action: "reload",
        pageId: selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined,
        width: vpnVp.w,
        height: vpnVp.h,
        isMobile: vpnVp.isMobile,
        deviceType: vpnVp.isMobile ? "phone" : "desktop",
        reloadOnModeChange: true,
      });
      setTimeout(refreshBrowserTabs, 300);
    } finally {
      setIsTogglingVpn(false);
    }
  };

  // Build unified Chrome Omnibox suggestions matching user reference screenshot
  const buildOmniboxSuggestions = (): Array<{
    kind: "primary" | "recent_search" | "search_suggest" | "history_url";
    label: string;
    subUrl?: string;
    targetValue: string;
  }> => {
    const q = addressInput.trim();
    const qLower = q.toLowerCase();
    const results: Array<{
      kind: "primary" | "recent_search" | "search_suggest" | "history_url";
      label: string;
      subUrl?: string;
      targetValue: string;
    }> = [];

    if (q) {
      const isUrlLike = q.includes("://") || (q.includes(".") && !q.includes(" "));
      results.push({
        kind: "primary",
        label: q,
        subUrl: isUrlLike ? q : "Google Search",
        targetValue: q,
      });
    }

    // 1. Matching recent searches (Clock icon)
    const matchedSearches = localHistoryEntries
      .filter((it) => it.isSearch && (!qLower || it.title.toLowerCase().includes(qLower)))
      .slice(0, 2);
    for (const s of matchedSearches) {
      if (!results.some((r) => r.label.toLowerCase() === s.title.toLowerCase())) {
        results.push({
          kind: "recent_search",
          label: s.title,
          targetValue: s.title,
        });
      }
    }

    // 2. Live Google Search autocomplete suggestions (Search icon)
    for (const sg of searchSuggestions.slice(0, 3)) {
      if (!results.some((r) => r.label.toLowerCase() === sg.toLowerCase())) {
        results.push({
          kind: "search_suggest",
          label: sg,
          targetValue: sg,
        });
      }
    }

    // 3. Matching visited pages from open tabs + history (Globe icon + Title - blue URL)
    const allPages: Array<{ title: string; url: string }> = [];
    const seenUrls = new Set<string>();
    for (const t of browserTabs) {
      if (t.url && !t.anchor && !t.url.startsWith("data:") && !t.url.startsWith("about:") && !seenUrls.has(t.url)) {
        seenUrls.add(t.url);
        allPages.push({ title: t.title || t.url, url: t.url });
      }
    }
    for (const h of historyItems) {
      if (h.url && !seenUrls.has(h.url)) {
        seenUrls.add(h.url);
        allPages.push({ title: h.title || h.url, url: h.url });
      }
    }
    for (const lh of localHistoryEntries) {
      if (!lh.isSearch && lh.url && !seenUrls.has(lh.url)) {
        seenUrls.add(lh.url);
        allPages.push({ title: lh.title || lh.url, url: lh.url });
      }
    }

    const matchedPages = allPages
      .filter((p) => !qLower || p.title.toLowerCase().includes(qLower) || p.url.toLowerCase().includes(qLower))
      .slice(0, 4);

    for (const p of matchedPages) {
      const cleanSubUrl = p.url.replace(/^https?:\/\/(www\.)?/, "");
      results.push({
        kind: "history_url",
        label: p.title,
        subUrl: cleanSubUrl,
        targetValue: p.url,
      });
    }

    return results.slice(0, 8);
  };

  const renderHighlightedMatch = (text: string, query: string) => {
    const q = query.trim();
    if (!q) return <span className="font-normal">{text}</span>;
    const idx = text.toLowerCase().indexOf(q.toLowerCase());
    if (idx === -1) return <span className="font-normal">{text}</span>;
    return (
      <>
        <span className="font-normal">{text.slice(0, idx)}</span>
        <span className="font-bold text-slate-950 dark:text-white">{text.slice(idx, idx + q.length)}</span>
        <span className="font-normal">{text.slice(idx + q.length)}</span>
      </>
    );
  };

  // Authentic Modern Chromium Tab Strip & Omnibox matching the exact reference screenshots
  const renderBrowserChromeHeader = () => {
    const rawDisplayUrl = isEditingAddress
      ? addressInput
      : addressInput || (activeTabObj?.anchor ? "" : activeTabObj?.url) || "";
    const omniboxItems = isEditingAddress ? buildOmniboxSuggestions() : [];

    return (
      <div
        data-testid="agent-browser-chrome-header"
        className="w-full bg-[#dee1e6] dark:bg-[#202124] flex flex-col shrink-0 select-none z-30 transition-colors"
      >
        {/* 1. Authentic Chrome Tab Strip + Unified Borderless Window CTAs */}
        <div className="flex items-end justify-between w-full pl-2 pr-0 pt-1">
          <div className="flex items-end flex-1 min-w-0 overflow-x-auto no-scrollbar">
          {browserTabs.length > 0 ? (
            browserTabs.map((tab, idx) => {
              const isActive = (activeTabObj?.targetId || "") === tab.targetId;
              const nextTab = browserTabs[idx + 1];
              const isNextActive = nextTab && (activeTabObj?.targetId || "") === nextTab.targetId;
              const favUrl = getTabFaviconUrl(tab.url, tab.anchor);
              const tabTitle = tab.anchor
                ? "New Tab"
                : (tab.title || tab.url || `Tab ${idx + 1}`);

              const isDraggingThis = draggingTabId === tab.targetId;
              const isDragOverThis = dragOverTabId === tab.targetId && draggingTabId !== tab.targetId;

              return (
                <div
                  key={tab.targetId || idx}
                  data-tab-id={tab.targetId}
                  draggable={browserTabs.length > 1}
                  onDragStart={(e) => {
                    if (browserTabs.length <= 1) return;
                    draggingTabIdRef.current = tab.targetId;
                    setDraggingTabId(tab.targetId);
                    e.dataTransfer.effectAllowed = "move";
                    try {
                      e.dataTransfer.setData("text/plain", tab.targetId);
                    } catch {}
                  }}
                  onDragOver={(e) => {
                    e.preventDefault();
                    e.dataTransfer.dropEffect = "move";
                    const srcId = draggingTabIdRef.current;
                    if (srcId && srcId !== tab.targetId) {
                      setDragOverTabId(tab.targetId);
                      reorderTabsInPlace(srcId, tab.targetId);
                    }
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    const srcId = draggingTabIdRef.current || e.dataTransfer.getData("text/plain");
                    if (srcId && srcId !== tab.targetId) {
                      reorderTabsInPlace(srcId, tab.targetId);
                    }
                    draggingTabIdRef.current = null;
                    setDraggingTabId(null);
                    setDragOverTabId(null);
                  }}
                  onDragEnd={() => {
                    draggingTabIdRef.current = null;
                    setDraggingTabId(null);
                    setDragOverTabId(null);
                  }}
                  className={`flex items-center flex-1 basis-0 min-w-[72px] max-w-[240px] transition-transform duration-150 ${
                    isDraggingThis ? "opacity-60 scale-[0.98] z-20" : ""
                  } ${isDragOverThis ? "ring-1 ring-[#1a73e8]/60 rounded-t-[10px]" : ""}`}
                >
                  <div
                    role="tab"
                    data-testid={`agent-browser-tab-${idx}`}
                    aria-selected={isActive}
                    onClick={() => handleActivateTab(tab)}
                    onAuxClick={(e) => {
                      if (e.button === 1 && browserTabs.length > 1) {
                        void handleCloseTab(tab.targetId, e);
                      }
                    }}
                    className={`group relative flex items-center gap-2 pl-3 pr-2 h-[34px] w-full rounded-t-[10px] text-[12px] font-sans min-w-0 transition-colors duration-75 cursor-pointer ${
                      isActive
                        ? "bg-[#f1f3f4] dark:bg-[#323639] text-[#202124] dark:text-[#e8eaed] font-medium z-10"
                        : "bg-transparent text-[#5f6368] dark:text-[#9aa0a6] hover:bg-black/[0.06] dark:hover:bg-white/[0.06] hover:text-[#202124] dark:hover:text-[#e8eaed]"
                    }`}
                    title={`${tabTitle}${tab.url && !tab.anchor ? ` — ${tab.url}` : ""} (Kéo thả để sắp xếp tab)`}
                  >
                    {/* Bottom-left & bottom-right outward curve connectors for active Chrome tab */}
                    {isActive && (
                      <>
                        <span className="pointer-events-none absolute -left-2 bottom-0 w-2 h-2 bg-transparent rounded-br-[8px] shadow-[4px_0_0_0_#f1f3f4] dark:shadow-[4px_0_0_0_#323639]" />
                        <span className="pointer-events-none absolute -right-2 bottom-0 w-2 h-2 bg-transparent rounded-bl-[8px] shadow-[-4px_0_0_0_#f1f3f4] dark:shadow-[-4px_0_0_0_#323639]" />
                      </>
                    )}

                    {tabLoadingById[tab.targetId] || (isActive && isNavigating) ? (
                      <Loader2
                        size={14}
                        data-testid={`agent-browser-tab-loading-${idx}`}
                        className="animate-spin text-[#1a73e8] dark:text-[#8ab4f8] shrink-0"
                      />
                    ) : favUrl ? (
                      <img
                        src={favUrl}
                        alt=""
                        draggable={false}
                        className="w-4 h-4 rounded-xs object-contain shrink-0 pointer-events-none"
                        onError={(e) => { (e.currentTarget as HTMLElement).style.display = "none"; }}
                      />
                    ) : (
                      <Globe
                        size={14}
                        className={isActive ? "text-[#5f6368] dark:text-[#9aa0a6] shrink-0" : "text-[#5f6368]/80 dark:text-[#9aa0a6]/80 shrink-0"}
                      />
                    )}

                    <span className="truncate flex-1 leading-none">{tabTitle}</span>

                    {browserTabs.length > 1 && (
                      <button
                        type="button"
                        draggable={false}
                        onDragStart={(e) => e.stopPropagation()}
                        onClick={(e) => handleCloseTab(tab.targetId, e)}
                        className="h-4 w-4 rounded-full hover:bg-black/10 dark:hover:bg-white/15 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-white flex items-center justify-center opacity-80 group-hover:opacity-100 transition-opacity shrink-0"
                        title="Đóng tab"
                        aria-label="Close tab"
                      >
                        <X size={11} />
                      </button>
                    )}
                  </div>

                  {/* Subtle vertical divider between inactive tabs or before the + button */}
                  {(!isActive && !isNextActive) && (
                    <span className="h-4 w-[1px] bg-black/15 dark:bg-white/15 mx-0.5 shrink-0" />
                  )}
                </div>
              );
            })
          ) : (
            <div className="flex items-center gap-2 px-3 h-[34px] flex-1 basis-0 max-w-[240px] rounded-t-[10px] bg-[#f1f3f4] dark:bg-[#323639] text-[#202124] dark:text-[#e8eaed] text-[12px] font-medium">
              <Globe size={14} className="text-[#9aa0a6] shrink-0" />
              <span className="truncate">{title || "New Tab"}</span>
            </div>
          )}

          {/* Vertical separator if last tab is active */}
          {browserTabs.length > 0 && (activeTabObj?.targetId || "") === browserTabs[browserTabs.length - 1]?.targetId && (
            <span className="h-4 w-[1px] bg-black/15 dark:bg-white/15 ml-2 mr-0.5 mb-[9px] shrink-0" />
          )}

          {/* New Tab (+) Button */}
          <button
            type="button"
            data-testid="agent-browser-new-tab-btn"
            onClick={handleCreateNewTab}
            className="h-7 w-7 mb-[3px] ml-0.5 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed] flex items-center justify-center transition-colors cursor-pointer shrink-0 active:scale-95"
            title="Mở tab mới (Google · Ctrl+T)"
            aria-label="New tab"
          >
            <Plus size={15} />
          </button>
          </div>

          {/* Unified Borderless Browser Header CTAs (matching Chrome Window Controls style) */}
          {(onCaptureScreenshot || onReloadSession || onToggleMaximize || onCloseBrowser) && (
            <div
              data-testid="agent-browser-window-ctas"
              className="flex items-stretch self-stretch shrink-0 ml-1 -mt-1"
            >
              {onCaptureScreenshot && (
                <Tooltip content={screenshotTooltip || "Chụp màn hình"} placement="bottom">
                  <button
                    type="button"
                    data-testid="agent-browser-header-screenshot-btn"
                    onClick={onCaptureScreenshot}
                    className={`h-[38px] w-11 border-0 rounded-none flex items-center justify-center transition-colors cursor-pointer ${
                      isScreenshotCaptured
                        ? "bg-emerald-500/20 text-emerald-400"
                        : "bg-transparent hover:bg-black/10 dark:hover:bg-[#35363a] text-[#5f6368] dark:text-[#e8eaed] hover:text-[#202124] dark:hover:text-white"
                    }`}
                    aria-label={screenshotTooltip || "Capture screenshot"}
                  >
                    {isScreenshotCaptured ? (
                      <Check size={14} className="text-emerald-400 animate-in zoom-in-75 duration-150" />
                    ) : (
                      <Camera size={14} />
                    )}
                  </button>
                </Tooltip>
              )}

              {onReloadSession && (
                <Tooltip content={reloadSessionTooltip || "Tải lại phiên trình duyệt"} placement="bottom">
                  <button
                    type="button"
                    data-testid="agent-browser-header-reload-session-btn"
                    disabled={isReloadingSession}
                    onClick={() => {
                      void handleBrowserAction("reload");
                      onReloadSession();
                    }}
                    className="h-[38px] w-11 border-0 rounded-none bg-transparent hover:bg-black/10 dark:hover:bg-[#35363a] text-[#5f6368] dark:text-[#e8eaed] hover:text-[#202124] dark:hover:text-white flex items-center justify-center transition-colors cursor-pointer disabled:opacity-50"
                    aria-label={reloadSessionTooltip || "Reload browser session"}
                  >
                    <RefreshCw size={13} className={isReloadingSession ? "animate-spin text-[#1a73e8] dark:text-[#8ab4f8]" : ""} />
                  </button>
                </Tooltip>
              )}

              {onToggleMaximize && (
                <Tooltip content={maximizeTooltip || (isMaximized ? "Thu nhỏ" : "Phóng to toàn màn hình")} placement="bottom">
                  <button
                    type="button"
                    data-testid="agent-browser-header-maximize-btn"
                    onClick={onToggleMaximize}
                    className="h-[38px] w-11 border-0 rounded-none bg-transparent hover:bg-black/10 dark:hover:bg-[#35363a] text-[#5f6368] dark:text-[#e8eaed] hover:text-[#202124] dark:hover:text-white flex items-center justify-center transition-colors cursor-pointer"
                    aria-label={maximizeTooltip || (isMaximized ? "Restore split view" : "Maximize browser")}
                  >
                    {isMaximized ? <Copy size={13} className="-scale-x-100" /> : <Maximize2 size={13} />}
                  </button>
                </Tooltip>
              )}

              {onCloseBrowser && (
                <Tooltip content={closeTooltip || "Đóng trình duyệt"} placement="bottom">
                  <button
                    type="button"
                    data-testid="agent-browser-header-close-btn"
                    data-ux-target-min="24"
                    onClick={onCloseBrowser}
                    className="h-[38px] w-11 border-0 rounded-none bg-transparent hover:bg-[#e81123] hover:text-white text-[#5f6368] dark:text-[#e8eaed] flex items-center justify-center transition-colors cursor-pointer"
                    aria-label={closeTooltip || "Close (Esc)"}
                  >
                    <X size={15} />
                  </button>
                </Tooltip>
              )}
            </div>
          )}
        </div>

        {/* 2. Authentic Chrome Navigation, Omnibox with History/Search Suggestions Dropdown & Right History Icon */}
        <div className="h-[42px] px-2.5 flex items-center gap-1.5 bg-[#f1f3f4] dark:bg-[#323639] border-b border-black/10 dark:border-black/40 relative">
          <button
            type="button"
            onClick={() => handleBrowserAction("back")}
            className="h-7 w-7 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed] flex items-center justify-center transition-colors cursor-pointer shrink-0"
            title="Quay lại (Back)"
            aria-label="Back"
          >
            <ArrowLeft size={15} />
          </button>
          <button
            type="button"
            onClick={() => handleBrowserAction("forward")}
            className="h-7 w-7 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed] flex items-center justify-center transition-colors cursor-pointer shrink-0"
            title="Tiến tới (Forward)"
            aria-label="Forward"
          >
            <ArrowRight size={15} />
          </button>
          <button
            type="button"
            data-testid="agent-browser-reload-btn"
            data-loading={isActivePageLoading ? "true" : "false"}
            onClick={() => (isActivePageLoading ? void handleStopLoading() : void handleBrowserAction("reload"))}
            className="h-7 w-7 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed] flex items-center justify-center transition-colors cursor-pointer shrink-0"
            title={isActivePageLoading ? "Dừng tải trang (Stop)" : "Tải lại trang (Reload · Ctrl+R)"}
            aria-label={isActivePageLoading ? "Stop loading" : "Reload"}
          >
            {isActivePageLoading ? <X size={15} /> : <RotateCw size={14} />}
          </button>

          {/* Chrome Omnibox + Rich Autocomplete Dropdown Container */}
          <div className="relative flex-1 min-w-0 flex items-center">
            <form onSubmit={handleNavigateSubmit} className="w-full flex items-center">
              <div
                className={`w-full h-[30px] px-3 bg-white dark:bg-[#202124] border-[1.5px] flex items-center gap-2.5 transition-colors ${
                  isEditingAddress && omniboxItems.length > 0
                    ? "rounded-t-[16px] border-[#1a73e8] dark:border-[#a8c7fa] border-b-transparent"
                    : "rounded-full border-black/15 dark:border-[#5f6368]/60 focus-within:border-[#1a73e8] dark:focus-within:border-[#a8c7fa]"
                }`}
              >
                <span className="text-[13px] font-sans font-bold text-[#5f6368] dark:text-[#e8eaed] select-none shrink-0 leading-none">
                  G
                </span>

                <input
                  ref={addressInputRef}
                  type="text"
                  value={rawDisplayUrl}
                  onFocus={(e) => {
                    const targetEl = e.currentTarget;
                    const currentUrl = activeTabObj?.anchor ? "" : (activeTabObj?.url || addressInput || "");
                    setIsEditingAddress(true);
                    setOmniboxActiveIdx(0);
                    setAddressInput(currentUrl);
                    // Also refresh tab history in background so suggestions include latest visited URLs
                    void fetchAgentBrowserHistory(
                      agentId,
                      selectedTabId && !selectedTabId.startsWith("optimistic-") ? selectedTabId : undefined
                    ).then((items) => {
                      setHistoryItems(items);
                      items.forEach((it) => {
                        if (it.url) saveOmniboxEntry(it.title || it.url, it.url, false);
                      });
                    });
                    requestAnimationFrame(() => {
                      try {
                        targetEl.setSelectionRange(0, targetEl.value.length, "forward");
                        targetEl.scrollLeft = targetEl.scrollWidth;
                      } catch {}
                    });
                  }}
                  onMouseUp={(e) => {
                    if (
                      document.activeElement === e.currentTarget &&
                      e.currentTarget.selectionStart === 0 &&
                      e.currentTarget.selectionEnd === e.currentTarget.value.length
                    ) {
                      e.preventDefault();
                    }
                  }}
                  onKeyDown={(e) => {
                    if (!isEditingAddress || omniboxItems.length === 0) return;
                    if (e.key === "ArrowDown") {
                      e.preventDefault();
                      setOmniboxActiveIdx((prev) => (prev + 1) % omniboxItems.length);
                    } else if (e.key === "ArrowUp") {
                      e.preventDefault();
                      setOmniboxActiveIdx((prev) => (prev - 1 + omniboxItems.length) % omniboxItems.length);
                    } else if (e.key === "Escape") {
                      e.preventDefault();
                      setIsEditingAddress(false);
                      e.currentTarget.blur();
                    }
                  }}
                  onBlur={() => {
                    setTimeout(() => setIsEditingAddress(false), 160);
                  }}
                  onChange={(e) => {
                    setAddressInput(e.target.value);
                    setOmniboxActiveIdx(0);
                  }}
                  placeholder="Tìm kiếm trên Google hoặc nhập một URL"
                  className="w-full bg-transparent text-[13px] font-sans text-[#202124] dark:text-[#e8eaed] placeholder:text-[#5f6368] dark:placeholder:text-[#9aa0a6] outline-none truncate selection:bg-[#1a73e8]/30 dark:selection:bg-[#8ab4f8]/35"
                />
              </div>
            </form>

            {/* Chrome Omnibox Suggestions Dropdown matching the exact screenshot */}
            {isEditingAddress && omniboxItems.length > 0 && (
              <div
                data-testid="agent-browser-omnibox-suggestions"
                onMouseDown={(e) => e.preventDefault()}
                className="absolute left-0 right-0 top-full bg-white dark:bg-[#292a2d] border-x-[1.5px] border-b-[1.5px] border-[#1a73e8] dark:border-[#a8c7fa] rounded-b-[18px] shadow-[0_12px_32px_rgba(0,0,0,0.45)] pb-2 pt-1 z-50 overflow-hidden"
              >
                {omniboxItems.map((item, sIdx) => {
                  const isSelected = sIdx === omniboxActiveIdx;
                  return (
                    <div
                      key={`${item.kind}-${item.targetValue}-${sIdx}`}
                      onMouseEnter={() => setOmniboxActiveIdx(sIdx)}
                      onClick={() => void handleNavigateUrl(item.targetValue)}
                      className={`relative flex items-center gap-3 px-3.5 py-2 text-[13px] font-sans cursor-pointer transition-colors ${
                        isSelected
                          ? "bg-[#e8f0fe] dark:bg-[#3c4043] rounded-r-full mr-2"
                          : "hover:bg-black/5 dark:hover:bg-white/5"
                      }`}
                    >
                      {/* Left Blue Vertical Selection Pill Indicator matching Chrome */}
                      {isSelected && (
                        <span className="absolute left-0 top-1.5 bottom-1.5 w-[3px] rounded-r-full bg-[#1a73e8] dark:bg-[#8ab4f8]" />
                      )}

                      {/* Leading Icon */}
                      <span className="w-5 h-5 flex items-center justify-center text-[#5f6368] dark:text-[#9aa0a6] shrink-0">
                        {item.kind === "recent_search" ? (
                          <Clock size={14} />
                        ) : item.kind === "history_url" ? (
                          <Globe size={14} />
                        ) : (
                          <Search size={14} />
                        )}
                      </span>

                      {/* Suggestion Content */}
                      <div className="min-w-0 flex-1 truncate text-[#202124] dark:text-[#e8eaed]">
                        {item.kind === "primary" ? (
                          <span>
                            <span className="font-medium">{item.label}</span>
                            {item.subUrl && (
                              <span className="text-[#5f6368] dark:text-[#9aa0a6]"> — {item.subUrl}</span>
                            )}
                          </span>
                        ) : item.kind === "history_url" ? (
                          <span>
                            {renderHighlightedMatch(item.label, addressInput)}
                            {item.subUrl && (
                              <span className="text-[#1a73e8] dark:text-[#8ab4f8] ml-1.5">
                                - {renderHighlightedMatch(item.subUrl, addressInput)}
                              </span>
                            )}
                          </span>
                        ) : (
                          <span>{renderHighlightedMatch(item.label, addressInput)}</span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Right Action Icons on Top Nav Bar: Stream Engine Toggle (CDP GPU vs WebRTC H.264/VP9), Find in Page, Zoom Controls, History, Touch/Mouse Mode, Rotate Landscape */}
          <div className="flex items-center gap-0.5 shrink-0">
            <Tooltip
              content={
                streamEngineMode === "webrtc"
                  ? "Đang phát luồng WebRTC H.264/VP9 (Selkies 60fps Video Stream) · Bấm để chuyển về CDP GPU Canvas (120Hz Scroll)"
                  : "Đang dùng CDP GPU Canvas (120Hz Predictive Scroll & Native Cursor) · Bấm để chuyển sang luồng WebRTC H.264/VP9 60fps khi xem video/animation tốc độ cao"
              }
              placement="bottom"
            >
              <button
                type="button"
                data-testid="agent-browser-stream-engine-btn"
                data-stream-engine={streamEngineMode}
                onClick={() => handleToggleStreamEngine()}
                className={`hidden h-7 px-2 mr-0.5 rounded-full items-center gap-1 text-[10px] font-mono font-semibold transition-all cursor-pointer shrink-0 border ${
                  streamEngineMode === "webrtc"
                    ? "bg-emerald-500/15 dark:bg-emerald-400/20 text-emerald-700 dark:text-emerald-300 border-emerald-500/35 shadow-2xs"
                    : "bg-black/[0.04] dark:bg-white/[0.06] hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed] border-black/10 dark:border-white/10"
                }`}
                aria-label={streamEngineMode === "webrtc" ? "Switch to CDP GPU Canvas" : "Switch to WebRTC H.264/VP9 Stream"}
              >
                <Radio size={11} className={streamEngineMode === "webrtc" ? "text-emerald-500 animate-pulse" : "text-[#1a73e8] dark:text-[#8ab4f8]"} />
                <span className="hidden sm:inline">
                  {streamEngineMode === "webrtc" ? "WebRTC H.264/VP9" : "CDP GPU"}
                </span>
                <span className="sm:hidden">
                  {streamEngineMode === "webrtc" ? "H.264" : "GPU"}
                </span>
              </button>
            </Tooltip>

            <Tooltip
              content={
                mobileInteractionMode === "mouse"
                  ? "Chế độ Chuột ảo (1 chạm: di chuyển/click · 2 chạm vuốt: cuộn trang · 2 chạm nhấn: chuột phải) · Bấm để chuyển sang Chạm"
                  : "Chế độ Chạm trực tiếp (Mặc định trên điện thoại) · Bấm để chuyển sang Chuột ảo (Trackpad)"
              }
              placement="bottom"
            >
              <button
                type="button"
                data-testid="agent-browser-quick-input-mode-btn"
                data-input-mode={mobileInteractionMode}
                onClick={() => {
                  triggerHaptic(8);
                  setMobileInteractionMode((m) => (m === "mouse" ? "touch" : "mouse"));
                }}
                className={`h-7 px-2 rounded-full flex items-center gap-1 text-[11px] font-sans font-medium transition-colors cursor-pointer shrink-0 border ${
                  mobileInteractionMode === "mouse"
                    ? "bg-[#1a73e8]/15 dark:bg-[#8ab4f8]/20 text-[#1a73e8] dark:text-[#8ab4f8] border-[#1a73e8]/30 dark:border-[#8ab4f8]/35"
                    : "bg-black/[0.04] dark:bg-white/[0.06] hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] border-black/10 dark:border-white/10"
                }`}
                aria-label={mobileInteractionMode === "mouse" ? "Switch to Touch Mode" : "Switch to Mouse Trackpad Mode"}
              >
                {mobileInteractionMode === "mouse" ? <MousePointer2 size={13} /> : <Hand size={13} />}
                <span className="hidden xs:inline">{mobileInteractionMode === "mouse" ? "Chuột" : "Chạm"}</span>
              </button>
            </Tooltip>

            {browserZoomPercent !== 100 && (
              <button
                type="button"
                data-testid="agent-browser-zoom-reset-btn"
                onClick={() => handleZoomStep("reset")}
                className="h-6 px-1.5 rounded-full bg-[#1a73e8]/15 dark:bg-[#8ab4f8]/20 text-[#1a73e8] dark:text-[#8ab4f8] text-[10px] font-mono font-semibold hover:bg-[#1a73e8]/25 transition-colors cursor-pointer"
                title="Đặt lại tỉ lệ màn hình 100% (Ctrl+0)"
              >
                {browserZoomPercent}%
              </button>
            )}

            <div className="relative shrink-0" onClick={(e) => e.stopPropagation()}>
              <Tooltip content="Menu công cụ & tỉ lệ màn hình" placement="bottom">
                <button
                  type="button"
                  data-testid="agent-browser-more-menu-btn"
                  onClick={() => {
                    setIsBrowserMoreMenuOpen((prev) => !prev);
                    if (isHistoryOpen) setIsHistoryOpen(false);
                  }}
                  className={`relative h-7 w-7 rounded-full flex items-center justify-center transition-colors cursor-pointer ${
                    isBrowserMoreMenuOpen || isHistoryOpen || isFindOpen || isLandscapeRotated || isDesktopSiteMode || browserZoomPercent !== 100 || vpnStatus?.enabled
                      ? "bg-[#1a73e8]/15 dark:bg-[#8ab4f8]/20 text-[#1a73e8] dark:text-[#8ab4f8]"
                      : "hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed]"
                  }`}
                  aria-label="More browser options"
                >
                  <MoreVertical size={15} />
                  {vpnStatus?.enabled && (
                    <span
                      data-testid="agent-browser-more-vpn-dot"
                      className="absolute -top-0.5 -right-0.5 h-2 w-2 rounded-full bg-emerald-500 ring-2 ring-white dark:ring-[#202124]"
                      title={`VPN ${vpnStatus.region || "VN"} đang bật (${vpnStatus.publicIp || vpnStatus.server || "proxy360 pool"})`}
                    />
                  )}
                </button>
              </Tooltip>

              {isBrowserMoreMenuOpen && (
                <div
                  data-testid="agent-browser-more-menu-popover"
                  className="absolute right-0 top-full mt-1.5 w-60 rounded-xl bg-white dark:bg-[#292a2d] border border-black/15 dark:border-white/15 shadow-2xl py-1.5 z-50 flex flex-col text-[12px] text-[#202124] dark:text-[#e8eaed] animate-in fade-in zoom-in-95 duration-100"
                >
                  {/* Row 1: Screen Scale / Zoom In & Out Controls */}
                  <div className="px-3 py-1.5 flex items-center justify-between border-b border-black/8 dark:border-white/10">
                    <span className="flex items-center gap-2 text-[#5f6368] dark:text-[#9aa0a6] font-medium">
                      <ZoomIn size={13} />
                      <span>Tỉ lệ màn hình</span>
                    </span>
                    <div className="flex items-center gap-1">
                      <button
                        type="button"
                        data-testid="agent-browser-scale-down-btn"
                        onClick={() => handleZoomStep(-15)}
                        className="h-6 w-6 rounded-md hover:bg-black/10 dark:hover:bg-white/10 flex items-center justify-center text-[#202124] dark:text-[#e8eaed] font-mono text-[13px] cursor-pointer"
                        title="Giảm tỉ lệ màn hình (-15%)"
                        aria-label="Decrease screen scale"
                      >
                        <ZoomOut size={13} />
                      </button>
                      <button
                        type="button"
                        data-testid="agent-browser-scale-reset-btn"
                        onClick={() => handleZoomStep("reset")}
                        className="min-w-[44px] h-6 px-1.5 rounded-md bg-black/[0.05] dark:bg-white/[0.08] hover:bg-black/10 dark:hover:bg-white/15 font-mono text-[11px] font-semibold text-center cursor-pointer"
                        title="Đặt lại 100%"
                      >
                        {browserZoomPercent}%
                      </button>
                      <button
                        type="button"
                        data-testid="agent-browser-scale-up-btn"
                        onClick={() => handleZoomStep(15)}
                        className="h-6 w-6 rounded-md hover:bg-black/10 dark:hover:bg-white/10 flex items-center justify-center text-[#202124] dark:text-[#e8eaed] font-mono text-[13px] cursor-pointer"
                        title="Tăng tỉ lệ màn hình (+15%)"
                        aria-label="Increase screen scale"
                      >
                        <ZoomIn size={13} />
                      </button>
                    </div>
                  </div>

                  {/* Row 2: Find in Page */}
                  <button
                    type="button"
                    data-testid="agent-browser-find-btn"
                    onClick={() => {
                      setIsBrowserMoreMenuOpen(false);
                      handleToggleFindBar();
                    }}
                    className="w-full px-3 py-2 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer"
                  >
                    <span className="flex items-center gap-2.5">
                      <Search size={14} className="text-[#5f6368] dark:text-[#9aa0a6]" />
                      <span>Tìm trong trang</span>
                    </span>
                    <span className="text-[10px] font-mono text-[#5f6368] dark:text-[#9aa0a6]">Ctrl+F</span>
                  </button>

                  {/* Row 3: Browser History */}
                  <button
                    type="button"
                    data-testid="agent-browser-history-btn"
                    onClick={() => {
                      setIsBrowserMoreMenuOpen(false);
                      void handleToggleHistory();
                    }}
                    className="w-full px-3 py-2 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer"
                  >
                    <span className="flex items-center gap-2.5">
                      <Clock size={14} className="text-[#5f6368] dark:text-[#9aa0a6]" />
                      <span>Lịch sử duyệt web</span>
                    </span>
                  </button>

                  {/* Row 4: Mouse Mode vs Touch Mode */}
                  <button
                    type="button"
                    data-testid="computer-mobile-input-mode-btn"
                    onClick={() => {
                      setMobileInteractionMode((m) => (m === "mouse" ? "touch" : "mouse"));
                      setIsBrowserMoreMenuOpen(false);
                    }}
                    className="w-full px-3 py-2 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer"
                  >
                    <span className="flex items-center gap-2.5">
                      {mobileInteractionMode === "mouse" ? (
                        <MousePointer2 size={14} className="text-[#1a73e8] dark:text-[#8ab4f8]" />
                      ) : (
                        <Hand size={14} className="text-[#5f6368] dark:text-[#9aa0a6]" />
                      )}
                      <span>Chế độ điều khiển</span>
                    </span>
                    <span className="px-1.5 py-0.5 rounded bg-black/[0.06] dark:bg-white/[0.1] text-[10px] font-medium text-[#1a73e8] dark:text-[#8ab4f8]">
                      {mobileInteractionMode === "mouse" ? "Chuột ảo" : "Chạm"}
                    </span>
                  </button>

                  {/* Row 5: View as Phone vs View as Desktop Mode */}
                  <div className="px-3 py-2 flex flex-col gap-1.5 border-t border-black/8 dark:border-white/10">
                    <div className="flex items-center justify-between">
                      <span className="flex items-center gap-2 text-[#5f6368] dark:text-[#9aa0a6] font-medium">
                        {effectiveViewMode === "phone" ? (
                          <Smartphone size={13} className="text-[#1a73e8] dark:text-[#8ab4f8]" />
                        ) : (
                          <Monitor size={13} className="text-[#1a73e8] dark:text-[#8ab4f8]" />
                        )}
                        <span>Chế độ hiển thị (View as)</span>
                      </span>
                      <button
                        type="button"
                        data-testid="computer-device-site-mode-btn"
                        data-view-as={effectiveViewMode}
                        onClick={() => void handleSetBrowserViewMode(effectiveViewMode === "phone" ? "desktop" : "phone")}
                        className="px-1.5 py-0.5 rounded bg-black/[0.06] dark:bg-white/[0.1] text-[10px] font-medium text-[#1a73e8] dark:text-[#8ab4f8] cursor-pointer"
                      >
                        {effectiveViewMode === "phone" ? "Phone" : "Desktop"}
                      </button>
                    </div>
                    <div className="grid grid-cols-2 gap-1 bg-black/[0.04] dark:bg-white/[0.06] p-0.5 rounded-lg">
                      <button
                        type="button"
                        data-testid="agent-browser-view-as-phone-btn"
                        aria-pressed={effectiveViewMode === "phone"}
                        onClick={() => void handleSetBrowserViewMode("phone")}
                        className={`px-2 py-1 rounded-md flex items-center justify-center gap-1.5 text-[11px] font-medium transition-colors cursor-pointer ${
                          effectiveViewMode === "phone"
                            ? "bg-white dark:bg-[#3c4043] text-[#1a73e8] dark:text-[#8ab4f8] shadow-2xs font-semibold"
                            : "text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed]"
                        }`}
                      >
                        <Smartphone size={12} />
                        <span>View as Phone</span>
                      </button>
                      <button
                        type="button"
                        data-testid="agent-browser-view-as-desktop-btn"
                        aria-pressed={effectiveViewMode === "desktop"}
                        onClick={() => void handleSetBrowserViewMode("desktop")}
                        className={`px-2 py-1 rounded-md flex items-center justify-center gap-1.5 text-[11px] font-medium transition-colors cursor-pointer ${
                          effectiveViewMode === "desktop"
                            ? "bg-white dark:bg-[#3c4043] text-[#1a73e8] dark:text-[#8ab4f8] shadow-2xs font-semibold"
                            : "text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e8eaed]"
                        }`}
                      >
                        <Monitor size={12} />
                        <span>View as Desktop</span>
                      </button>
                    </div>
                  </div>

                  {/* Row 6: Rotate 90° Landscape */}
                  <button
                    type="button"
                    data-testid="computer-rotate-landscape-btn"
                    onClick={() => {
                      setIsLandscapeRotated((r) => !r);
                      setIsBrowserMoreMenuOpen(false);
                    }}
                    className="w-full px-3 py-2 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer"
                  >
                    <span className="flex items-center gap-2.5">
                      <Smartphone size={14} className={isLandscapeRotated ? "rotate-90 text-[#1a73e8] dark:text-[#8ab4f8] transition-transform" : "text-[#5f6368] dark:text-[#9aa0a6] transition-transform"} />
                      <span>Xoay ngang màn hình</span>
                    </span>
                    <span className="text-[10px] font-mono text-[#5f6368] dark:text-[#9aa0a6]">
                      {isLandscapeRotated ? "Ngang 90°" : "Dọc"}
                    </span>
                  </button>

                  {/* Row 7: Per-Profile VPN (proxy360 Round-Robin IP Pool) */}
                  <div className="border-t border-black/8 dark:border-white/10 mt-1 pt-1 flex flex-col">
                    <button
                      type="button"
                      data-testid="agent-browser-vpn-toggle-btn"
                      data-vpn-enabled={vpnStatus?.enabled ? "true" : "false"}
                      disabled={isTogglingVpn}
                      onClick={() => void handleToggleVpn(false)}
                      className="w-full px-3 py-2 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer"
                    >
                      <span className="flex items-center gap-2.5">
                        {isTogglingVpn ? (
                          <Loader2 size={14} className="animate-spin text-[#1a73e8] dark:text-[#8ab4f8]" />
                        ) : vpnStatus?.enabled ? (
                          <ShieldCheck size={14} className="text-emerald-500" />
                        ) : (
                          <Shield size={14} className="text-[#5f6368] dark:text-[#9aa0a6]" />
                        )}
                        <span className="flex flex-col">
                          <span className="font-medium">VPN Profile ({vpnStatus?.region || "VN"})</span>
                          <span className="text-[10px] font-mono text-[#5f6368] dark:text-[#9aa0a6]">
                            {vpnStatus?.enabled
                              ? (vpnStatus.publicIp || vpnStatus.server || "proxy360 pool")
                              : "Tắt · Dùng mạng gốc VPS"}
                          </span>
                        </span>
                      </span>
                      <span
                        className={`px-1.5 py-0.5 rounded text-[10px] font-mono font-semibold ${
                          vpnStatus?.enabled
                            ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-300 border border-emerald-500/30"
                            : "bg-black/[0.06] dark:bg-white/[0.1] text-[#5f6368] dark:text-[#9aa0a6]"
                        }`}
                      >
                        {vpnStatus?.enabled ? "ĐANG BẬT" : "BẬT VPN"}
                      </span>
                    </button>

                    {vpnStatus?.enabled && (
                      <button
                        type="button"
                        data-testid="agent-browser-vpn-rotate-btn"
                        disabled={isTogglingVpn}
                        onClick={() => void handleToggleVpn(true)}
                        className="w-full px-3 py-1.5 text-left flex items-center justify-between hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer text-[11px] text-[#1a73e8] dark:text-[#8ab4f8]"
                      >
                        <span className="flex items-center gap-2.5 pl-0.5">
                          <RefreshCw size={12} className={isTogglingVpn ? "animate-spin" : ""} />
                          <span>Xoay tour IP kế tiếp (Pool)</span>
                        </span>
                        <span className="text-[10px] font-mono opacity-80">Round-Robin</span>
                      </button>
                    )}
                  </div>
                </div>
              )}

              {isHistoryOpen && (
                <div
                  data-testid="agent-browser-history-popover"
                  onClick={(e) => e.stopPropagation()}
                  className="absolute right-0 top-full mt-1.5 w-72 sm:w-80 max-h-72 rounded-xl bg-white dark:bg-[#292a2d] border border-black/15 dark:border-white/15 shadow-2xl overflow-hidden flex flex-col z-50 animate-in fade-in zoom-in-95 duration-100"
                >
                  <div className="px-3 py-2 border-b border-black/10 dark:border-white/10 flex items-center justify-between text-[12px] font-semibold text-[#202124] dark:text-[#e8eaed]">
                    <span className="flex items-center gap-1.5">
                      <Clock size={13} className="text-[#1a73e8] dark:text-[#8ab4f8]" />
                      <span>Lịch sử duyệt web</span>
                    </span>
                    <button
                      type="button"
                      onClick={() => setIsHistoryOpen(false)}
                      className="h-5 w-5 rounded-full hover:bg-black/10 dark:hover:bg-white/10 flex items-center justify-center text-[#5f6368] dark:text-[#9aa0a6]"
                    >
                      <X size={12} />
                    </button>
                  </div>

                  <div className="flex-1 overflow-y-auto divide-y divide-black/5 dark:divide-white/5 py-1">
                    {isLoadingHistory ? (
                      <div className="px-3 py-4 text-center text-[11px] text-[#5f6368] dark:text-[#9aa0a6]">
                        Đang tải lịch sử...
                      </div>
                    ) : historyItems.length === 0 && localHistoryEntries.length === 0 ? (
                      <div className="px-3 py-4 text-center text-[11px] text-[#5f6368] dark:text-[#9aa0a6]">
                        Chưa có lịch sử trên tab này
                      </div>
                    ) : (
                      (historyItems.length > 0 ? historyItems : localHistoryEntries.map((lh, i) => ({ id: i, title: lh.title, url: lh.url, isCurrent: false }))).map((hItem, hIdx) => {
                        const hFav = getTabFaviconUrl(hItem.url, false);
                        return (
                          <button
                            key={`${hItem.id}-${hIdx}`}
                            type="button"
                            onClick={() => void handleNavigateUrl(hItem.url)}
                            className={`w-full px-3 py-2 text-left flex items-center gap-2.5 hover:bg-black/5 dark:hover:bg-white/10 transition-colors cursor-pointer ${
                              hItem.isCurrent ? "bg-[#1a73e8]/10 dark:bg-[#8ab4f8]/10" : ""
                            }`}
                          >
                            {hFav ? (
                              <img src={hFav} alt="" className="w-3.5 h-3.5 rounded-xs shrink-0" />
                            ) : (
                              <Globe size={13} className="text-[#5f6368] dark:text-[#9aa0a6] shrink-0" />
                            )}
                            <div className="min-w-0 flex-1">
                              <div className="text-[12px] font-medium text-[#202124] dark:text-[#e8eaed] truncate">
                                {hItem.title}
                              </div>
                              <div className="text-[10px] font-mono text-[#1a73e8] dark:text-[#8ab4f8] truncate">
                                {hItem.url}
                              </div>
                            </div>
                          </button>
                        );
                      })
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>

          {isActivePageLoading && (
            <div
              data-testid="agent-browser-loading-bar"
              role="progressbar"
              aria-label="Đang tải trang"
              className="pointer-events-none absolute bottom-0 inset-x-0 h-[2px] overflow-hidden"
            >
              <div className="agent-browser-loading-sweep h-full w-1/3 bg-[#1a73e8] dark:bg-[#a8c7fa]" />
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div
      ref={containerRef}
      onClick={() => {
        if (isHistoryOpen) setIsHistoryOpen(false);
        if (isBrowserMoreMenuOpen) setIsBrowserMoreMenuOpen(false);
      }}
      className="relative w-full h-full bg-[#F8F3ED] dark:bg-[#0c0c12] overflow-hidden touch-manipulation select-none flex flex-col"
    >
      <div
        style={
          isLandscapeRotated
            ? {
                position: "absolute",
                top: "50%",
                left: "50%",
                width: `${boxSize.h}px`,
                height: `${boxSize.w}px`,
                transform: "translate(-50%, -50%) rotate(90deg)",
                transformOrigin: "center center",
              }
            : undefined
        }
        className={`relative transition-transform duration-200 ease-out flex flex-col bg-[#FFFDF9] dark:bg-[#0c0c12] overflow-hidden ${
          isLandscapeRotated ? "z-20 shadow-2xl" : "w-full h-full flex-1"
        }`}
      >
        {/* Unified Customized Browser Tab Strip & Omnibox Header (Hidden in Fullscreen Mode on Phone for 100% Web Viewport) */}
        {!(isMaximized && isPhoneClient) && renderBrowserChromeHeader()}

        {/* Compact Floating Exit-Fullscreen Control Pill on Phone when Web Controls are hidden */}
        {isMaximized && isPhoneClient && (
          <div
            data-testid="agent-browser-phone-fullscreen-floating-bar"
            onClick={(e) => e.stopPropagation()}
            className="absolute top-2.5 right-2.5 z-50 flex items-center gap-1 p-1 rounded-full bg-black/65 hover:bg-black/80 backdrop-blur-md border border-white/15 shadow-lg text-white transition-all"
          >
            <button
              type="button"
              data-testid="agent-browser-phone-fullscreen-rotate-btn"
              onClick={() => {
                triggerHaptic(8);
                setIsLandscapeRotated((r) => !r);
              }}
              className={`h-7 w-7 rounded-full flex items-center justify-center transition-colors cursor-pointer ${
                isLandscapeRotated ? "bg-[#1a73e8] text-white" : "hover:bg-white/15 text-white/90"
              }`}
              title={isLandscapeRotated ? "Quay về màn hình dọc" : "Xoay ngang màn hình 90°"}
              aria-label="Toggle landscape rotation"
            >
              <Smartphone size={13} className={isLandscapeRotated ? "rotate-90 transition-transform" : "transition-transform"} />
            </button>
            {onToggleMaximize && (
              <button
                type="button"
                data-testid="agent-browser-phone-fullscreen-exit-btn"
                onClick={() => {
                  triggerHaptic(8);
                  onToggleMaximize();
                }}
                className="h-7 px-2.5 rounded-full bg-white/15 hover:bg-white/25 text-white text-[11px] font-medium flex items-center gap-1 transition-colors cursor-pointer"
                title={maximizeTooltip || "Thoát toàn màn hình (Hiện thanh điều khiển)"}
                aria-label="Exit fullscreen and show browser controls"
              >
                <Minimize2 size={12} />
                <span>Thu nhỏ</span>
              </button>
            )}
          </div>
        )}

        {/* Main Webpage Viewport Area (Full Height & Interactive Touch/Mouse/Pinch-Zoom) */}
        <div className="relative flex-1 w-full min-h-0 bg-[#F8F3ED] dark:bg-[#0a0a0f] overflow-hidden flex items-center justify-center">
          {isFindOpen && (
            <div
              data-testid="agent-browser-find-bar"
              onClick={(e) => e.stopPropagation()}
              className="absolute top-2 right-5 z-40 flex items-center gap-1 px-2.5 py-1.5 rounded-xl bg-white dark:bg-[#292a2d] border border-black/15 dark:border-white/15 shadow-xl"
            >
              <Search size={13} className="text-[#5f6368] dark:text-[#9aa0a6] shrink-0 mr-0.5" />
              <input
                ref={findInputRef}
                type="text"
                value={findQuery}
                onChange={(e) => {
                  const val = e.target.value;
                  setFindQuery(val);
                  void handleFindInPage(val, "next");
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    void handleFindInPage(findQuery, e.shiftKey ? "prev" : "next");
                  } else if (e.key === "Escape") {
                    e.preventDefault();
                    setIsFindOpen(false);
                    void handleFindInPage("", "next");
                  }
                }}
                placeholder="Tìm trong trang..."
                className="w-36 sm:w-44 bg-transparent text-[12px] font-sans text-[#202124] dark:text-[#e8eaed] placeholder:text-[#5f6368] dark:placeholder:text-[#9aa0a6] outline-none"
              />
              <div className="h-3.5 w-[1px] bg-black/10 dark:bg-white/10 mx-0.5" />
              <button
                type="button"
                onClick={() => void handleFindInPage(findQuery, "prev")}
                className="h-6 w-6 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-white flex items-center justify-center cursor-pointer"
                title="Kết quả trước (Shift+Enter)"
                aria-label="Previous match"
              >
                <ChevronUp size={13} />
              </button>
              <button
                type="button"
                onClick={() => void handleFindInPage(findQuery, "next")}
                className="h-6 w-6 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-white flex items-center justify-center cursor-pointer"
                title="Kết quả tiếp theo (Enter)"
                aria-label="Next match"
              >
                <ChevronDown size={13} />
              </button>
              <button
                type="button"
                onClick={() => {
                  setIsFindOpen(false);
                  void handleFindInPage("", "next");
                }}
                className="h-6 w-6 rounded-full hover:bg-black/10 dark:hover:bg-white/10 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-white flex items-center justify-center cursor-pointer"
                title="Đóng tìm kiếm (Esc)"
                aria-label="Close find bar"
              >
                <X size={12} />
              </button>
            </div>
          )}

          {streamEngineMode === "webrtc" && webrtcSignedUrl && webrtcStatus === "ready" && (
            <div
              data-testid="agent-browser-webrtc-container"
              className="absolute inset-0 z-30 w-full h-full bg-[#0a0a0f] flex flex-col overflow-hidden"
            >
              <iframe
                key={`webrtc-${agentId}-${attempt}-${reloadKey}`}
                data-testid="agent-browser-webrtc-iframe"
                src={webrtcSignedUrl}
                title={`${title || "Agent Browser"} · WebRTC H.264/VP9 Stream`}
                allow="autoplay; clipboard-read; clipboard-write; fullscreen; microphone; camera"
                className="w-full h-full border-0 flex-1 bg-[#0a0a0f]"
              />
              <div className="pointer-events-none absolute bottom-2.5 right-3 z-40 flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-black/75 backdrop-blur-md border border-emerald-500/35 text-[10px] font-mono text-emerald-300 shadow-lg">
                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse" />
                <span>WebRTC H.264/VP9 · 60fps</span>
                <button
                  type="button"
                  onClick={() => handleToggleStreamEngine("canvas")}
                  className="pointer-events-auto ml-1 px-1.5 py-0.5 rounded bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
                  title="Chuyển về CDP GPU Canvas"
                >
                  CDP GPU
                </button>
              </div>
            </div>
          )}

          {streamEngineMode === "webrtc" && webrtcStatus === "connecting" && (
            <div
              data-testid="agent-browser-webrtc-connecting"
              className="pointer-events-none absolute top-3 left-1/2 -translate-x-1/2 z-40 flex items-center gap-2 px-3 py-1.5 rounded-full bg-black/80 backdrop-blur-md border border-emerald-500/30 text-[11px] font-mono text-emerald-300 shadow-xl"
            >
              <Loader2 size={12} className="animate-spin text-emerald-400" />
              <span>Đang kết nối luồng WebRTC H.264/VP9 60fps...</span>
            </div>
          )}

          <div
            className={
              effectiveViewMode === "phone" && !isPhoneClient && !isLandscapeRotated
                ? "relative h-full max-w-full aspect-[390/844] rounded-2xl overflow-hidden shadow-2xl border border-black/15 dark:border-white/15 bg-[#FFFDF9] dark:bg-[#0a0a0f]"
                : "relative w-full h-full"
            }
          >
          <AgentBrowserPreview
            agentId={agentId}
            pageId={selectedTabId || undefined}
            enabled={boxSize.w > 0 && boxSize.h > 0}
            intervalMs={800}
            liveWs={true}
            refreshSignal={attempt + reloadKey}
            isLandscapeRotated={isLandscapeRotated}
            interactive={true}
            isResizing={isResizing}
            mobileInputMode={mobileInteractionMode}
            isMobileDevice={effectiveViewMode === "phone"}
            isVirtualKeyboardOpen={isVirtualKeyboardOpen}
            virtualKeyboardHeight={virtualKeyboardHeight}
            viewportWidth={computeActiveBrowserViewport().w}
            viewportHeight={computeActiveBrowserViewport().h}
            frameCacheRef={tabFrameCacheRef}
            onPageLoadingState={handlePageLoadingState}
            onPopupOpened={handlePopupOpened}
            externalZoomPercent={browserZoomPercent}
            onZoomStep={handleZoomStep}
            onBrowserShortcut={(shortcut) => {
              if (shortcut === "new_tab") void handleCreateNewTab();
              else if (shortcut === "close_tab" && selectedTabId) void handleCloseTab(selectedTabId);
              else if (shortcut === "focus_address") addressInputRef.current?.focus();
              else if (shortcut === "reload") void handleBrowserAction("reload");
              else if (shortcut === "back") void handleBrowserAction("back");
              else if (shortcut === "forward") void handleBrowserAction("forward");
              else if (shortcut === "find") handleToggleFindBar();
            }}
          />
          </div>
        </div>
      </div>
    </div>
  );
}

/** Live CDP screencast + Zero-Re-Render Direct DOM Pipeline + Kinetic Inertia Scrolling + 2-Mode Mobile Touch vs Trackpad Mouse. */
function AgentBrowserPreview({
  agentId,
  pageId,
  enabled,
  intervalMs = 5000,
  liveWs = false,
  refreshSignal = 0,
  isLandscapeRotated = false,
  interactive = false,
  isResizing = false,
  mobileInputMode = "touch",
  isMobileDevice = false,
  isVirtualKeyboardOpen = false,
  virtualKeyboardHeight = 0,
  viewportWidth = 0,
  viewportHeight = 0,
  frameCacheRef,
  externalZoomPercent = 100,
  onZoomStep,
  onBrowserShortcut,
  onPageLoadingState,
  onPopupOpened,
}: {
  agentId: string;
  pageId?: string;
  enabled: boolean;
  intervalMs?: number;
  liveWs?: boolean;
  refreshSignal?: number;
  isLandscapeRotated?: boolean;
  interactive?: boolean;
  isResizing?: boolean;
  mobileInputMode?: "touch" | "mouse";
  isMobileDevice?: boolean;
  isVirtualKeyboardOpen?: boolean;
  virtualKeyboardHeight?: number;
  viewportWidth?: number;
  viewportHeight?: number;
  frameCacheRef?: React.MutableRefObject<Record<string, string>>;
  externalZoomPercent?: number;
  onZoomStep?: (deltaPct: number | "reset") => void;
  onBrowserShortcut?: (shortcut: "new_tab" | "close_tab" | "focus_address" | "reload" | "back" | "forward" | "find") => void;
  onPageLoadingState?: (state: { loading: boolean; url: string; title: string }) => void;
  onPopupOpened?: (popup: { openerId: string; url: string }) => void;
}) {
  const onPageLoadingStateRef = useRef(onPageLoadingState);
  onPageLoadingStateRef.current = onPageLoadingState;
  const onPopupOpenedRef = useRef(onPopupOpened);
  onPopupOpenedRef.current = onPopupOpened;
  const cacheKey = `${agentId}:${pageId || "default"}`;
  const initCached = frameCacheRef?.current?.[cacheKey];
  const validInitCached = initCached && initCached !== "__loading__" ? initCached : "";
  const [hasFrame, setHasFrame] = useState<boolean>(() => Boolean(validInitCached));
  const [failures, setFailures] = useState(0);
  const [refreshNonce, setRefreshNonce] = useState(0);

  const cursorNormRef = useRef<{ x: number; y: number }>({ x: 0.5, y: 0.5 });
  const zoomScaleRef = useRef<number>(1);
  const zoomPanRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const predictiveScrollOffsetRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const predictiveResetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const viewportBoxRef = useRef<HTMLDivElement>(null);
  const zoomWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const cursorElRef = useRef<HTMLDivElement>(null);
  const scrollbarTrackRef = useRef<HTMLDivElement>(null);
  const scrollbarThumbRef = useRef<HTMLDivElement>(null);
  const scrollMetricsRef = useRef<{ scrollTop: number; scrollHeight: number; clientHeight: number }>({
    scrollTop: 0,
    scrollHeight: 0,
    clientHeight: 0,
  });
  const scrollbarDragRef = useRef<{
    active: boolean;
    pointerId: number;
    startY: number;
    startRatio: number;
    lastSentAt: number;
  }>({ active: false, pointerId: -1, startY: 0, startRatio: 0, lastSentAt: 0 });
  const currentSrcRef = useRef<string>(validInitCached);
  const naturalDimsRef = useRef<{ w: number; h: number }>({ w: 0, h: 0 });
  const usingCanvasGpuRef = useRef<boolean>(false);
  const lastCacheSnapshotAtRef = useRef<number>(0);
  const remoteCursorStyleRef = useRef<string>("default");
  const IME_PROXY_PAD = "                                ";
  const imeProxyRef = useRef<HTMLTextAreaElement>(null);
  const imeComposingRef = useRef<boolean>(false);
  const imeCommittedValRef = useRef<string>(IME_PROXY_PAD);
  const imeDebounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastRemoteTextFocusAtRef = useRef<number>(0);
  const remoteEditableFocusRef = useRef<{ editable: boolean; inputType: string; yRatio: number; bottomRatio: number }>({
    editable: false,
    inputType: "text",
    yRatio: 0.5,
    bottomRatio: 0.5,
  });
  const keyboardPanOffsetYRef = useRef<number>(0);
  const inputQueueChainRef = useRef<Promise<void>>(Promise.resolve());

  const resetImeProxyBuffer = () => {
    const el = imeProxyRef.current;
    if (!el || imeComposingRef.current) return;
    if (imeDebounceTimerRef.current) {
      clearTimeout(imeDebounceTimerRef.current);
      imeDebounceTimerRef.current = null;
    }
    imeCommittedValRef.current = IME_PROXY_PAD;
    el.value = IME_PROXY_PAD;
    try { el.setSelectionRange(IME_PROXY_PAD.length, IME_PROXY_PAD.length); } catch {}
  };

  const focusImeProxy = () => {
    if (!interactive) return;
    const el = imeProxyRef.current;
    if (el) {
      if (document.activeElement !== el) {
        el.focus({ preventScroll: true });
      }
      if (!imeComposingRef.current && (el.value.length < 8 || el.value.length > 160)) {
        resetImeProxyBuffer();
      } else if (!imeComposingRef.current) {
        try { el.setSelectionRange(el.value.length, el.value.length); } catch {}
      }
    } else {
      viewportBoxRef.current?.focus({ preventScroll: true });
    }
  };

  const applyScrollMetricsDom = (scrollTop: number, scrollHeight: number, clientHeight: number) => {
    scrollMetricsRef.current = { scrollTop, scrollHeight, clientHeight };
    const trackEl = scrollbarTrackRef.current;
    const thumbEl = scrollbarThumbRef.current;
    if (!trackEl || !thumbEl) return;
    if (scrollHeight <= clientHeight + 4 || clientHeight <= 0) {
      trackEl.style.opacity = "0";
      trackEl.style.pointerEvents = "none";
      return;
    }
    trackEl.style.opacity = "1";
    trackEl.style.pointerEvents = "auto";
    const ratioVisible = Math.max(0.08, Math.min(1, clientHeight / scrollHeight));
    const maxScroll = Math.max(1, scrollHeight - clientHeight);
    const scrollProgress = Math.max(0, Math.min(1, scrollTop / maxScroll));
    const thumbHeightPct = ratioVisible * 100;
    const thumbTopPct = scrollProgress * (100 - thumbHeightPct);
    thumbEl.style.height = `${thumbHeightPct.toFixed(2)}%`;
    thumbEl.style.top = `${thumbTopPct.toFixed(2)}%`;
  };

  const applyRemoteCursorStyleDom = (rawCursor: string) => {
    const rawClean = (rawCursor || "default").trim().toLowerCase();
    // Sanitize any custom url(...) CSS cursor down to its standard keyword fallback so local browser CSS cursor always renders natively
    const keywordMatch = rawClean.match(/(pointer|text|vertical-text|grab|grabbing|move|not-allowed|no-drop|wait|progress|crosshair|help|zoom-in|zoom-out|col-resize|row-resize|ew-resize|ns-resize|nesw-resize|nwse-resize|n-resize|e-resize|s-resize|w-resize|ne-resize|nw-resize|se-resize|sw-resize|cell|copy|alias|context-menu|none|default)\s*$/i);
    const clean = keywordMatch ? keywordMatch[1].toLowerCase() : (rawClean === "auto" || !rawClean ? "default" : rawClean);
    remoteCursorStyleRef.current = clean;
    if (clean === "text") {
      lastRemoteTextFocusAtRef.current = Date.now();
    }
    if (viewportBoxRef.current) {
      viewportBoxRef.current.style.cursor = clean;
      viewportBoxRef.current.setAttribute("data-remote-cursor", clean);
    }
    if (zoomWrapperRef.current) {
      zoomWrapperRef.current.style.cursor = clean;
    }
    const curEl = cursorElRef.current;
    if (curEl) {
      curEl.setAttribute("data-cursor-kind", clean);
      const arrowSvg = curEl.querySelector('[data-cursor-shape="arrow"]') as HTMLElement | null;
      const pointerSvg = curEl.querySelector('[data-cursor-shape="pointer"]') as HTMLElement | null;
      const textSvg = curEl.querySelector('[data-cursor-shape="text"]') as HTMLElement | null;
      const isPointer = clean === "pointer" || clean === "grab" || clean === "grabbing";
      const isText = clean === "text" || clean === "vertical-text";
      if (arrowSvg) arrowSvg.style.display = !isPointer && !isText ? "block" : "none";
      if (pointerSvg) pointerSvg.style.display = isPointer ? "block" : "none";
      if (textSvg) textSvg.style.display = isText ? "block" : "none";
    }
  };

  const lastTouchHandledAtRef = useRef<number>(0);
  const lastHoverMoveSentAtRef = useRef<number>(0);
  const lastTouchScrollSentAtRef = useRef<number>(0);
  const inertiaRafRef = useRef<number>(0);
  const activePointersRef = useRef<Map<number, { x: number; y: number }>>(new Map());
  const lastSingleTapRef = useRef<{ time: number; x: number; y: number }>({ time: 0, x: 0, y: 0 });
  const isTapDraggingRef = useRef<boolean>(false);

  const gestureRef = useRef<{
    type: "single" | "pinch";
    nativeDrag?: boolean;
    startX: number;
    startY: number;
    lastX: number;
    lastY: number;
    lastTime: number;
    velDx: number;
    velDy: number;
    velStartTime: number;
    peakVx: number;
    peakVy: number;
    peakAt: number;
    vx: number;
    vy: number;
    startCursorX: number;
    startCursorY: number;
    startDist: number;
    startScale: number;
    startPanX: number;
    startPanY: number;
    startCenterX: number;
    startCenterY: number;
    moved: boolean;
    twoFingerMode?: "undecided" | "scroll" | "pinch";
    startedAt?: number;
    isDragSelect?: boolean;
  } | null>(null);

  const currentBlobUrlRef = useRef<string>("");
  const wsConnectedRef = useRef<boolean>(false);
  const wsRef = useRef<WebSocket | null>(null);
  const latestViewportRef = useRef<{ w: number; h: number; isMobile: boolean }>({ w: viewportWidth, h: viewportHeight, isMobile: isMobileDevice });
  latestViewportRef.current = { w: viewportWidth, h: viewportHeight, isMobile: isMobileDevice };

  // Direct DOM updater for zoom + virtual keyboard pan offset (0ms 60Hz/120Hz local GPU smoothness!)
  const applyZoomTransformDom = () => {
    const el = zoomWrapperRef.current;
    if (!el) return;
    const s = zoomScaleRef.current;
    const p = zoomPanRef.current;
    const kbY = keyboardPanOffsetYRef.current;
    const totalY = p.y + kbY;
    if (Math.abs(s - 1) > 0.005 || Math.abs(p.x) > 0.5 || Math.abs(totalY) > 0.5) {
      el.style.transform = `translate3d(${p.x.toFixed(1)}px, ${totalY.toFixed(1)}px, 0) scale(${s.toFixed(3)})`;
    } else {
      el.style.transform = "none";
    }
  };

  const recomputeVirtualKeyboardPanDom = () => {
    const ed = remoteEditableFocusRef.current;
    const boxRect = viewportBoxRef.current?.getBoundingClientRect();
    const boxH = boxRect?.height || viewportHeight || 600;
    if ((isVirtualKeyboardOpen || virtualKeyboardHeight > 80) && ed.editable && ed.bottomRatio > 0.44) {
      const targetRatio = 0.36;
      const neededLift = Math.max(0, (ed.bottomRatio - targetRatio) * boxH);
      const maxLift = Math.max(60, Math.min(boxH * 0.46, virtualKeyboardHeight > 0 ? virtualKeyboardHeight * 0.85 : boxH * 0.42));
      keyboardPanOffsetYRef.current = -Math.min(maxLift, neededLift);
    } else {
      keyboardPanOffsetYRef.current = 0;
    }
    applyZoomTransformDom();
  };

  useEffect(() => {
    recomputeVirtualKeyboardPanDom();
  }, [isVirtualKeyboardOpen, virtualKeyboardHeight]);

  const applyPredictiveScrollOffset = (_dx: number, _dy: number) => {
    // Keep canvas rock-steady at (0, 0) without synthetic CSS translation so scroll frames never rubber-band or show empty borders
  };

  const getRenderedImageBox = () => {
    const activeSurface =
      usingCanvasGpuRef.current && canvasRef.current
        ? canvasRef.current
        : imgRef.current;
    if (!activeSurface) return null;
    const rect = activeSurface.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return null;

    const natW = naturalDimsRef.current.w || imgRef.current?.naturalWidth || rect.width;
    const natH = naturalDimsRef.current.h || imgRef.current?.naturalHeight || rect.height;
    const imgAspect = natW / natH;
    const boxAspect = rect.width / rect.height;

    let renderW = rect.width;
    let renderH = rect.height;
    let offsetX = 0;
    let offsetY = 0;

    // When interactive (or aspect ratios match closely), canvas/img uses object-fill so the stream fills 100% of container width & height with zero letterboxing/pillarboxing
    if (!interactive && !isLandscapeRotated && Math.abs(imgAspect - boxAspect) > 0.04) {
      if (imgAspect > boxAspect) {
        renderW = rect.width;
        renderH = rect.width / imgAspect;
        offsetY = (rect.height - renderH) / 2;
      } else {
        renderH = rect.height;
        renderW = rect.height * imgAspect;
        offsetX = (rect.width - renderW) / 2;
      }
    }

    return { rect, renderW, renderH, offsetX, offsetY };
  };

  // Direct DOM updater for virtual mouse cursor (0 React re-renders during 120Hz touch/mouse move!)
  const applyCursorDom = () => {
    const curEl = cursorElRef.current;
    if (!curEl) return;
    const { x, y } = cursorNormRef.current;
    const box = getRenderedImageBox();
    if (box && box.rect.width > 0 && box.rect.height > 0) {
      const layoutW = isLandscapeRotated ? box.renderH : box.renderW;
      const layoutH = isLandscapeRotated ? box.renderW : box.renderH;
      curEl.style.left = `${(box.offsetX + x * layoutW).toFixed(1)}px`;
      curEl.style.top = `${(box.offsetY + y * layoutH).toFixed(1)}px`;
    } else {
      curEl.style.left = `${(x * 100).toFixed(2)}%`;
      curEl.style.top = `${(y * 100).toFixed(2)}%`;
    }
  };

  const canvasCtxRef = useRef<CanvasRenderingContext2D | null>(null);

  // Hardware GPU ImageBitmap -> <canvas> painter (0 Blob URL churn, 0 DOM layout recalc, VSync-locked 60fps!)
  const paintImageBitmapDom = (bitmap: ImageBitmap, backingBlob?: Blob) => {
    try {
      const cvs = canvasRef.current;
      if (!cvs) {
        bitmap.close();
        return;
      }
      if (cvs.width !== bitmap.width || cvs.height !== bitmap.height) {
        cvs.width = bitmap.width;
        cvs.height = bitmap.height;
        canvasCtxRef.current = null;
      }
      naturalDimsRef.current = { w: bitmap.width, h: bitmap.height };
      if (!canvasCtxRef.current) {
        canvasCtxRef.current = cvs.getContext("2d", { alpha: false, desynchronized: true });
        if (canvasCtxRef.current) {
          canvasCtxRef.current.imageSmoothingEnabled = true;
          canvasCtxRef.current.imageSmoothingQuality = "medium";
        }
      }
      const ctx = canvasCtxRef.current;
      if (ctx) {
        ctx.drawImage(bitmap, 0, 0);
      }

      usingCanvasGpuRef.current = true;
      cvs.style.display = "block";
      if (imgRef.current) {
        imgRef.current.style.display = "none";
      }
      if (!hasFrame) {
        setHasFrame(true);
      }
      if (mobileInputMode === "mouse") {
        applyCursorDom();
      }
      // Throttled snapshot cache for 0ms tab switch (creates a Blob URL at most once every 1200ms, zero GC pressure during active scrolling!)
      const nowMs = performance.now();
      if (backingBlob && frameCacheRef?.current && (!frameCacheRef.current[cacheKey] || frameCacheRef.current[cacheKey] === "__loading__" || nowMs - lastCacheSnapshotAtRef.current > 1200)) {
        lastCacheSnapshotAtRef.current = nowMs;
        const prevCached = frameCacheRef.current[cacheKey];
        const nextUrl = URL.createObjectURL(backingBlob);
        currentSrcRef.current = nextUrl;
        frameCacheRef.current[cacheKey] = nextUrl;
        if (prevCached && prevCached !== nextUrl && prevCached.startsWith("blob:")) {
          setTimeout(() => {
            const stillUsed = frameCacheRef?.current && Object.values(frameCacheRef.current).includes(prevCached);
            if (!stillUsed) {
              try { URL.revokeObjectURL(prevCached); } catch {}
            }
          }, 250);
        }
      }
    } finally {
      try { bitmap.close(); } catch {}
    }
  };

  // Direct DOM updater for video stream frame fallback (0 React re-renders + safe Blob URL lifecycle!)
  const commitStreamFrameDom = (nextUrl: string) => {
    const prevUrl = currentSrcRef.current;
    currentSrcRef.current = nextUrl;
    if (frameCacheRef?.current) {
      frameCacheRef.current[cacheKey] = nextUrl;
    }
    usingCanvasGpuRef.current = false;
    if (canvasRef.current) {
      canvasRef.current.style.display = "none";
    }
    if (imgRef.current) {
      imgRef.current.style.display = "block";
      imgRef.current.style.objectFit = interactive && !nextUrl.startsWith("data:image/svg+xml") ? "fill" : "contain";
      imgRef.current.style.backgroundColor = nextUrl.startsWith("data:image/svg+xml") ? "#ffffff" : "transparent";
      imgRef.current.src = nextUrl;
    }
    if (!hasFrame) {
      setHasFrame(true);
    }
    if (prevUrl && prevUrl !== nextUrl && prevUrl.startsWith("blob:")) {
      setTimeout(() => {
        // Only revoke if no tab in frameCacheRef is still referencing prevUrl
        const stillCached = frameCacheRef?.current && Object.values(frameCacheRef.current).includes(prevUrl);
        if (!stillCached && currentSrcRef.current !== prevUrl) {
          try { URL.revokeObjectURL(prevUrl); } catch {}
        }
      }, 250);
    }
  };

  useEffect(() => {
    const nextZoom = Math.max(1, externalZoomPercent / 100);
    zoomScaleRef.current = nextZoom;
    if (Math.abs(zoomScaleRef.current - 1) <= 0.01) {
      zoomPanRef.current = { x: 0, y: 0 };
    }
    applyZoomTransformDom();
    if (mobileInputMode === "mouse") {
      requestAnimationFrame(applyCursorDom);
    }
  }, [mobileInputMode, externalZoomPercent]);

  const pendingScrollWireRef = useRef<{ dx: number; dy: number; xRatio: number; yRatio: number; raf: number; lastFlushAt: number }>({
    dx: 0,
    dy: 0,
    xRatio: 0.5,
    yRatio: 0.5,
    raf: 0,
    lastFlushAt: 0,
  });

  const sendRealtimeInput = async (payload: BrowserInputPayload) => {
    const sock = wsRef.current;
    if (sock && sock.readyState === WebSocket.OPEN) {
      try {
        sock.send(JSON.stringify(payload));
        return;
      } catch {}
    }
    await dispatchAgentBrowserInput(agentId, payload);
  };

  const enqueueOrderedInput = (task: () => Promise<void>) => {
    inputQueueChainRef.current = inputQueueChainRef.current
      .then(task)
      .catch(() => {});
  };

  const flushImeProxyDiffImmediate = (el?: HTMLTextAreaElement | null) => {
    if (imeDebounceTimerRef.current) {
      clearTimeout(imeDebounceTimerRef.current);
      imeDebounceTimerRef.current = null;
    }
    const targetEl = el || imeProxyRef.current;
    if (!targetEl) return;
    const prevNFC = imeCommittedValRef.current.normalize("NFC");
    const nextNFC = targetEl.value.normalize("NFC");
    if (prevNFC === nextNFC) {
      imeCommittedValRef.current = targetEl.value;
      return;
    }
    const prevChars = Array.from(prevNFC);
    const nextChars = Array.from(nextNFC);
    let prefix = 0;
    while (prefix < prevChars.length && prefix < nextChars.length && prevChars[prefix] === nextChars[prefix]) {
      prefix++;
    }
    const backspaces = prevChars.length - prefix;
    const inserted = nextChars.slice(prefix).join("").replace(/\u200B/g, "");
    imeCommittedValRef.current = targetEl.value;
    if (!imeComposingRef.current && (targetEl.value.length < 8 || targetEl.value.length > 160 || targetEl.value.endsWith(" ") || targetEl.value.endsWith("\n"))) {
      resetImeProxyBuffer();
    }
    if (backspaces > 0 || inserted.length > 0) {
      const payload: BrowserInputPayload = {
        action: "ime_commit",
        backspaces,
        text: inserted,
        pageId,
      };
      const sock = wsRef.current;
      if (sock && sock.readyState === WebSocket.OPEN) {
        try {
          sock.send(JSON.stringify(payload));
          return;
        } catch {}
      }
      enqueueOrderedInput(async () => {
        await sendRealtimeInput(payload);
      });
    }
  };

  const flushImeProxyDiff = (el: HTMLTextAreaElement, immediate = false) => {
    if (immediate) {
      flushImeProxyDiffImmediate(el);
      return;
    }
    if (imeDebounceTimerRef.current) {
      clearTimeout(imeDebounceTimerRef.current);
    }
    //Adaptive coalescing: if this input deleted characters (Unikey / EVKey Backspace before diacritic replacement), wait 12ms to merge the replacement; otherwise flush in 4ms for instant 0-lag typing!
    const isDeletionStep = el.value.length < imeCommittedValRef.current.length;
    imeDebounceTimerRef.current = setTimeout(() => {
      imeDebounceTimerRef.current = null;
      flushImeProxyDiffImmediate(el);
    }, isDeletionStep ? 12 : 4);
  };

  const queueCoalescedScrollInput = (xRatio: number, yRatio: number, deltaX: number, deltaY: number) => {
    const st = pendingScrollWireRef.current;
    st.dx += deltaX;
    st.dy += deltaY;
    st.xRatio = xRatio;
    st.yRatio = yRatio;
    const flush = () => {
      st.raf = 0;
      if (Math.hypot(st.dx, st.dy) < 0.05) return;
      const sendDx = Number(st.dx.toFixed(2));
      const sendDy = Number(st.dy.toFixed(2));
      st.dx -= sendDx;
      st.dy -= sendDy;
      st.lastFlushAt = performance.now();
      if (Math.hypot(sendDx, sendDy) < 0.05) return;
      void sendRealtimeInput({
        action: "scroll",
        xRatio: st.xRatio,
        yRatio: st.yRatio,
        deltaX: sendDx,
        deltaY: sendDy,
        pageId,
      });
    };
    const now = performance.now();
    if (now - st.lastFlushAt >= 8 && !st.raf) {
      flush();
    } else if (!st.raf) {
      st.raf = requestAnimationFrame(flush);
    }
  };

  // 0. Instant 0ms Frame Restore on Tab/Agent Switch from in-memory tab cache (resets stale previous-agent canvas when uncached)
  useLayoutEffect(() => {
    const cached = frameCacheRef?.current?.[cacheKey];
    if (cached && cached !== "__loading__") {
      currentSrcRef.current = cached;
      usingCanvasGpuRef.current = false;
      if (canvasRef.current) {
        canvasRef.current.style.display = "none";
      }
      if (imgRef.current) {
        imgRef.current.style.display = "block";
        imgRef.current.style.objectFit = interactive && !cached.startsWith("data:image/svg+xml") ? "fill" : "contain";
        imgRef.current.style.backgroundColor = cached.startsWith("data:image/svg+xml") ? "#ffffff" : "transparent";
        imgRef.current.src = cached;
      }
      setHasFrame(true);
    } else {
      currentSrcRef.current = "";
      usingCanvasGpuRef.current = false;
      if (canvasRef.current) {
        canvasRef.current.style.display = "none";
      }
      if (imgRef.current) {
        imgRef.current.style.display = "none";
        imgRef.current.removeAttribute("src");
      }
      setHasFrame(false);
    }
  }, [cacheKey]);

  // The stream socket outlives tab changes, so frame painters are read through refs (fresh cacheKey/hasFrame per tab).
  const streamPageIdRef = useRef(pageId);
  streamPageIdRef.current = pageId;
  const requestTabSwitchRef = useRef<((nextPageId: string) => boolean) | null>(null);
  const [streamNonce, setStreamNonce] = useState(0);
  const paintImageBitmapDomRef = useRef(paintImageBitmapDom);
  paintImageBitmapDomRef.current = paintImageBitmapDom;
  const commitStreamFrameDomRef = useRef(commitStreamFrameDom);
  commitStreamFrameDomRef.current = commitStreamFrameDom;

  // 1. Persistent 30fps Full HD WebSocket Screencast with Zero-Re-Render DOM Swap & Adaptive Network Quality
  useEffect(() => {
    const initialPageId = streamPageIdRef.current;
    if (!enabled || !liveWs || typeof WebSocket === "undefined" || (initialPageId && initialPageId.startsWith("optimistic-"))) return;
    let alive = true;
    // Tab switches reuse this socket: frames are dropped from switch_tab until the server acks the new tab.
    let tabGen = 0;
    let switchPending: string | null = null;
    let switchTimer: ReturnType<typeof setTimeout> | null = null;
    let ws: WebSocket | null = null;
    let rafId = 0;
    let pendingDataUrl: string | null = null;
    let pendingBlob: Blob | null = null;
    let lastPaintedAt = 0;
    let currentAbrQuality = detectAdaptiveNetworkQuality();
    let lastQualitySentAt = 0;
    let ewmaKbps = 2500;
    let lastFrameAt = performance.now();
    const supportsGpuBitmap = typeof window !== "undefined" && typeof window.createImageBitmap === "function";
    wsConnectedRef.current = false;

    let isDecodingFrame = false;
    const flushPendingFrame = () => {
      rafId = 0;
      if (!alive || (!pendingBlob && !pendingDataUrl) || isDecodingFrame) return;
      if (pendingBlob && supportsGpuBitmap) {
        const blobToDecode = pendingBlob;
        const decodeGen = tabGen;
        pendingBlob = null;
        isDecodingFrame = true;
        window.createImageBitmap(blobToDecode)
          .then((bitmap) => {
            isDecodingFrame = false;
            if (!alive || decodeGen !== tabGen) {
              try { bitmap.close(); } catch {}
              if (alive && (pendingBlob || pendingDataUrl)) flushPendingFrame();
              return;
            }
            lastPaintedAt = performance.now();
            paintImageBitmapDomRef.current(bitmap, blobToDecode);
            if (pendingBlob || pendingDataUrl) {
              flushPendingFrame();
            }
          })
          .catch(() => {
            isDecodingFrame = false;
            if (!alive) return;
            if (decodeGen !== tabGen) return;
            const fallbackUrl = URL.createObjectURL(blobToDecode);
            lastPaintedAt = performance.now();
            commitStreamFrameDomRef.current(fallbackUrl);
            if ((pendingBlob || pendingDataUrl) && !rafId) {
              rafId = requestAnimationFrame(flushPendingFrame);
            }
          });
        return;
      }
      if (true) {

        const nextUrl = pendingDataUrl || (pendingBlob ? URL.createObjectURL(pendingBlob) : "");
        pendingDataUrl = null;
        pendingBlob = null;
        if (!nextUrl) return;
        isDecodingFrame = true;

        const preImg = new Image();
        preImg.decoding = "async";
        preImg.src = nextUrl;
        const decodeGen = tabGen;
        const finishDecode = () => {
          isDecodingFrame = false;
          if (!alive) return;
          if (decodeGen !== tabGen) {
            if (nextUrl.startsWith("blob:")) {
              try { URL.revokeObjectURL(nextUrl); } catch {}
            }
            return;
          }
          lastPaintedAt = performance.now();
          commitStreamFrameDomRef.current(nextUrl);
          if ((pendingBlob || pendingDataUrl) && !rafId) {
            rafId = requestAnimationFrame(flushPendingFrame);
          }
        };
        if (typeof preImg.decode === "function") {
          preImg.decode().then(finishDecode).catch(finishDecode);
        } else {
          finishDecode();
        }
      } else {
        rafId = requestAnimationFrame(flushPendingFrame);
      }
    };

    const onNetChange = () => {
      if (!alive || !ws || ws.readyState !== WebSocket.OPEN) return;
      const targetQ = detectAdaptiveNetworkQuality();
      if (Math.abs(targetQ - currentAbrQuality) >= 6) {
        currentAbrQuality = targetQ;
        try {
          ws.send(JSON.stringify({ action: "quality", width: targetQ, pageId: streamPageIdRef.current }));
        } catch {}
      }
    };

    const conn = typeof navigator !== "undefined" ? (navigator as any).connection : null;
    try { conn?.addEventListener?.("change", onNetChange); } catch {}

    let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    let reconnectAttempt = 0;

    const connectWs = async () => {
      reconnectTimer = null;
      if (!alive) return;
      // The stream authenticates via ?access_token=; renew it first so reconnects never loop on an expired token (401).
      await ensureFreshAccessToken().catch(() => null);
      if (!alive) return;
      try {
        const { w: initW, h: initH, isMobile: initMob } = latestViewportRef.current;
        const wantedPageId = streamPageIdRef.current;
        // An optimistic tab has no Chromium target yet: open on the default tab and hold frames until the real id arrives.
        const connPageId = wantedPageId && !wantedPageId.startsWith("optimistic-") ? wantedPageId : undefined;
        tabGen += 1;
        switchPending = connPageId === wantedPageId ? null : (wantedPageId ?? null);
        if (switchTimer) { clearTimeout(switchTimer); switchTimer = null; }
        ws = new WebSocket(agentBrowserStreamWsUrl(agentId, 1920, connPageId, initW, initH, initMob));
        ws.binaryType = "blob";
        wsRef.current = ws;
        ws.onopen = () => {
          if (!alive) return;
          reconnectAttempt = 0;
          wsConnectedRef.current = true;
          lastFrameAt = performance.now();
          const curVp = latestViewportRef.current;
          if (curVp.w >= 320 && curVp.h >= 240) {
            const rw = Math.round(curVp.w);
            const rh = Math.round(curVp.h);
            lastSentViewportRef.current = { agentId, pageId: connPageId, w: rw, h: rh, isMobile: curVp.isMobile, refreshSignal, confirmed: true };
            try {
              ws?.send(
                JSON.stringify({
                  action: "resize",
                  width: rw,
                  height: rh,
                  pageId: connPageId,
                  isMobile: curVp.isMobile,
                  deviceType: curVp.isMobile ? "phone" : "desktop",
                })
              );
            } catch {}
          }
        };
      ws.onmessage = (ev) => {
        if (!alive) return;
        if (switchPending && typeof ev.data !== "string") return;
        try {
          let nextFrameUrl = "";
          let nextFrameBlob: Blob | null = null;
          let frameBytes = 0;

          if (ev.data instanceof Blob) {
            frameBytes = ev.data.size;
            if (frameBytes <= 0) return;
            if (supportsGpuBitmap) {
              nextFrameBlob = ev.data;
            } else {
              nextFrameUrl = URL.createObjectURL(ev.data);
            }
          } else if (ev.data instanceof ArrayBuffer) {
            frameBytes = ev.data.byteLength;
            if (frameBytes <= 0) return;
            const b = new Blob([ev.data], { type: "image/jpeg" });
            if (supportsGpuBitmap) {
              nextFrameBlob = b;
            } else {
              nextFrameUrl = URL.createObjectURL(b);
            }
          } else if (typeof ev.data === "string") {
            const msg = JSON.parse(ev.data);
            if (msg?.method === "Page.tabSwitched" && msg?.params) {
              const ackId = typeof msg.params.pageId === "string" ? msg.params.pageId : "";
              if (ackId && ackId === switchPending) {
                if (switchTimer) { clearTimeout(switchTimer); switchTimer = null; }
                if (msg.params.ok === false) {
                  // Tab is not (yet) known to the server: a fresh connection opens it directly.
                  try { ws?.close(); } catch {}
                } else {
                  switchPending = null;
                }
              }
              return;
            }
            if (switchPending && msg?.method !== "Page.popupOpened" && msg?.method !== "Page.clipboardContent") return;
            if (msg?.method === "Page.loadingState" && msg?.params) {
              onPageLoadingStateRef.current?.({
                loading: Boolean(msg.params.loading),
                url: typeof msg.params.url === "string" ? msg.params.url : "",
                title: typeof msg.params.title === "string" ? msg.params.title : "",
              });
              return;
            }
            if (msg?.method === "Page.popupOpened" && msg?.params) {
              onPopupOpenedRef.current?.({
                openerId: typeof msg.params.openerId === "string" ? msg.params.openerId : "",
                url: typeof msg.params.url === "string" ? msg.params.url : "",
              });
              return;
            }
            if (msg?.method === "Page.cursorChanged" && typeof msg?.params?.cursor === "string") {
              applyRemoteCursorStyleDom(msg.params.cursor);
              return;
            }
            if (msg?.method === "Page.clipboardContent" && typeof msg?.params?.text === "string" && msg.params.text) {
              try {
                if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
                  void navigator.clipboard.writeText(msg.params.text);
                }
              } catch {}
              return;
            }
            if (msg?.method === "Page.inputFocusChanged" && msg?.params) {
              const isEd = Boolean(msg.params.editable);
              const inType = typeof msg.params.inputType === "string" ? msg.params.inputType : "text";
              const yR = Number(msg.params.yRatio) || 0.5;
              const bR = Number(msg.params.bottomRatio) || yR;
              remoteEditableFocusRef.current = { editable: isEd, inputType: inType, yRatio: yR, bottomRatio: bR };
              const isCoarseClient =
                isMobileDevice ||
                (typeof window !== "undefined" &&
                  (window.innerWidth < 768 ||
                    (typeof window.matchMedia === "function" && window.matchMedia("(pointer: coarse)").matches)));
              if (isEd) {
                lastRemoteTextFocusAtRef.current = Date.now();
                const proxyEl = imeProxyRef.current;
                if (proxyEl) {
                  const nextInputMode =
                    inType === "email"
                      ? "email"
                      : inType === "tel"
                      ? "tel"
                      : inType === "url"
                      ? "url"
                      : inType === "number"
                      ? "decimal"
                      : inType === "search"
                      ? "search"
                      : "text";
                  proxyEl.setAttribute("inputmode", nextInputMode);
                }
                focusImeProxy();
              } else {
                lastRemoteTextFocusAtRef.current = 0;
                if (isCoarseClient && imeProxyRef.current && document.activeElement === imeProxyRef.current) {
                  try { imeProxyRef.current.blur(); } catch {}
                }
              }
              recomputeVirtualKeyboardPanDom();
              return;
            }
            if (msg?.method === "Page.scrollMetrics" && msg?.params) {
              const st = Number(msg.params.scrollTop) || 0;
              const sh = Number(msg.params.scrollHeight) || 0;
              const ch = Number(msg.params.clientHeight) || 0;
              if (!scrollbarDragRef.current.active) {
                applyScrollMetricsDom(st, sh, ch);
              }
              return;
            }
            const b64 = msg?.params?.data;
            if (typeof b64 === "string" && b64.length > 0) {
              frameBytes = b64.length * 0.75;
              nextFrameUrl = `data:image/jpeg;base64,${b64}`;
            }
          }

          if (nextFrameBlob || nextFrameUrl) {
            wsConnectedRef.current = true;
            setFailures(0);

            const now = performance.now();
            const dtMs = Math.max(8, now - lastFrameAt);
            lastFrameAt = now;
            if (dtMs < 400 && frameBytes > 0) {
              const instantKbps = (frameBytes * 8) / dtMs;
              ewmaKbps = ewmaKbps * 0.75 + instantKbps * 0.25;
              if (now - lastQualitySentAt > 420 && ws && ws.readyState === WebSocket.OPEN) {
                // Smoothly map ewmaKbps (500..3000 kbps) into JPEG quality (55..75) for 60fps active frame pumping over 4G mobile links
                const desiredQ = Math.max(55, Math.min(75, Math.round(55 + ((ewmaKbps - 500) / 2500) * 20)));
                if (Math.abs(desiredQ - currentAbrQuality) >= 3) {
                  currentAbrQuality = desiredQ;
                  lastQualitySentAt = now;
                  try {
                    ws.send(JSON.stringify({ action: "quality", width: desiredQ, pageId: streamPageIdRef.current }));
                  } catch {}
                }
              }
            }

            if (nextFrameBlob) {
              pendingBlob = nextFrameBlob;
            } else {
              if (pendingDataUrl && pendingDataUrl.startsWith("blob:")) {
                try { URL.revokeObjectURL(pendingDataUrl); } catch {}
              }
              pendingDataUrl = nextFrameUrl;
            }
            if (!isDecodingFrame && nextFrameBlob && supportsGpuBitmap) {
              flushPendingFrame();
            } else if (!rafId) {
              rafId = requestAnimationFrame(flushPendingFrame);
            }
          }
        } catch {}
      };
        ws.onclose = () => {
          wsConnectedRef.current = false;
          if (wsRef.current === ws) wsRef.current = null;
          if (alive) {
            const delayMs = Math.min(3500, 450 + reconnectAttempt * 500);
            reconnectAttempt += 1;
            reconnectTimer = setTimeout(connectWs, delayMs);
          }
        };
        ws.onerror = () => { wsConnectedRef.current = false; };
      } catch {}
    };

    const beginTabSwitch = (nextPageId: string): boolean => {
      if (!alive) return false;
      if (!ws || ws.readyState !== WebSocket.OPEN) {
        // A socket that is still connecting (or about to reconnect) opens on the latest tab by itself.
        return ws?.readyState === WebSocket.CONNECTING || reconnectTimer !== null;
      }
      tabGen += 1;
      pendingBlob = null;
      if (pendingDataUrl && pendingDataUrl.startsWith("blob:")) {
        try { URL.revokeObjectURL(pendingDataUrl); } catch {}
      }
      pendingDataUrl = null;
      switchPending = nextPageId;
      if (switchTimer) { clearTimeout(switchTimer); switchTimer = null; }
      if (nextPageId.startsWith("optimistic-")) return true;
      const vp = latestViewportRef.current;
      try {
        ws.send(JSON.stringify({
          action: "switch_tab",
          pageId: nextPageId,
          width: Math.round(vp.w),
          height: Math.round(vp.h),
          isMobile: vp.isMobile,
          deviceType: vp.isMobile ? "phone" : "desktop",
        }));
      } catch {
        return false;
      }
      const sock = ws;
      switchTimer = setTimeout(() => {
        switchTimer = null;
        if (alive && switchPending === nextPageId) {
          try { sock.close(); } catch {}
        }
      }, 4000);
      return true;
    };
    requestTabSwitchRef.current = beginTabSwitch;

    void connectWs();

    return () => {
      alive = false;
      wsConnectedRef.current = false;
      requestTabSwitchRef.current = null;
      if (switchTimer) clearTimeout(switchTimer);
      if (reconnectTimer) clearTimeout(reconnectTimer);
      if (rafId) cancelAnimationFrame(rafId);
      try { conn?.removeEventListener?.("change", onNetChange); } catch {}
      if (wsRef.current === ws) wsRef.current = null;
      if (ws) {
        try { ws.close(); } catch {}
      }
    };
  }, [enabled, agentId, liveWs, streamNonce]);

  // Tab change: move the open stream onto the new tab (no new handshake/auth round trip); reconnect only as a fallback.
  const switchedPageIdRef = useRef(pageId);
  useEffect(() => {
    if (switchedPageIdRef.current === pageId) return;
    switchedPageIdRef.current = pageId;
    if (!enabled || !liveWs) return;
    if (!pageId || !requestTabSwitchRef.current?.(pageId)) {
      setStreamNonce((n) => n + 1);
    }
  }, [pageId, enabled, liveWs]);

  const lastSentViewportRef = useRef<{ agentId?: string; pageId?: string; w: number; h: number; isMobile?: boolean; refreshSignal?: number; confirmed?: boolean }>({ agentId: undefined, pageId: undefined, w: 0, h: 0, isMobile: undefined, refreshSignal: 0, confirmed: false });

  // 2. Smooth Debounced Viewport Synchronization (Frozen while Phone Virtual Keyboard is open or during active splitter drag to prevent CDP resize thrash; flushes smoothly once settled)
  useEffect(() => {
    if (!enabled || !liveWs || viewportWidth < 320 || viewportHeight < 240 || (pageId && pageId.startsWith("optimistic-"))) return;
    if (isVirtualKeyboardOpen) return;
    if (isResizing) return;
    const w = Math.round(viewportWidth);
    const h = Math.round(viewportHeight);
    const prev = lastSentViewportRef.current;
    const forceResync = prev.refreshSignal !== refreshSignal || prev.agentId !== agentId;
    if (!forceResync && prev.confirmed && prev.agentId === agentId && prev.pageId === pageId && prev.isMobile === isMobileDevice && Math.abs(prev.w - w) <= 2 && Math.abs(prev.h - h) <= 2) {
      return;
    }
    const timer = setTimeout(() => {
      const modeFlipped = prev.agentId === agentId && prev.pageId === pageId && prev.isMobile !== undefined && prev.isMobile !== isMobileDevice;
      lastSentViewportRef.current = { agentId, pageId, w, h, isMobile: isMobileDevice, refreshSignal, confirmed: true };
      const deviceType = isMobileDevice ? "phone" : "desktop";
      const sock = wsRef.current;
      if (sock && sock.readyState === WebSocket.OPEN) {
        try {
          sock.send(JSON.stringify({ action: "resize", width: w, height: h, pageId, isMobile: isMobileDevice, deviceType, reloadOnModeChange: modeFlipped }));
          return;
        } catch {}
      }
      void dispatchAgentBrowserInput(agentId, { action: "resize", width: w, height: h, pageId, isMobile: isMobileDevice, deviceType, reloadOnModeChange: modeFlipped });
    }, forceResync ? 16 : 64);
    return () => clearTimeout(timer);
  }, [enabled, agentId, pageId, viewportWidth, viewportHeight, isMobileDevice, isVirtualKeyboardOpen, isResizing, refreshSignal]);

  // 3. Fallback HTTP Frame Poll ONLY when liveWs is false or if WebSocket fails to connect within 1400ms
  useEffect(() => {
    if (!enabled || (pageId && pageId.startsWith("optimistic-"))) return;
    let alive = true;
    let fails = 0;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const ctrl = new AbortController();

    const fetchFallbackFrame = async () => {
      if (document.hidden || wsConnectedRef.current || (liveWs && (hasFrame || viewportWidth >= 320))) return;
      try {
        const next = await fetchAgentBrowserFrame(agentBrowserImageUrl(agentId, Date.now(), pageId), ctrl.signal);
        if (!alive || wsConnectedRef.current) {
          URL.revokeObjectURL(next);
          return;
        }
        if (currentBlobUrlRef.current) {
          URL.revokeObjectURL(currentBlobUrlRef.current);
        }
        currentBlobUrlRef.current = next;
        fails = 0;
        commitStreamFrameDom(next);
        setFailures(0);
      } catch {
        if (!alive) return;
        fails += 1;
        setFailures(fails);
      }
    };

    const loop = async () => {
      await fetchFallbackFrame();
      if (alive) {
        timer = setTimeout(loop, fails > 2 ? 15000 : (wsConnectedRef.current ? 5000 : intervalMs));
      }
    };

    if (!liveWs) {
      void fetchFallbackFrame();
      timer = setTimeout(loop, intervalMs);
    } else {
      timer = setTimeout(loop, 1400);
    }

    return () => {
      alive = false;
      ctrl.abort();
      if (timer) clearTimeout(timer);
    };
  }, [enabled, agentId, pageId, intervalMs, liveWs, refreshNonce, refreshSignal]);

  useEffect(() => {
    return () => {
      if (inertiaRafRef.current) cancelAnimationFrame(inertiaRafRef.current);
      if (currentBlobUrlRef.current) {
        URL.revokeObjectURL(currentBlobUrlRef.current);
        currentBlobUrlRef.current = "";
      }
    };
  }, []);

  const computeNormalizedCoords = (clientX: number, clientY: number): { xRatio: number; yRatio: number } | null => {
    const box = getRenderedImageBox();
    if (!box) return null;
    const { rect, renderW, renderH, offsetX, offsetY } = box;

    if (isLandscapeRotated) {
      return {
        xRatio: Math.max(0, Math.min(1, (clientY - rect.top) / rect.height)),
        yRatio: Math.max(0, Math.min(1, (rect.right - clientX) / rect.width)),
      };
    }

    const xInImg = clientX - rect.left - offsetX;
    const yInImg = clientY - rect.top - offsetY;

    return {
      xRatio: Math.max(0, Math.min(1, xInImg / Math.max(1, renderW))),
      yRatio: Math.max(0, Math.min(1, yInImg / Math.max(1, renderH))),
    };
  };

  // Stop any ongoing kinetic inertia scroll when user touches screen
  const stopInertiaScroll = () => {
    if (inertiaRafRef.current) {
      cancelAnimationFrame(inertiaRafRef.current);
      inertiaRafRef.current = 0;
    }
  };

  // Start smooth iOS/Android native-grade kinetic momentum scrolling after finger release in Touch Mode / 2-Finger Scroll
  const startInertiaScroll = (initialVx: number, initialVy: number, anchorXRatio: number, anchorYRatio: number) => {
    stopInertiaScroll();
    // Boost initial flick velocity (~1.38x) and cap to prevent runaway jumps
    let vx = Math.max(-4.8, Math.min(4.8, initialVx * 1.38));
    let vy = Math.max(-4.8, Math.min(4.8, initialVy * 1.38));
    let lastTs = performance.now();

    const stepInertia = () => {
      const now = performance.now();
      const dt = Math.min(32, Math.max(8, now - lastTs));
      lastTs = now;

      // Native mobile Safari/Chrome deceleration curve (0.968 per 16.67ms frame -> ~900-1200ms smooth glide)
      const decay = Math.pow(0.968, dt / 16.67);
      vx *= decay;
      vy *= decay;

      const stepDx = vx * dt;
      const stepDy = vy * dt;

      if (Math.hypot(stepDx, stepDy) < 0.16) {
        inertiaRafRef.current = 0;
        return;
      }

      const boxRect = viewportBoxRef.current?.getBoundingClientRect();
      const dispW = Math.max(320, isLandscapeRotated ? (boxRect?.height || 640) : (boxRect?.width || 390));
      const logicalW = Math.max(dispW, latestViewportRef.current.w || 390);
      const speedPxMs = Math.hypot(vx, vy);
      const speedBoost = Math.min(1.32, 1 + Math.max(0, speedPxMs - 0.55) * 0.16);
      const touchScale = Math.max(2.1, Math.min(3.1, (logicalW / dispW) * 1.48)) * speedBoost;
      const scrollDeltaX = isLandscapeRotated ? -stepDy * touchScale : -stepDx * touchScale;
      const scrollDeltaY = isLandscapeRotated ? stepDx * touchScale : -stepDy * touchScale;
      const { scrollTop, scrollHeight, clientHeight } = scrollMetricsRef.current;
      if (scrollHeight > clientHeight && Math.abs(scrollDeltaY) > 0.05) {
        const nextTop = Math.max(0, Math.min(scrollHeight - clientHeight, scrollTop + scrollDeltaY));
        applyScrollMetricsDom(nextTop, scrollHeight, clientHeight);
      }
      applyPredictiveScrollOffset(scrollDeltaX, scrollDeltaY);
      queueCoalescedScrollInput(anchorXRatio, anchorYRatio, scrollDeltaX, scrollDeltaY);

      inertiaRafRef.current = requestAnimationFrame(stepInertia);
    };

    inertiaRafRef.current = requestAnimationFrame(stepInertia);
  };

  const beginSingleGesture = (clientX: number, clientY: number, pointerType = "touch") => {
    stopInertiaScroll();
    const startCoords = computeNormalizedCoords(clientX, clientY);
    const isScrollbarZone = Boolean(startCoords && startCoords.xRatio >= 0.965);
    const useNativeMouseDrag = isScrollbarZone || (pointerType === "mouse" && mobileInputMode === "touch");

    // Enhancement 3: Tap-and-drag preparation for text selection & dragging in Phone Mouse Mode
    const isDragSelect = false;
    const now = performance.now();

    gestureRef.current = {
      type: "single",
      nativeDrag: useNativeMouseDrag,
      isDragSelect,
      startX: clientX,
      startY: clientY,
      lastX: clientX,
      lastY: clientY,
      lastTime: now,
      velDx: 0,
      velDy: 0,
      velStartTime: now,
      peakVx: 0,
      peakVy: 0,
      peakAt: now,
      vx: 0,
      vy: 0,
      startCursorX: cursorNormRef.current.x,
      startCursorY: cursorNormRef.current.y,
      startDist: 0,
      startScale: zoomScaleRef.current,
      startPanX: zoomPanRef.current.x,
      startPanY: zoomPanRef.current.y,
      startCenterX: clientX,
      startCenterY: clientY,
      moved: false,
    };

    if (useNativeMouseDrag && startCoords) {
      void sendRealtimeInput({
        action: "mousedown",
        xRatio: startCoords.xRatio,
        yRatio: startCoords.yRatio,
        pageId,
      });
    }
  };

  const beginPinchGesture = (x1: number, y1: number, x2: number, y2: number) => {
    stopInertiaScroll();
    const dist = Math.max(10, Math.hypot(x1 - x2, y1 - y2));
    const cx = (x1 + x2) / 2;
    const cy = (y1 + y2) / 2;
    const now = performance.now();
    gestureRef.current = {
      type: "pinch",
      startX: cx,
      startY: cy,
      lastX: cx,
      lastY: cy,
      lastTime: now,
      velDx: 0,
      velDy: 0,
      velStartTime: now,
      peakVx: 0,
      peakVy: 0,
      peakAt: now,
      vx: 0,
      vy: 0,
      startCursorX: cursorNormRef.current.x,
      startCursorY: cursorNormRef.current.y,
      startDist: dist,
      startScale: zoomScaleRef.current,
      startPanX: zoomPanRef.current.x,
      startPanY: zoomPanRef.current.y,
      startCenterX: cx,
      startCenterY: cy,
      moved: false,
      twoFingerMode: mobileInputMode === "mouse" ? "undecided" : "pinch",
      startedAt: now,
    };
  };

  const movePinchGesture = (x1: number, y1: number, x2: number, y2: number) => {
    const g = gestureRef.current;
    if (!g || g.type !== "pinch") return;
    const dist = Math.hypot(x1 - x2, y1 - y2);
    const cx = (x1 + x2) / 2;
    const cy = (y1 + y2) / 2;
    const now = performance.now();

    // In Phone Mouse Mode: 2-touch swipe scrolls the web page like a trackpad!
    if (mobileInputMode === "mouse") {
      const centerMove = Math.hypot(cx - g.startX, cy - g.startY);
      const distChange = Math.abs(dist - g.startDist);
      const distRatio = dist / Math.max(10, g.startDist);

      if (g.twoFingerMode === "undecided") {
        if (distChange > 28 && Math.abs(distRatio - 1) > 0.16 && distChange > centerMove * 1.5) {
          g.twoFingerMode = "pinch";
        } else if (centerMove > 9) {
          // Tolerate finger jitter so a 2-finger tap still resolves to right click
          g.twoFingerMode = "scroll";
        } else {
          return;
        }
      }

      if (g.twoFingerMode === "scroll") {
        g.moved = true;
        const stepDx = cx - g.lastX;
        const stepDy = cy - g.lastY;
        g.lastX = cx;
        g.lastY = cy;
        g.lastTime = now;

        g.velDx += stepDx;
        g.velDy += stepDy;
        const velDt = now - g.velStartTime;
        if (velDt >= 10) {
          const instVx = g.velDx / velDt;
          const instVy = g.velDy / velDt;
          if (Math.hypot(g.velDx, g.velDy) > 0.8 || velDt > 38) {
            g.vx = g.vx * 0.35 + instVx * 0.65;
            g.vy = g.vy * 0.35 + instVy * 0.65;
            if (Math.hypot(g.vx, g.vy) >= Math.hypot(g.peakVx, g.peakVy) * 0.82 || now - g.peakAt > 65) {
              g.peakVx = g.vx;
              g.peakVy = g.vy;
              g.peakAt = now;
            }
          }
          g.velDx = 0;
          g.velDy = 0;
          g.velStartTime = now;
        }

        if (Math.hypot(stepDx, stepDy) > 0.2) {
          lastTouchScrollSentAtRef.current = now;

          // Enhancement 4: 2-Touch bidirectional smooth horizontal and vertical scrolling
          const boxRect = viewportBoxRef.current?.getBoundingClientRect();
          const dispW = Math.max(320, isLandscapeRotated ? (boxRect?.height || 640) : (boxRect?.width || 390));
          const logicalW = Math.max(dispW, latestViewportRef.current.w || 390);
          const speedPxMs = Math.hypot(g.vx, g.vy);
          const speedBoost = Math.min(1.42, 1 + Math.max(0, speedPxMs - 0.5) * 0.22);
          const touchScale = Math.max(2.05, Math.min(2.9, (logicalW / dispW) * 1.45)) * speedBoost;
          const scrollDeltaX = isLandscapeRotated ? -stepDy * touchScale : -stepDx * touchScale;
          const scrollDeltaY = isLandscapeRotated ? stepDx * touchScale : -stepDy * touchScale;

          const { scrollTop, scrollHeight, clientHeight } = scrollMetricsRef.current;
          if (scrollHeight > clientHeight) {
            const nextTop = Math.max(0, Math.min(scrollHeight - clientHeight, scrollTop + scrollDeltaY));
            applyScrollMetricsDom(nextTop, scrollHeight, clientHeight);
          }
          applyPredictiveScrollOffset(scrollDeltaX, scrollDeltaY);
          queueCoalescedScrollInput(cursorNormRef.current.x, cursorNormRef.current.y, scrollDeltaX, scrollDeltaY);
        }
        return;
      }
    }

    const totalDistChange = Math.abs(dist - g.startDist);
    const totalCenterDelta = Math.hypot(cx - g.startX, cy - g.startY);
    if (totalDistChange > 6 || totalCenterDelta > 6) {
      g.moved = true;
    }
    const nextScale = Math.max(1, Math.min(3.5, g.startScale * (dist / g.startDist)));
    zoomScaleRef.current = nextScale;
    if (nextScale > 1.02) {
      zoomPanRef.current = {
        x: g.startPanX + (cx - g.startCenterX),
        y: g.startPanY + (cy - g.startCenterY),
      };
    } else {
      zoomPanRef.current = { x: 0, y: 0 };
    }
    applyZoomTransformDom();
  };

  const moveSingleGesture = (clientX: number, clientY: number) => {
    const g = gestureRef.current;
    if (!g || g.type !== "single") return;
    const now = performance.now();
    const totalMove = Math.hypot(clientX - g.startX, clientY - g.startY);

    if (g.nativeDrag) {
      if (totalMove > 2) g.moved = true;
      if (now - lastTouchScrollSentAtRef.current >= 14) {
        lastTouchScrollSentAtRef.current = now;
        const coords = computeNormalizedCoords(clientX, clientY);
        if (coords) {
          void sendRealtimeInput({
            action: "mousemove_drag",
            xRatio: coords.xRatio,
            yRatio: coords.yRatio,
            pageId,
          });
        }
      }
      return;
    }

    if (mobileInputMode === "mouse") {
      // MODE 2: MOUSE (TRACKPAD) MODE — Direct DOM cursor update (0ms lag, 0 React re-renders!)
      if (totalMove > 4) {
        g.moved = true;
        // Engage tap-and-drag on first movement if second tap arrived within 320ms window!
        if (!g.isDragSelect && (now - lastSingleTapRef.current.time < 320) && (Math.hypot(g.startX - lastSingleTapRef.current.x, g.startY - lastSingleTapRef.current.y) < 36)) {
          g.isDragSelect = true;
          isTapDraggingRef.current = true;
          triggerHaptic(12);
          void sendRealtimeInput({
            action: "mousedown",
            xRatio: cursorNormRef.current.x,
            yRatio: cursorNormRef.current.y,
            pageId,
          });
        }
      }
      const rect = viewportBoxRef.current?.getBoundingClientRect();
      const w = Math.max(180, rect?.width || 360);
      const h = Math.max(180, rect?.height || 600);
      const sensitivity = 1.25;
      const dxNorm = ((clientX - g.startX) / w) * sensitivity;
      const dyNorm = ((clientY - g.startY) / h) * sensitivity;

      const nx = Math.max(0, Math.min(1, isLandscapeRotated ? g.startCursorX + dyNorm : g.startCursorX + dxNorm));
      const ny = Math.max(0, Math.min(1, isLandscapeRotated ? g.startCursorY - dxNorm : g.startCursorY + dyNorm));
      cursorNormRef.current = { x: nx, y: ny };
      applyCursorDom();

      const throttleMs = g.isDragSelect ? 16 : 24;
      if (now - lastHoverMoveSentAtRef.current > throttleMs) {
        lastHoverMoveSentAtRef.current = now;
        void sendRealtimeInput({
          action: g.isDragSelect ? "mousemove_drag" : "move",
          xRatio: nx,
          yRatio: ny,
          pageId,
        });
      }
    } else {
      // MODE 1: TOUCH MODE — Real-time 60Hz drag scroll + windowed velocity tracking for kinetic inertia!
      if (totalMove > 1.5) {
        if (totalMove > 5) {
          g.moved = true;
        }
        const stepDx = clientX - g.lastX;
        const stepDy = clientY - g.lastY;
        g.lastX = clientX;
        g.lastY = clientY;
        g.lastTime = now;

        g.velDx += stepDx;
        g.velDy += stepDy;
        const velDt = now - g.velStartTime;
        if (velDt >= 10) {
          const instVx = g.velDx / velDt;
          const instVy = g.velDy / velDt;
          // Ignore tiny pre-lift micro-movement so finger lift never zeroes out flick momentum
          if (Math.hypot(g.velDx, g.velDy) > 0.8 || velDt > 38) {
            g.vx = g.vx * 0.35 + instVx * 0.65;
            g.vy = g.vy * 0.35 + instVy * 0.65;
            if (Math.hypot(g.vx, g.vy) >= Math.hypot(g.peakVx, g.peakVy) * 0.82 || now - g.peakAt > 65) {
              g.peakVx = g.vx;
              g.peakVy = g.vy;
              g.peakAt = now;
            }
          }
          g.velDx = 0;
          g.velDy = 0;
          g.velStartTime = now;
        }

        if (Math.hypot(stepDx, stepDy) > 0.15) {
          lastTouchScrollSentAtRef.current = now;
          const coords = computeNormalizedCoords(g.startX, g.startY) || { xRatio: 0.5, yRatio: 0.5 };
          const boxRect = viewportBoxRef.current?.getBoundingClientRect();
          const dispW = Math.max(320, isLandscapeRotated ? (boxRect?.height || 640) : (boxRect?.width || 390));
          const logicalW = Math.max(dispW, latestViewportRef.current.w || 390);
          const speedPxMs = Math.hypot(g.vx, g.vy);
          const speedBoost = Math.min(1.45, 1 + Math.max(0, speedPxMs - 0.5) * 0.24);
          const touchScale = Math.max(2.1, Math.min(2.95, (logicalW / dispW) * 1.48)) * speedBoost;
          const scrollDeltaX = isLandscapeRotated ? -stepDy * touchScale : -stepDx * touchScale;
          const scrollDeltaY = isLandscapeRotated ? stepDx * touchScale : -stepDy * touchScale;
          // Optimistically update scrollbar thumb during touch scroll
          const { scrollTop, scrollHeight, clientHeight } = scrollMetricsRef.current;
          if (scrollHeight > clientHeight) {
            const nextTop = Math.max(0, Math.min(scrollHeight - clientHeight, scrollTop + scrollDeltaY));
            applyScrollMetricsDom(nextTop, scrollHeight, clientHeight);
          }
          applyPredictiveScrollOffset(scrollDeltaX, scrollDeltaY);
          queueCoalescedScrollInput(coords.xRatio, coords.yRatio, scrollDeltaX, scrollDeltaY);
        }
      }
    }
  };

  const endGesture = async (endClientX?: number, endClientY?: number) => {
    const g = gestureRef.current;
    gestureRef.current = null;
    if (!g) return;
    const now = performance.now();

    // Flush any remaining sub-10ms velocity sample if significant
    const remDt = Math.max(6, now - g.velStartTime);
    if (Math.hypot(g.velDx, g.velDy) > 1.8 && remDt < 45) {
      const instVx = g.velDx / remDt;
      const instVy = g.velDy / remDt;
      g.vx = g.vx * 0.35 + instVx * 0.65;
      g.vy = g.vy * 0.35 + instVy * 0.65;
    }
    const usePeak = (now - g.peakAt <= 75) && (Math.hypot(g.peakVx, g.peakVy) > Math.hypot(g.vx, g.vy));
    const launchVx = usePeak ? g.peakVx : g.vx;
    const launchVy = usePeak ? g.peakVy : g.vy;

    if (g.type === "pinch") {
      if (mobileInputMode === "mouse") {
        const tapDuration = now - (g.startedAt ?? now);
        if (!g.moved && g.twoFingerMode !== "pinch" && tapDuration < 450) {
          // 2-TOUCH TAP IN MOUSE MODE: Right click at virtual mouse pointer!
          triggerHaptic(15);
          const cur = cursorNormRef.current;
          if (cursorElRef.current?.animate) {
            cursorElRef.current.animate(
              [{ transform: "scale(1)" }, { transform: "scale(0.82)" }, { transform: "scale(1)" }],
              { duration: 160 }
            );
          }
          await sendRealtimeInput({
            action: "rightclick",
            xRatio: cur.x,
            yRatio: cur.y,
            pageId,
          });
          return;
        }
        if (g.twoFingerMode === "scroll" && (now - g.lastTime < 130) && Math.hypot(launchVx, launchVy) > 0.1) {
          // Launch smooth kinetic momentum scroll when user flicks 2 fingers!
          startInertiaScroll(launchVx, launchVy, cursorNormRef.current.x, cursorNormRef.current.y);
          return;
        }
      }
      return;
    }

    if (g.nativeDrag) {
      const coords = computeNormalizedCoords(endClientX ?? g.lastX, endClientY ?? g.lastY) ||
        computeNormalizedCoords(g.startX, g.startY) || { xRatio: 0.5, yRatio: 0.5 };
      await sendRealtimeInput({
        action: "mouseup",
        xRatio: coords.xRatio,
        yRatio: coords.yRatio,
        pageId,
      });
      return;
    }

    if (mobileInputMode === "mouse") {
      const cur = cursorNormRef.current;

      // If completing tap-and-drag, release mouse button (Enhancement 3)
      if (g.isDragSelect || isTapDraggingRef.current) {
        isTapDraggingRef.current = false;
        await sendRealtimeInput({
          action: "mouseup",
          xRatio: cur.x,
          yRatio: cur.y,
          pageId,
        });
        lastSingleTapRef.current = { time: 0, x: 0, y: 0 };
        return;
      }

      if (!g.moved) {
        // Enhancement 2: Double-tap detection -> dblclick action
        const prevTap = lastSingleTapRef.current;
        const timeSincePrev = now - prevTap.time;
        const distFromPrev = Math.hypot((endClientX ?? g.lastX) - prevTap.x, (endClientY ?? g.lastY) - prevTap.y);

        if (timeSincePrev < 280 && distFromPrev < 28) {
          // Double click triggered!
          triggerHaptic(18);
          if (cursorElRef.current?.animate) {
            cursorElRef.current.animate(
              [{ transform: "scale(1)" }, { transform: "scale(0.78)" }, { transform: "scale(1)" }],
              { duration: 150 }
            );
          }
          await sendRealtimeInput({
            action: "dblclick",
            xRatio: cur.x,
            yRatio: cur.y,
            pageId,
          });
          lastSingleTapRef.current = { time: 0, x: 0, y: 0 };
        } else {
          // Single click triggered!
          triggerHaptic(8);
          if (cursorElRef.current?.animate) {
            cursorElRef.current.animate(
              [{ transform: "scale(1)" }, { transform: "scale(0.88)" }, { transform: "scale(1)" }],
              { duration: 120 }
            );
          }
          focusImeProxy();
          await sendRealtimeInput({
            action: "click",
            xRatio: cur.x,
            yRatio: cur.y,
            pageId,
          });
          lastSingleTapRef.current = { time: now, x: endClientX ?? g.lastX, y: endClientY ?? g.lastY };
        }
      } else {
        await sendRealtimeInput({
          action: "move",
          xRatio: cur.x,
          yRatio: cur.y,
          pageId,
        });
      }
      return;
    }

    if (!g.moved) {
      const coords = computeNormalizedCoords(g.startX, g.startY);
      if (coords) {
        focusImeProxy();
        await sendRealtimeInput({
          action: "click",
          xRatio: coords.xRatio,
          yRatio: coords.yRatio,
          pageId,
        });
      }
    } else if ((now - g.lastTime < 130) && Math.hypot(launchVx, launchVy) > 0.08) {
      // Launch smooth kinetic momentum scroll when user flicks finger (skip if user held finger stationary before lifting)!
      const coords = computeNormalizedCoords(g.startX, g.startY) || { xRatio: 0.5, yRatio: 0.5 };
      startInertiaScroll(launchVx, launchVy, coords.xRatio, coords.yRatio);
    }
  };

  const handlersRef = useRef({ beginSingleGesture, beginPinchGesture, moveSingleGesture, movePinchGesture, endGesture, interactive });
  handlersRef.current = { beginSingleGesture, beginPinchGesture, moveSingleGesture, movePinchGesture, endGesture, interactive };

  useEffect(() => {
    const el = viewportBoxRef.current;
    if (!el) return;

    const onNativeTouchStart = (ev: TouchEvent) => {
      if (!handlersRef.current.interactive) return;
      ev.stopPropagation();
      lastTouchHandledAtRef.current = Date.now();
      if (ev.touches.length >= 2) {
        ev.preventDefault();
        const cur = gestureRef.current;
        if (cur?.type === "pinch") {
          // A finger re-landed mid-gesture: rebase the center/distance without resetting
          // moved/twoFingerMode, so a 2-finger swipe never ends as a stray right click.
          const x1 = ev.touches[0].clientX, y1 = ev.touches[0].clientY;
          const x2 = ev.touches[1].clientX, y2 = ev.touches[1].clientY;
          const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
          const shiftX = cx - cur.lastX, shiftY = cy - cur.lastY;
          cur.startX += shiftX;
          cur.startY += shiftY;
          cur.lastX = cx;
          cur.lastY = cy;
          cur.startDist = Math.max(10, Math.hypot(x1 - x2, y1 - y2));
          cur.velDx = 0;
          cur.velDy = 0;
          cur.velStartTime = performance.now();
          return;
        }
        handlersRef.current.beginPinchGesture(
          ev.touches[0].clientX,
          ev.touches[0].clientY,
          ev.touches[1].clientX,
          ev.touches[1].clientY
        );
      } else if (ev.touches.length === 1) {
        handlersRef.current.beginSingleGesture(ev.touches[0].clientX, ev.touches[0].clientY);
      }
    };

    const onNativeTouchMove = (ev: TouchEvent) => {
      if (!handlersRef.current.interactive) return;
      ev.stopPropagation();
      ev.preventDefault();
      lastTouchHandledAtRef.current = Date.now();
      if (ev.touches.length >= 2) {
        if (gestureRef.current?.type !== "pinch") {
          handlersRef.current.beginPinchGesture(
            ev.touches[0].clientX,
            ev.touches[0].clientY,
            ev.touches[1].clientX,
            ev.touches[1].clientY
          );
        } else {
          handlersRef.current.movePinchGesture(
            ev.touches[0].clientX,
            ev.touches[0].clientY,
            ev.touches[1].clientX,
            ev.touches[1].clientY
          );
        }
      } else if (ev.touches.length === 1) {
        handlersRef.current.moveSingleGesture(ev.touches[0].clientX, ev.touches[0].clientY);
      }
    };

    const onNativeTouchEnd = (ev: TouchEvent) => {
      if (!handlersRef.current.interactive) return;
      ev.stopPropagation();
      lastTouchHandledAtRef.current = Date.now();
      if (ev.touches.length === 0) {
        void handlersRef.current.endGesture();
      }
    };

    el.addEventListener("touchstart", onNativeTouchStart, { passive: false });
    el.addEventListener("touchmove", onNativeTouchMove, { passive: false });
    el.addEventListener("touchend", onNativeTouchEnd, { passive: false });
    el.addEventListener("touchcancel", onNativeTouchEnd, { passive: false });

    return () => {
      el.removeEventListener("touchstart", onNativeTouchStart);
      el.removeEventListener("touchmove", onNativeTouchMove);
      el.removeEventListener("touchend", onNativeTouchEnd);
      el.removeEventListener("touchcancel", onNativeTouchEnd);
    };
  }, [enabled]);

  const wheelAccumRef = useRef<{ targetDx: number; targetDy: number; xRatio: number; yRatio: number; raf: number; lastWheelAt: number; isTouchpadStream: boolean }>({
    targetDx: 0,
    targetDy: 0,
    xRatio: 0.5,
    yRatio: 0.5,
    raf: 0,
    lastWheelAt: 0,
    isTouchpadStream: false,
  });

  const stepSmoothWheelScroll = () => {
    const state = wheelAccumRef.current;
    const remX = state.targetDx;
    const remY = state.targetDy;

    if (Math.hypot(remX, remY) < 0.5) {
      if (Math.hypot(remX, remY) > 0.05) {
        queueCoalescedScrollInput(state.xRatio, state.yRatio, remX, remY);
      }
      state.targetDx = 0;
      state.targetDy = 0;
      state.raf = 0;
      return;
    }

    // Smooth critically-damped glide for discrete notched mouse wheels
    const stepX = remX * 0.42;
    const stepY = remY * 0.42;
    state.targetDx -= stepX;
    state.targetDy -= stepY;

    const { scrollTop, scrollHeight, clientHeight } = scrollMetricsRef.current;
    if (scrollHeight > clientHeight) {
      const nextTop = Math.max(0, Math.min(scrollHeight - clientHeight, scrollTop + stepY));
      applyScrollMetricsDom(nextTop, scrollHeight, clientHeight);
    }

    applyPredictiveScrollOffset(stepX, stepY);
    queueCoalescedScrollInput(state.xRatio, state.yRatio, stepX, stepY);

    if (Math.hypot(state.targetDx, state.targetDy) >= 0.5) {
      state.raf = requestAnimationFrame(stepSmoothWheelScroll);
    } else {
      if (Math.hypot(state.targetDx, state.targetDy) > 0.05) {
        queueCoalescedScrollInput(state.xRatio, state.yRatio, state.targetDx, state.targetDy);
      }
      state.targetDx = 0;
      state.targetDy = 0;
      state.raf = 0;
    }
  };

  const handleWheelScroll = (e: React.WheelEvent<HTMLDivElement>) => {
    if (!interactive) return;
    stopInertiaScroll();
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.12 : 0.89;
      const nextScale = Math.max(1, Math.min(3.5, zoomScaleRef.current * factor));
      zoomScaleRef.current = nextScale;
      if (nextScale <= 1.02) {
        zoomPanRef.current = { x: 0, y: 0 };
      }
      applyZoomTransformDom();
      return;
    }

    const coords = computeNormalizedCoords(e.clientX, e.clientY) || { xRatio: 0.5, yRatio: 0.5 };
    // Normalize deltaMode (1 = lines -> ~36px, 2 = pages -> ~720px, 0 = pixels)
    const modeMultiplier = e.deltaMode === 1 ? 36 : e.deltaMode === 2 ? 720 : 1;
    const rawDx = (e.shiftKey && Math.abs(e.deltaX) < 1 ? e.deltaY : e.deltaX) * modeMultiplier;
    const rawDy = (e.shiftKey && Math.abs(e.deltaX) < 1 ? 0 : e.deltaY) * modeMultiplier;

    const now = performance.now();
    const state = wheelAccumRef.current;
    const dt = now - state.lastWheelAt;
    state.lastWheelAt = now;

    // Detect precision touchpad stream: pixel mode (deltaMode === 0) with high frequency (< 34ms), fractional deltas, 2D pan, or small steps (< 64px)
    const hasFractionalDelta = !Number.isInteger(e.deltaX) || !Number.isInteger(e.deltaY);
    const has2DPan = Math.abs(e.deltaX) > 0 && Math.abs(e.deltaY) > 0;
    const isLikelyTouchpad =
      e.deltaMode === 0 &&
      (hasFractionalDelta ||
        has2DPan ||
        Math.hypot(rawDx, rawDy) < 64 ||
        (dt < 34 && state.isTouchpadStream));
    state.isTouchpadStream = isLikelyTouchpad;

    if (isLikelyTouchpad) {
      // Zero-lag 1:1 pass-through for precision touchpad (no double-smoothing rAF interpolation on top of native OS trackpad inertia!)
      if (state.raf) {
        cancelAnimationFrame(state.raf);
        state.raf = 0;
      }
      const totalDx = state.targetDx + rawDx;
      const totalDy = state.targetDy + rawDy;
      state.targetDx = 0;
      state.targetDy = 0;
      const { scrollTop, scrollHeight, clientHeight } = scrollMetricsRef.current;
      if (scrollHeight > clientHeight && Math.abs(totalDy) > 0.05) {
        const nextTop = Math.max(0, Math.min(scrollHeight - clientHeight, scrollTop + totalDy));
        applyScrollMetricsDom(nextTop, scrollHeight, clientHeight);
      }
      applyPredictiveScrollOffset(totalDx, totalDy);
      queueCoalescedScrollInput(coords.xRatio, coords.yRatio, totalDx, totalDy);
      return;
    }

    state.targetDx += rawDx;
    state.targetDy += rawDy;
    state.xRatio = coords.xRatio;
    state.yRatio = coords.yRatio;

    if (!state.raf) {
      state.raf = requestAnimationFrame(stepSmoothWheelScroll);
    }
  };

  if (!enabled) return null;
  return (
    <div
      ref={viewportBoxRef}
      data-no-swipe="true"
      tabIndex={interactive ? 0 : -1}
      onPointerDown={(e) => {
        if (!interactive) return;
        flushImeProxyDiffImmediate();
        if (remoteCursorStyleRef.current === "text") {
          lastRemoteTextFocusAtRef.current = Date.now();
        }
        const shouldFocusImmediately =
          e.pointerType === "mouse" &&
          (remoteCursorStyleRef.current === "text" ||
            remoteCursorStyleRef.current === "vertical-text" ||
            remoteEditableFocusRef.current.editable);
        if (shouldFocusImmediately) {
          focusImeProxy();
        }
        resetImeProxyBuffer();
        if (e.pointerType === "touch" && Date.now() - lastTouchHandledAtRef.current < 400) return;

        if (e.pointerType === "mouse" && mobileInputMode === "mouse") {
          const coords = computeNormalizedCoords(e.clientX, e.clientY);
          if (coords) {
            cursorNormRef.current = { x: coords.xRatio, y: coords.yRatio };
            applyCursorDom();
          }
        }

        try { e.currentTarget.setPointerCapture(e.pointerId); } catch {}
        activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
        const pts = Array.from(activePointersRef.current.values());
        if (pts.length >= 2) {
          beginPinchGesture(pts[0].x, pts[0].y, pts[1].x, pts[1].y);
        } else if (pts.length === 1) {
          beginSingleGesture(e.clientX, e.clientY, e.pointerType || "mouse");
        }
      }}
      onPointerMove={(e) => {
        if (!interactive) return;
        if (e.pointerType === "touch" && Date.now() - lastTouchHandledAtRef.current < 400) return;

        if (!activePointersRef.current.has(e.pointerId)) {
          if (e.pointerType === "mouse") {
            const coords = computeNormalizedCoords(e.clientX, e.clientY);
            if (coords) {
              if (mobileInputMode === "mouse") {
                cursorNormRef.current = { x: coords.xRatio, y: coords.yRatio };
                applyCursorDom();
              }
              const now = Date.now();
              if (now - lastHoverMoveSentAtRef.current >= 16) {
                lastHoverMoveSentAtRef.current = now;
                void sendRealtimeInput({
                  action: "move",
                  xRatio: coords.xRatio,
                  yRatio: coords.yRatio,
                  pageId,
                });
              }
            }
          }
          return;
        }

        activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
        const pts = Array.from(activePointersRef.current.values());
        if (pts.length >= 2) {
          if (gestureRef.current?.type !== "pinch") {
            beginPinchGesture(pts[0].x, pts[0].y, pts[1].x, pts[1].y);
          } else {
            movePinchGesture(pts[0].x, pts[0].y, pts[1].x, pts[1].y);
          }
        } else if (pts.length === 1) {
          moveSingleGesture(e.clientX, e.clientY);
        }
      }}
      onPointerUp={(e) => {
        if (!interactive) return;
        try { e.currentTarget.releasePointerCapture(e.pointerId); } catch {}
        activePointersRef.current.delete(e.pointerId);
        if (e.pointerType === "touch" && Date.now() - lastTouchHandledAtRef.current < 400) return;
        if (activePointersRef.current.size === 0) {
          void endGesture(e.clientX, e.clientY);
        }
      }}
      onPointerCancel={(e) => {
        activePointersRef.current.delete(e.pointerId);
        if (activePointersRef.current.size === 0) {
          gestureRef.current = null;
        }
      }}
      onWheel={handleWheelScroll}
      onDoubleClick={(e) => {
        if (!interactive) return;
        const coords = computeNormalizedCoords(e.clientX, e.clientY);
        if (coords) {
          void sendRealtimeInput({
            action: "dblclick",
            xRatio: coords.xRatio,
            yRatio: coords.yRatio,
            pageId,
          });
        }
      }}
      onContextMenu={(e) => {
        if (!interactive) return;
        e.preventDefault();
        const coords = computeNormalizedCoords(e.clientX, e.clientY);
        if (coords) {
          void sendRealtimeInput({
            action: "rightclick",
            xRatio: coords.xRatio,
            yRatio: coords.yRatio,
            pageId,
          });
        }
      }}
      onCopy={async (e) => {
        if (!interactive) return;
        // Native browser copy event inside viewport
        e.preventDefault();
        await sendRealtimeInput({ action: "key", key: "c", modifiers: 2, pageId });
      }}
      onCut={async (e) => {
        if (!interactive) return;
        e.preventDefault();
        await sendRealtimeInput({ action: "key", key: "x", modifiers: 2, pageId });
      }}
      onPaste={async (e) => {
        if (!interactive) return;
        const pasted = e.clipboardData?.getData("text");
        if (pasted) {
          e.preventDefault();
          lastRemoteTextFocusAtRef.current = Date.now();
          await sendRealtimeInput({ action: "type", text: pasted, pageId });
          resetImeProxyBuffer();
        }
      }}
      onKeyDown={async (e) => {
        if (!interactive) return;
        const nativeEv = e.nativeEvent as KeyboardEvent;
        // Let the hidden IME proxy textarea handle active IME composition or OS-synthesized 229/Process events without interfering
        if (imeComposingRef.current || nativeEv.isComposing || e.key === "Process" || nativeEv.keyCode === 229) {
          return;
        }

        const isEditingTextContext =
          remoteCursorStyleRef.current === "text" ||
          remoteCursorStyleRef.current === "vertical-text" ||
          Date.now() - lastRemoteTextFocusAtRef.current < 15000;

        const cdpMods =
          (e.altKey ? 1 : 0) |
          (e.ctrlKey ? 2 : 0) |
          (e.metaKey ? 4 : 0) |
          (e.shiftKey ? 8 : 0);

        // 1. Browser Wrapper Keyboard Shortcuts (Ctrl/Cmd + T/W/L/R/F/+/-/0, Alt + Left/Right, F5)
        if (e.ctrlKey || e.metaKey) {
          flushImeProxyDiffImmediate();
          const kLower = e.key.toLowerCase();
          if (kLower === "l") {
            e.preventDefault();
            onBrowserShortcut?.("focus_address");
            return;
          }
          if (kLower === "r") {
            e.preventDefault();
            onBrowserShortcut?.("reload");
            return;
          }
          if (kLower === "f") {
            e.preventDefault();
            onBrowserShortcut?.("find");
            return;
          }
          if (kLower === "t") {
            e.preventDefault();
            onBrowserShortcut?.("new_tab");
            return;
          }
          if (kLower === "w") {
            e.preventDefault();
            onBrowserShortcut?.("close_tab");
            return;
          }
          if (e.key === "=" || e.key === "+") {
            e.preventDefault();
            onZoomStep?.(15);
            return;
          }
          if (e.key === "-") {
            e.preventDefault();
            onZoomStep?.(-15);
            return;
          }
          if (e.key === "0") {
            e.preventDefault();
            onZoomStep?.("reset");
            return;
          }
          if (kLower === "c") {
            // Forward Ctrl+C (Copy) to active tab & sync to local client clipboard if text is selected
            e.preventDefault();
            triggerHaptic(8);
            await sendRealtimeInput({ action: "key", key: "c", modifiers: 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (kLower === "v") {
            // Forward Ctrl+V (Paste): read local clipboard and insert into active browser target
            e.preventDefault();
            triggerHaptic(8);
            lastRemoteTextFocusAtRef.current = Date.now();
            try {
              if (navigator.clipboard?.readText) {
                const clipText = await navigator.clipboard.readText();
                if (clipText) {
                  await sendRealtimeInput({ action: "type", text: clipText, pageId });
                  resetImeProxyBuffer();
                  return;
                }
              }
            } catch {}
            await sendRealtimeInput({ action: "key", key: "v", modifiers: 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (kLower === "x") {
            e.preventDefault();
            triggerHaptic(8);
            lastRemoteTextFocusAtRef.current = Date.now();
            await sendRealtimeInput({ action: "key", key: "x", modifiers: 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (kLower === "a") {
            e.preventDefault();
            await sendRealtimeInput({ action: "key", key: "a", modifiers: 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (kLower === "z") {
            e.preventDefault();
            lastRemoteTextFocusAtRef.current = Date.now();
            await sendRealtimeInput({ action: "key", key: "z", modifiers: e.shiftKey ? 10 : 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (kLower === "y") {
            e.preventDefault();
            lastRemoteTextFocusAtRef.current = Date.now();
            await sendRealtimeInput({ action: "key", key: "y", modifiers: 2, pageId });
            resetImeProxyBuffer();
            return;
          }
          if (e.key === "Backspace" || e.key === "Delete" || e.key === "ArrowLeft" || e.key === "ArrowRight" || e.key === "Home" || e.key === "End") {
            e.preventDefault();
            lastRemoteTextFocusAtRef.current = Date.now();
            await sendRealtimeInput({ action: "key", key: e.key, modifiers: cdpMods, pageId });
            resetImeProxyBuffer();
            return;
          }
        }
        if (e.key === "F5") {
          e.preventDefault();
          onBrowserShortcut?.("reload");
          return;
        }
        if (e.altKey && (e.key === "ArrowLeft" || e.key === "ArrowRight")) {
          e.preventDefault();
          onBrowserShortcut?.(e.key === "ArrowLeft" ? "back" : "forward");
          return;
        }

        // 2. Space / Shift+Space Page Down / Page Up ONLY when NOT in an editing text context
        if ((e.key === " " || e.code === "Space") && !isEditingTextContext) {
          e.preventDefault();
          const pageDelta = e.shiftKey ? -520 : 520;
          wheelAccumRef.current.targetDy += pageDelta;
          wheelAccumRef.current.xRatio = 0.5;
          wheelAccumRef.current.yRatio = 0.5;
          if (!wheelAccumRef.current.raf) {
            wheelAccumRef.current.raf = requestAnimationFrame(stepSmoothWheelScroll);
          }
          return;
        }

        // 3. Navigation & Editing Keys
        if (["Enter", "Backspace", "Escape", "Tab", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Delete", "Home", "End", "PageUp", "PageDown"].includes(e.key)) {
          // If Backspace is pressed while focus is on our hidden IME proxy textarea AND the textarea still has characters to delete, let the textarea native input handler diff and process it so Vietnamese IME (Windows VIE / Unikey / EVKey) Backspace+replacement sequences stay 100% atomic!
          if (e.key === "Backspace" && !e.ctrlKey && !e.metaKey && !e.altKey) {
            const proxyEl = imeProxyRef.current;
            if (proxyEl && document.activeElement === proxyEl && proxyEl.value.length > 0 && (proxyEl.selectionStart ?? proxyEl.value.length) > 0) {
              return;
            }
            e.preventDefault();
            lastRemoteTextFocusAtRef.current = Date.now();
            flushImeProxyDiffImmediate();
            enqueueOrderedInput(async () => {
              await sendRealtimeInput({ action: "key", key: "Backspace", pageId });
              resetImeProxyBuffer();
            });
            return;
          }
          flushImeProxyDiffImmediate();
          e.preventDefault();
          if (e.key === "Escape") {
            lastRemoteTextFocusAtRef.current = 0;
            await sendRealtimeInput({ action: "key", key: "Escape", modifiers: cdpMods, pageId });
          } else if (e.key === "Home" && !isEditingTextContext && !e.shiftKey) {
            await sendRealtimeInput({ action: "scroll_to", yRatio: 0, pageId });
          } else if (e.key === "End" && !isEditingTextContext && !e.shiftKey) {
            await sendRealtimeInput({ action: "scroll_to", yRatio: 1, pageId });
          } else if (e.key === "PageDown" || (e.key === "ArrowDown" && !isEditingTextContext && !e.shiftKey)) {
            wheelAccumRef.current.targetDy += e.key === "PageDown" ? 520 : 140;
            wheelAccumRef.current.xRatio = 0.5;
            wheelAccumRef.current.yRatio = 0.5;
            if (!wheelAccumRef.current.raf) {
              wheelAccumRef.current.raf = requestAnimationFrame(stepSmoothWheelScroll);
            }
          } else if (e.key === "PageUp" || (e.key === "ArrowUp" && !isEditingTextContext && !e.shiftKey)) {
            wheelAccumRef.current.targetDy += e.key === "PageUp" ? -520 : -140;
            wheelAccumRef.current.xRatio = 0.5;
            wheelAccumRef.current.yRatio = 0.5;
            if (!wheelAccumRef.current.raf) {
              wheelAccumRef.current.raf = requestAnimationFrame(stepSmoothWheelScroll);
            }
          } else if (e.key === "ArrowLeft" && !isEditingTextContext && !e.shiftKey) {
            wheelAccumRef.current.targetDx -= 140;
            if (!wheelAccumRef.current.raf) {
              wheelAccumRef.current.raf = requestAnimationFrame(stepSmoothWheelScroll);
            }
          } else if (e.key === "ArrowRight" && !isEditingTextContext && !e.shiftKey) {
            wheelAccumRef.current.targetDx += 140;
            if (!wheelAccumRef.current.raf) {
              wheelAccumRef.current.raf = requestAnimationFrame(stepSmoothWheelScroll);
            }
          } else {
            enqueueOrderedInput(async () => {
              await sendRealtimeInput({ action: "key", key: e.key, modifiers: cdpMods, pageId });
              resetImeProxyBuffer();
            });
          }
          return;
        }

        // 4. Printable character typing: if the hidden IME proxy textarea is focused, let the native browser input/composition pipeline handle character & Vietnamese diacritic insertion without duplicate keyDown typing!
        if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
          lastRemoteTextFocusAtRef.current = Date.now();
          if (document.activeElement === imeProxyRef.current) {
            return;
          }
          focusImeProxy();
          const proxyEl = imeProxyRef.current;
          if (proxyEl) {
            e.preventDefault();
            const cur = proxyEl.value || IME_PROXY_PAD;
            proxyEl.value = cur + e.key;
            try { proxyEl.setSelectionRange(proxyEl.value.length, proxyEl.value.length); } catch {}
            flushImeProxyDiff(proxyEl, false);
            return;
          }
          e.preventDefault();
          enqueueOrderedInput(async () => {
            await sendRealtimeInput({ action: "type", text: e.key, pageId });
          });
        }
      }}
      className="relative w-full h-full overflow-hidden flex items-center justify-center bg-[#FFFDF9] dark:bg-[#0a0a0f] outline-none select-none touch-none"
    >
      {interactive && (
        <textarea
          ref={imeProxyRef}
          data-testid="agent-browser-ime-proxy"
          aria-label="Browser keyboard and Vietnamese IME input proxy"
          defaultValue={IME_PROXY_PAD}
          autoCapitalize="off"
          autoComplete="off"
          autoCorrect="off"
          spellCheck={false}
          rows={1}
          onCompositionStart={() => {
            imeComposingRef.current = true;
            lastRemoteTextFocusAtRef.current = Date.now();
          }}
          lang="vi"
          inputMode="text"
          onCompositionEnd={(e) => {
            imeComposingRef.current = false;
            lastRemoteTextFocusAtRef.current = Date.now();
            flushImeProxyDiff(e.currentTarget, true);
          }}
          onInput={(e) => {
            if (imeComposingRef.current || (e.nativeEvent as InputEvent).isComposing) {
              return;
            }
            lastRemoteTextFocusAtRef.current = Date.now();
            flushImeProxyDiff(e.currentTarget, false);
          }}
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: "24px",
            height: "24px",
            opacity: 0.001,
            fontSize: "16px",
            lineHeight: "20px",
            color: "transparent",
            background: "transparent",
            caretColor: "transparent",
            padding: 0,
            border: 0,
            outline: "none",
            resize: "none",
            overflow: "hidden",
            pointerEvents: "none",
            zIndex: 0,
          }}
        />
      )}
      <div
        ref={zoomWrapperRef}
        style={{ transformOrigin: "center center", willChange: "transform" }}
        className={`relative w-full h-full flex items-center justify-center pointer-events-none ${hasFrame ? "" : "hidden"}`}
      >
        <canvas
          ref={canvasRef}
          data-testid="agent-browser-gpu-canvas"
          style={{
            display: "none",
            imageRendering: "-webkit-optimize-contrast",
            willChange: "contents",
          }}
          className={`select-none z-[12] block w-full h-full ${interactive ? "object-fill" : "object-contain"} [backface-visibility:hidden] [transform:translateZ(0)] pointer-events-none`}
        />
        <img
          ref={imgRef}
          src={currentSrcRef.current || undefined}
          alt="Agent browser preview"
          decoding="sync"
          draggable={false}
          onLoad={(e) => {
            const el = e.currentTarget;
            if (el.naturalWidth > 0 && el.naturalHeight > 0) {
              naturalDimsRef.current = { w: el.naturalWidth, h: el.naturalHeight };
            }
            if (mobileInputMode === "mouse") applyCursorDom();
          }}
          style={{
            imageRendering: "-webkit-optimize-contrast",
            willChange: "contents",
          }}
          className={`select-none z-[12] block w-full h-full ${interactive ? "object-fill" : "object-contain"} [backface-visibility:hidden] [transform:translateZ(0)] pointer-events-none`}
        />

        {/* Virtual Mouse Pointer Overlay when in Mouse Mode (Direct DOM position & shape update -> 0 React re-renders!) */}
        {mobileInputMode === "mouse" && (
          <div
            ref={cursorElRef}
            data-testid="virtual-mouse-cursor"
            data-cursor-kind={remoteCursorStyleRef.current}
            style={{
              left: "50%",
              top: "50%",
              willChange: "left, top",
            }}
            className="pointer-events-none absolute z-40 drop-shadow-[0_2px_6px_rgba(0,0,0,0.85)]"
          >
            {/* Default Arrow Cursor */}
            <svg data-cursor-shape="arrow" width="22" height="22" viewBox="0 0 24 24" fill="none" style={{ display: "block" }}>
              <path
                d="M1 1L8.5 18L11.2 11.2L18 8.5L1 1Z"
                fill="#ffffff"
                stroke="#111827"
                strokeWidth="2"
                strokeLinejoin="round"
              />
            </svg>
            {/* Link / Button Pointer Hand Cursor */}
            <svg data-cursor-shape="pointer" width="22" height="22" viewBox="0 0 24 24" fill="none" style={{ display: "none" }}>
              <path
                d="M9 11V4.5C9 3.67 9.67 3 10.5 3C11.33 3 12 3.67 12 4.5V10H13.5C14.33 10 15 10.67 15 11.5V10.5C15 9.67 15.67 9 16.5 9C17.33 9 18 9.67 18 10.5V11.5C18 10.67 18.67 10 19.5 10C20.33 10 21 10.67 21 11.5V16C21 19.31 18.31 22 15 22H12.5C10.5 22 8.8 20.9 7.8 19.2L4.4 13.8C3.9 13 4.1 12 4.9 11.5C5.7 11 6.7 11.2 7.2 12L9 14.5V11Z"
                fill="#ffffff"
                stroke="#1a73e8"
                strokeWidth="1.8"
                strokeLinejoin="round"
              />
            </svg>
            {/* Text Input I-Beam Cursor */}
            <svg data-cursor-shape="text" width="20" height="22" viewBox="0 0 24 24" fill="none" style={{ display: "none" }}>
              <path
                d="M8 4H16M8 20H16M12 4V20"
                stroke="#ffffff"
                strokeWidth="3.2"
                strokeLinecap="round"
              />
              <path
                d="M8 4H16M8 20H16M12 4V20"
                stroke="#111827"
                strokeWidth="1.6"
                strokeLinecap="round"
              />
            </svg>
          </div>
        )}
      </div>

      {/* Interactive Synchronized Browser Scrollbar Overlay (Click track or drag thumb for instant 60fps scrolling) */}
      {interactive && (
        <div
          ref={scrollbarTrackRef}
          data-testid="agent-browser-interactive-scrollbar"
          style={{ opacity: 0, pointerEvents: "none" }}
          onPointerDown={(e) => {
            e.stopPropagation();
            e.preventDefault();
            stopInertiaScroll();
            const trackEl = scrollbarTrackRef.current;
            const thumbEl = scrollbarThumbRef.current;
            if (!trackEl || !thumbEl) return;
            try { trackEl.setPointerCapture(e.pointerId); } catch {}
            const trackRect = trackEl.getBoundingClientRect();
            const thumbRect = thumbEl.getBoundingClientRect();
            if (trackRect.height <= 0) return;

            const isClickOnThumb = e.clientY >= thumbRect.top - 4 && e.clientY <= thumbRect.bottom + 4;
            const usableTrack = Math.max(1, trackRect.height - thumbRect.height);
            let startRatio = (thumbRect.top - trackRect.top) / usableTrack;

            const rawYRatio = Math.max(0, Math.min(1, (e.clientY - trackRect.top) / Math.max(1, trackRect.height)));
            void sendRealtimeInput({
              action: "mousedown",
              xRatio: 0.995,
              yRatio: rawYRatio,
              pageId,
            });

            if (!isClickOnThumb) {
              // Jump thumb center to clicked track position
              const targetThumbTop = Math.max(0, Math.min(usableTrack, e.clientY - trackRect.top - thumbRect.height / 2));
              startRatio = targetThumbTop / usableTrack;
              const { scrollHeight, clientHeight } = scrollMetricsRef.current;
              if (scrollHeight > clientHeight) {
                applyScrollMetricsDom(startRatio * (scrollHeight - clientHeight), scrollHeight, clientHeight);
              }
              void sendRealtimeInput({
                action: "scroll_to",
                yRatio: Math.max(0, Math.min(1, startRatio)),
                pageId,
              });
            }

            scrollbarDragRef.current = {
              active: true,
              pointerId: e.pointerId,
              startY: e.clientY,
              startRatio: Math.max(0, Math.min(1, startRatio)),
              lastSentAt: performance.now(),
            };
          }}
          onPointerMove={(e) => {
            const drag = scrollbarDragRef.current;
            if (!drag.active || drag.pointerId !== e.pointerId) return;
            e.stopPropagation();
            e.preventDefault();
            const trackEl = scrollbarTrackRef.current;
            const thumbEl = scrollbarThumbRef.current;
            if (!trackEl || !thumbEl) return;
            const trackRect = trackEl.getBoundingClientRect();
            const thumbRect = thumbEl.getBoundingClientRect();
            const usableTrack = Math.max(1, trackRect.height - thumbRect.height);
            const deltaRatio = (e.clientY - drag.startY) / usableTrack;
            const nextRatio = Math.max(0, Math.min(1, drag.startRatio + deltaRatio));
            const rawYRatio = Math.max(0, Math.min(1, (e.clientY - trackRect.top) / Math.max(1, trackRect.height)));

            const { scrollHeight, clientHeight } = scrollMetricsRef.current;
            if (scrollHeight > clientHeight) {
              applyScrollMetricsDom(nextRatio * (scrollHeight - clientHeight), scrollHeight, clientHeight);
            }

            const now = performance.now();
            if (now - drag.lastSentAt >= 12) {
              drag.lastSentAt = now;
              void sendRealtimeInput({
                action: "mousemove_drag",
                xRatio: 0.995,
                yRatio: rawYRatio,
                pageId,
              });
              void sendRealtimeInput({
                action: "scroll_to",
                yRatio: nextRatio,
                pageId,
              });
            }
          }}
          onPointerUp={(e) => {
            const drag = scrollbarDragRef.current;
            if (!drag.active || drag.pointerId !== e.pointerId) return;
            e.stopPropagation();
            try { scrollbarTrackRef.current?.releasePointerCapture(e.pointerId); } catch {}
            scrollbarDragRef.current.active = false;
            const trackEl = scrollbarTrackRef.current;
            const thumbEl = scrollbarThumbRef.current;
            if (trackEl && thumbEl) {
              const trackRect = trackEl.getBoundingClientRect();
              const thumbRect = thumbEl.getBoundingClientRect();
              const usableTrack = Math.max(1, trackRect.height - thumbRect.height);
              const finalRatio = Math.max(0, Math.min(1, drag.startRatio + (e.clientY - drag.startY) / usableTrack));
              const rawYRatio = Math.max(0, Math.min(1, (e.clientY - trackRect.top) / Math.max(1, trackRect.height)));
              void sendRealtimeInput({
                action: "mouseup",
                xRatio: 0.995,
                yRatio: rawYRatio,
                pageId,
              });
              void sendRealtimeInput({
                action: "scroll_to",
                yRatio: finalRatio,
                pageId,
              });
            }
          }}
          onPointerCancel={(e) => {
            if (scrollbarDragRef.current.pointerId === e.pointerId) {
              scrollbarDragRef.current.active = false;
            }
          }}
          className="group/sbar absolute top-0 right-0 bottom-0 w-4 bg-transparent z-30 cursor-pointer select-none touch-none"
          title="Kéo hoặc nhấp để cuộn trang (Scrollbar)"
        >
          <div
            ref={scrollbarThumbRef}
            data-testid="agent-browser-scrollbar-thumb"
            style={{ top: "0%", height: "25%" }}
            className="absolute left-0 right-0 min-h-[28px] bg-transparent pointer-events-none"
          />
        </div>
      )}

      {!hasFrame && (
        <div className="absolute inset-0 flex items-center justify-center text-[12px] font-mono text-[#78716c] dark:text-neutral-500 bg-[#FFFDF9] dark:bg-[#0c0c12] pointer-events-none select-none z-[12]">
          {failures > 0 ? "Đang kết nối trình duyệt của Agent…" : "Đang tải trang web…"}
        </div>
      )}
    </div>
  );
}

interface QuickSuggestion {
  title: string;
  desc: string;
  prompt: string;
  badge?: string;
}

// Dynamically generate 4 tailored quick prompt suggestions based on agent role, tools, and node placement
// Helper to extract clean/friendly short name from full agent name (e.g. 'GM Bốc (Executive)' -> 'Bốc')
function getCleanAgentShortName(agent?: InfraAgent): string {
  if (!agent?.name) return 'Agent';
  const raw = agent.name.split('(')[0].trim();
  if (raw.toUpperCase().startsWith('GM ')) {
    return raw.slice(3).trim();
  }
  return raw;
}



// Dynamic task suggestions based on agent role and capabilities (concise, office-focused)
function getDynamicSuggestionsForAgent(agent?: InfraAgent): QuickSuggestion[] {
  const role = (agent?.roleTag || "").toLowerCase();
  const id = (agent?.id || "").toLowerCase();
  const slug = (agent?.slug || "").toLowerCase();
  const name = (agent?.name || "").toLowerCase();
  const tools = (agent?.tools || []).map((t: any) => (typeof t === "string" ? t : t.name || "").toLowerCase());

  // Business & Accounting / ERP (GM Bốc, Gạo, Lúa, Sales, ERPCore)
  const isErp = tools.some((t: string) => t.includes("erpcore") || t.includes("invoice") || t.includes("order")) ||
    id.includes("gm-") || slug.includes("gm-") || name.includes("bốc") || name.includes("gạo") || name.includes("lúa") || name.includes("gm") || role.includes("finance");
  if (isErp) {
    return [
      {
        title: "Báo cáo doanh số",
        desc: "Tổng hợp doanh thu và đơn hàng hôm nay",
        prompt: "Lập báo cáo tổng hợp doanh thu và danh sách đơn hàng xuất bán hôm nay.",
        badge: "Báo cáo"
      },
      {
        title: "Đối chiếu công nợ",
        desc: "Rà soát công nợ khách hàng sắp đến hạn",
        prompt: "Kiểm tra và đối chiếu các khoản công nợ của khách hàng sắp đến hạn thanh toán.",
        badge: "Kế toán"
      },
      {
        title: "Kiểm tra tồn kho",
        desc: "Tra cứu lượng tồn và số đã xuất giao",
        prompt: "Kiểm tra số lượng tồn kho các mặt hàng chủ lực và danh sách phiếu xuất trong tuần.",
        badge: "Kho vận"
      }
    ];
  }

  // Creative & Market Research (Climax, Zen, Media, Content)
  const isCreative = role.includes("research") || role.includes("creative") || id.includes("climax") || slug.includes("climax") || id.includes("zen") || slug.includes("zen");
  if (isCreative) {
    return [
      {
        title: "Nghiên cứu thị trường",
        desc: "Phân tích xu hướng và đối thủ cạnh tranh",
        prompt: "Phân tích xu hướng nổi bật của thị trường và các điểm mạnh của đối thủ cạnh tranh trong tuần này.",
        badge: "Nghiên cứu"
      },
      {
        title: "Lên ý tưởng bài viết",
        desc: "Gợi ý góc nhìn và thông điệp truyền thông",
        prompt: "Đề xuất 3 chủ đề bài viết và thông điệp truyền thông thu hút cho kênh mạng xã hội tuần tới.",
        badge: "Nội dung"
      },
      {
        title: "Tóm tắt tin tức ngành",
        desc: "Trích xuất thông tin trọng tâm",
        prompt: "Tổng hợp và tóm tắt ngắn gọn các tin tức công nghệ và tự động hóa đáng chú ý trong ngày.",
        badge: "Tổng hợp"
      }
    ];
  }

  // Operations & Tech / Product (Mons, Ken, QA, SRE)
  const isOps = role.includes("engineering") || role.includes("dev") || id.includes("mons") || id.includes("ken") || id.includes("qa");
  if (isOps) {
    return [
      {
        title: "Rà soát tiến độ",
        desc: "Kiểm tra backlog và đầu việc ưu tiên",
        prompt: "Rà soát các đầu việc đang xử lý trong sprint và liệt kê danh sách việc cần ưu tiên hôm nay.",
        badge: "Tiến độ"
      },
      {
        title: "Kiểm tra trạng thái",
        desc: "Kiểm tra vận hành và thông báo lỗi",
        prompt: "Kiểm tra trạng thái hoạt động của hệ thống, ghi nhận các cảnh báo hoặc dịch vụ gặp sự cố.",
        badge: "Vận hành"
      },
      {
        title: "Phân công nhiệm vụ",
        desc: "Lập checklist công việc cụ thể",
        prompt: "Lập bảng kế hoạch công việc và phân chia các mốc hoàn thành rõ ràng cho dự án.",
        badge: "Kế hoạch"
      }
    ];
  }

  // Default Office & Generalist (Mkai, Assistant, Office tasks)
  return [
    {
      title: "Soạn thảo văn bản",
      desc: "Soạn email thông báo hoặc thư mời họp",
      prompt: "Soạn thảo email thông báo kế hoạch làm việc tuần mới gửi nội bộ, văn phong lịch sự và rõ ràng.",
      badge: "Văn bản"
    },
    {
      title: "Tóm tắt tài liệu",
      desc: "Trích xuất ý chính và đầu việc cần làm",
      prompt: "Tóm tắt ngắn gọn nội dung cốt lõi của tài liệu này và liệt kê các hành động cần thực hiện.",
      badge: "Tóm tắt"
    },
    {
      title: "Lập kế hoạch tuần",
      desc: "Sắp xếp thứ tự ưu tiên các mục tiêu",
      prompt: "Giúp tôi lập lịch trình làm việc và phân chia thời gian cho các mục tiêu trọng tâm trong tuần.",
      badge: "Kế hoạch"
    }
  ];
}

// Helper to accurately distinguish between mobile touch screens and laptops (including touch laptops / trackpads)
function isCoarseTouchDevice(): boolean {
  if (typeof window === "undefined") return false;
  // Primary pointer is coarse (finger) or no fine pointer (mouse/trackpad) and screen width < 1024
  const hasCoarse = window.matchMedia("(pointer: coarse)").matches;
  const hasFine = window.matchMedia("(pointer: fine)").matches;
  const isSmallScreen = window.innerWidth < 1024;
  return isSmallScreen || (hasCoarse && !hasFine);
}


// Touch-only phones/tablets (no mouse/trackpad): the virtual keyboard's Enter key inserts a newline; sending uses the Send button.
function isTouchOnlyKeyboardDevice(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches && !window.matchMedia("(any-pointer: fine)").matches;
}

function parseChatTimestamp(ts?: string): Date | null {
  if (!ts) return null;
  const d = new Date(ts);
  if (!isNaN(d.getTime())) return d;
  const m = String(ts).trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i);
  if (m) {
    let hours = parseInt(m[1], 10);
    const minutes = parseInt(m[2], 10);
    const meridiem = m[3]?.toUpperCase();
    if (meridiem === "PM" && hours < 12) hours += 12;
    if (meridiem === "AM" && hours === 12) hours = 0;
    const now = new Date();
    now.setHours(hours, minutes, 0, 0);
    return now;
  }
  return null;
}


function formatChatTimestampDivider(ts?: string, lang?: string): string {
  const d = parseChatTimestamp(ts);
  if (!d) return ts ? String(ts) : "";
  const effectiveLang = (lang || (typeof document !== "undefined" && document.documentElement.lang) || "vi").toLowerCase().startsWith("vi") ? "vi" : "en";
  const now = new Date();
  const isToday = d.toDateString() === now.toDateString();
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  const isYesterday = d.toDateString() === yesterday.toDateString();

  const timeStr = d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit", hour12: true });
  if (isToday) {
    return effectiveLang === "vi" ? `Hôm nay ${timeStr}` : `Today ${timeStr}`;
  }
  if (isYesterday) {
    return effectiveLang === "vi" ? `Hôm qua ${timeStr}` : `Yesterday ${timeStr}`;
  }
  return `${d.toLocaleDateString([], { month: "short", day: "numeric" })} ${timeStr}`;
}

function shouldShowChatTimestampDivider(prevTs?: string, currTs?: string): boolean {
  if (!currTs) return false;
  if (!prevTs) return true;
  const d1 = parseChatTimestamp(prevTs);
  const d2 = parseChatTimestamp(currTs);
  if (!d1 || !d2) return false;
  return Math.abs(d2.getTime() - d1.getTime()) >= 15 * 60 * 1000;
}

export interface QueuedRequestItem {
  id: string;
  text: string;
  previewText?: string;
  attachedFiles?: UploadedFileResult[];
  createdAt: number;
}

function useScrollBottomIndicator() {
  const [canScrollDown, setCanScrollDown] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const updateScrollState = () => {
    const el = scrollRef.current;
    if (!el) return;
    const hasOverflow = el.scrollHeight > el.clientHeight + 4;
    const isAtBottom = el.scrollHeight - el.scrollTop - el.clientHeight <= 10;
    setCanScrollDown(hasOverflow && !isAtBottom);
  };

  return { scrollRef, canScrollDown, updateScrollState };
}

